export const OVERLAYS = {"milk-meat-hygiene--milk-mastitis":{"milk-meat-hygiene--milk-mastitis--definition-of-mastitis":{"claims":[{"id":"milk-meat-hygiene--milk-mastitis--definition-of-mastitis--v1","statement":"Mastitis คือ inflammation ของ mammary gland (udder) ซึ่งโดยหลักเกิดจาก intramammary infection (IMI) และเป็นหนึ่งในโรคที่พบบ่อยที่สุดในโคนม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39694240","locator":"Vol 108, issue 4, pages 3917-3928; abstract, opening sentence","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mastitis, an inflammation of the udder primarily caused by an IMI, is one of the most common diseases in dairy cattle."}}]},"milk-meat-hygiene--milk-mastitis--process-of-infection-4-steps":{"claims":[{"id":"milk-meat-hygiene--milk-mastitis--process-of-infection-4-steps--v1","statement":"เชื้อเข้าสู่เต้านมผ่าน teat canal โดยมี keratin ภายใน teat canal ทำหน้าที่เป็นด่านป้องกัน การเปลี่ยนแปลง/รบกวน keratin สัมพันธ์กับจำนวน new intramammary infection ที่เปลี่ยนไป และ staphylococci สามารถ colonize keratin ใน teat canal ของ heifer ได้ตั้งแต่อายุประมาณ 9 เดือน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3319986","locator":"Vol 191, issue 11, pages 1484-1488; review abstract (teat-end defenses)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Alteration of teat canal keratin by method of intramammary drug infusion through the teat canal influenced the number of new infections. ... Staphylococci colonize teat canal keratin and lacteal secretions of dairy heifers as early as 9 mon"}},{"id":"milk-meat-hygiene--milk-mastitis--process-of-infection-4-steps--v2","statement":"Mastitis ทำให้ milk yield ลดลงและ milk composition เปลี่ยนแปลง โดยเชื้อก่อโรคทุกกลุ่มที่ศึกษา (Streptococcus spp., Staphylococcus aureus, coagulase-negative staphylococci, coliforms, fungi) ทำให้ SCC เพิ่มขึ้นอย่างมีนัยสำคัญ และทำให้ปริมาณ lactose ในน้ำนมลดลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30101726","locator":"Vol 85, issue 3, pages 309-316; abstract, results (3,149 dairy cows, 31 herds, Hokkaido)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All pathogens, in particular S. aureus and fungi, significantly increased SCC in both parity groups. All pathogens, especially CNS (in primipara) and S. aureus (in multipara), decreased lactose content."}}]},"milk-meat-hygiene--milk-mastitis--mastitis-classification-pathogen-list":{"claims":[{"id":"milk-meat-hygiene--milk-mastitis--mastitis-classification-pathogen-list--v1","statement":"Environmental mastitis เป็นรูปแบบที่พบบ่อยและสร้างความสูญเสียมากที่สุดในฟาร์มโคนมสมัยใหม่ที่ควบคุมการแพร่แบบ contagious ได้แล้ว โดยมูลโค สภาพแวดล้อมในโรงเรือน และแปลงหญ้าที่ใช้แล้วเป็นแหล่งสำคัญของเชื้อ เช่น Escherichia coli และ Streptococcus uberis อย่างไรก็ตาม การจัดกลุ่มเชื้อแบบ binary เป็น contagious หรือ environmental อาจทำให้เข้าใจผิดได้ โดยเฉพาะกับ Staphylococcus aureus, Streptococcus uberis และ streptococci อื่นรวมถึง Streptococcus agalactiae","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29083115","locator":"Vol 65 Suppl 1, pages 166-185; abstract (review)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Environmental mastitis can be caused by a wide range of bacterial species, and binary classification of species as contagious or environmental is misleading, particularly for Staphylococcus aureus, Streptococcus uberis and other streptococc"}},{"id":"milk-meat-hygiene--milk-mastitis--mastitis-classification-pathogen-list--v2","statement":"Subclinical mastitis นิยมนิยามด้วยเกณฑ์ somatic cell count (SCC) มากกว่า 200,000 cells/mL ที่ระดับ quarter","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30591327","locator":"Vol 102, issue 2, pages 1402-1416; abstract, methods (case definition)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Quarter somatic cell count (SCC) was measured using the reference method (DeLaval cell counter; De Laval International AB, Tumba, Sweden) with SCM defined as SCC >200,000 cells/mL."}},{"id":"milk-meat-hygiene--milk-mastitis--mastitis-classification-pathogen-list--v3","statement":"California Mastitis Test (CMT) เป็น cow-side test สำหรับคัดกรอง subclinical mastitis โดยประเมิน SCC ทางอ้อม เมื่อเทียบกับวิธีอ้างอิง Fossomatic cell count พบ sensitivity 81.0% และ specificity 92.9% และให้ผลตรงกับวิธีอ้างอิง 83.1% ของตัวอย่าง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37505872","locator":"Vol 10, issue 7, article 468; abstract, results (284 mixed milk samples, FSCC as gold standard)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The CMT matched with the FSCC in 83.1% of the samples ... The sensitivity and specificity reached 81.0% and 92.9% for the CMT"}}]},"milk-meat-hygiene--milk-mastitis--กลไกการติดเชื้อ-และรูปแบบของ-mastitis":{"claims":[{"id":"milk-meat-hygiene--milk-mastitis--กลไกการติดเชื้อ-และรูปแบบของ-mastitis--v1","statement":"Subclinical mastitis พบมากกว่า clinical mastitis อย่างชัดเจนในฟาร์มโคนม การสำรวจโคนม 305 ตัวพบ subclinical 33.8 เปอร์เซ็นต์ ขณะที่ clinical พบเพียง 3.6 เปอร์เซ็นต์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22476790","locator":"Abstract, Results; 44(7):1765-1771","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The overall prevalence of clinical and subclinical mastitis was 3.6 and 33.8 %, respectively."}}]},"milk-meat-hygiene--milk-mastitis--contagious-mastitis":{"claims":[{"id":"milk-meat-hygiene--milk-mastitis--contagious-mastitis--v1","statement":"Streptococcus agalactiae เป็น obligate pathogen ของเต้านม และกำจัดออกจากฝูงได้เร็วด้วยโปรแกรมเพาะเชื้อร่วมกับการรักษา ขณะที่ Staphylococcus aureus กระจายอยู่ตามร่างกายโคและสิ่งแวดล้อมด้วย และผลการรักษามักน่าผิดหวัง โดยเฉพาะการรักษาระหว่างให้นม ตรงกับที่สไลด์ระบุว่า S. agalactiae รักษาง่ายกว่าและ S. aureus รักษายาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22664203","locator":"Abstract; 28(2):203-216","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"S agalactiae is an obligate pathogen of the mammary gland, whereas S aureus is more widespread on other cow body sites and in the environment. ... For S agalactiae, eradication can be completed rapidly through a culture and treatment progra"}},{"id":"milk-meat-hygiene--milk-mastitis--contagious-mastitis--v2","statement":"Staphylococcus aureus เป็นเชื้อก่อ mastitis ที่แยกได้บ่อยที่สุดจากตัวอย่างน้ำนมโค ในการสำรวจฟาร์มขนาดใหญ่พบ S. aureus 36 เปอร์เซ็นต์ของเชื้อที่แยกได้ รองลงมาคือ Escherichia coli 27.3 เปอร์เซ็นต์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22476790","locator":"Abstract, Results; 44(7):1765-1771","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Staphylococcus aureus accounted for 36 % of the isolates followed by Escherichia coli (27.3 %)."}},{"id":"milk-meat-hygiene--milk-mastitis--contagious-mastitis--v3","statement":"Mycoplasma bovis ทำลายเต้านมรุนแรงและรักษาด้วยยาแทบไม่ได้ผล การควบคุมที่ได้ผลคือเฝ้าระวังสม่ำเสมอแล้วแยกฝูงหรือคัดทิ้งโคที่ติดเชื้ออย่างรวดเร็ว ตรงกับแนวทางที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27687942","locator":"Abstract; 216:142-147","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It causes severe damage to the udder of cattle and is largely untreatable by chemotherapy. ... An approach to successful control is proposed, which involves regular monitoring and rapid segregation or culling of infected cows."}},{"id":"milk-meat-hygiene--milk-mastitis--contagious-mastitis--v4","statement":"Mycoplasma mastitis ถือเป็นโรคที่ติดต่อได้สูงมากในฝูงและไม่มีการรักษาที่ได้ผล การควบคุมอาศัยการตรวจแล้วคัดทิ้งหรือแยกฝูงอย่างเข้มงวด รวมทั้งการกักและตรวจโคที่ซื้อเข้าใหม่ก่อนเข้าฝูง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12682943","locator":"Abstract; 19(1):199-221","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mycoplasmal bovine mastitis is potentially a highly contagious disease that can cause severe economic problems in affected herds. ... There is no treatment for mycoplasmal mastitis"}}]},"milk-meat-hygiene--milk-mastitis--environmental-และ-opportunistic-mastitis":{"claims":[{"id":"milk-meat-hygiene--milk-mastitis--environmental-และ-opportunistic-mastitis--v1","statement":"Lipopolysaccharide หรือ endotoxin คือองค์ประกอบหลักของ Escherichia coli ที่เซลล์เยื่อบุเต้านมรับรู้ผ่าน TLR4 ร่วมกับ co-receptor CD14 จึงเป็นตัวจุดชนวนการอักเสบรุนแรงใน coliform mastitis ตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38867337","locator":"Abstract; 55(1):76","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Lipopolysaccharide (LPS) is the major E. coli motif recognized by MEC through its interaction with the TLR4 receptor and the CD14 co-receptor."}},{"id":"milk-meat-hygiene--milk-mastitis--environmental-และ-opportunistic-mastitis--v2","statement":"เชื้อกลุ่ม environmental มีแหล่งอยู่นอกเต้านมและเพิ่มจำนวนในวัสดุรองนอนเป็นหลัก จึงควบคุมได้ยากกว่ากลุ่ม contagious โดยมาตรการสุขศาสตร์การรีดนมคุม Streptococcus uberis ได้ไม่ดีนัก และไม่มีผลต่อ coliform mastitis เลย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-6352750","locator":"Abstract; 66(8):1773-1780","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"control of Streptococcus uberis is much less effective and coliform mastitis is unaffected ... There is poor control with infection caused by pathogens that emanate from sources other than the mammary gland and multiply mainly in bedding ma"}},{"id":"milk-meat-hygiene--milk-mastitis--environmental-และ-opportunistic-mastitis--v3","statement":"Pseudomonas aeruginosa ก่อการระบาดของ mastitis ในฝูงโคนมได้จริง และการรักษาด้วยยาปฏิชีวนะไม่ได้ผล สอดคล้องกับที่สไลด์ระบุว่าเชื้อนี้ดื้อยาสูงมาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34250786","locator":"Abstract; 24(2):303-305","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Treatments with antibiotics were proved ineffective. Milk bacterial cultures from 15 affected animals revealed Pseudomonas aeruginosa."}},{"id":"milk-meat-hygiene--milk-mastitis--environmental-และ-opportunistic-mastitis--v4","statement":"ความชุกของ Corynebacterium bovis สูงขึ้นในฝูงที่จุ่มหัวนมหลังรีดน้อยกว่า สอดคล้องกับที่สไลด์ระบุว่าเชื้อนี้พบในกรณีที่ไม่ได้จุ่มหัวนมหลังรีดนม และเชื้อนี้จัดเป็น minor pathogen ที่ก่อการอักเสบไม่รุนแรง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2683341","locator":"Abstract; 125(15):393-396","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The prevalence of coagulase-negative staphylococci, Corynebacterium bovis and Micrococcus species was higher in the herds with a low incidence of clinical mastitis. ... In herds with a low incidence of clinical mastitis significantly less t"}}]},"milk-meat-hygiene--milk-mastitis--การตรวจวินิจฉัย-mastitis":{"claims":[{"id":"milk-meat-hygiene--milk-mastitis--การตรวจวินิจฉัย-mastitis--v1","statement":"California Mastitis Test เป็นการตรวจข้างตัวสัตว์ที่แม่นยำที่สุดรองจากการนับ SCC ในห้องปฏิบัติการ และระดับปฏิกิริยาของ CMT สัมพันธ์กับค่า SCC อย่างมีนัยสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25326717","locator":"Abstract, Results; 47(1):79-86","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The categories of CMT reactions were strongly correlated with SCC (P < 0.05). ... Thus, CMT was concluded to be the most accurate (r = 0.782) field diagnostic test after laboratory test like SCC (r = 0.924)."}},{"id":"milk-meat-hygiene--milk-mastitis--การตรวจวินิจฉัย-mastitis--v2","statement":"ในช่วงที่เกิด mastitis ระดับ sodium และ chloride ในน้ำนมสูงขึ้นและค่าความนำไฟฟ้าสูงขึ้น ขณะที่ potassium ลดลง ตรงกับทิศทางการเปลี่ยนแปลงที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36387788","locator":"Abstract; 10(31):11252-11259","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In the early stages of LM, lactic sodium, chloride, and EC increase, but potassium decreases."}},{"id":"milk-meat-hygiene--milk-mastitis--การตรวจวินิจฉัย-mastitis--v3","statement":"ความนำไฟฟ้าของน้ำนมร่วมกับ chloride และ sodium ทำนายสถานะการติดเชื้อของเต้านมได้แม่นยำกว่าตัวแปรอื่นรวมทั้ง lactose และ somatic cell count ในการเปรียบเทียบวิธีตรวจทางอ้อม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3989085","locator":"Abstract; 68(2):449-456","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Electrical conductivity, chloride, and sodium content of milk were more accurate for predicting infection status of quarters than were other variables."}},{"id":"milk-meat-hygiene--milk-mastitis--การตรวจวินิจฉัย-mastitis--v4","statement":"กิจกรรมของเอนไซม์ NAGase ในน้ำนมเพิ่มขึ้นอย่างมีนัยสำคัญเมื่อเกิด mastitis จากการทดลองฉีดเชื้อ Escherichia coli เข้าเต้านม โดยตอบสนองไปพร้อมกับ LDH และ alkaline phosphatase และเร็วกว่าเอนไซม์บางตัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26026757","locator":"Abstract, Results; 98(8):5440-5447","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The enzymes LDH, NAGase, and alkaline phosphatase showed similar responses, with a significantly increased activity and higher peak values for the HH than the HL cows."}}]},"milk-meat-hygiene--milk-mastitis--ผลของ-mastitis-ต่อน้ำนมและผลิตภัณฑ์":{"claims":[{"id":"milk-meat-hygiene--milk-mastitis--ผลของ-mastitis-ต่อน้ำนมและผลิตภัณฑ์--v1","statement":"น้ำนมจากโคที่มี SCC สูงกว่า 500,000 เซลล์ต่อมิลลิลิตร มีองค์ประกอบเปลี่ยนไปแม้ไม่มีอาการทางคลินิก ซึ่งบ่งชี้ว่ากำแพงกั้นระหว่างเลือดกับน้ำนมเสียหาย สอดคล้องกับกลไก tight junction เสียหายที่สไลด์อธิบาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25682130","locator":"Abstract; 98(4):2079-2087","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Despite no signs of clinical mastitis, milk from cows with somatic cell counts >500,000 cells/mL showed altered milk composition, indicating impaired barrier between the milk and the blood."}},{"id":"milk-meat-hygiene--milk-mastitis--ผลของ-mastitis-ต่อน้ำนมและผลิตภัณฑ์--v2","statement":"ปริมาณ casein เป็นปัจจัยสำคัญที่อธิบายความแปรผันของคุณสมบัติการจับตัวเป็นลิ่มด้วยเรนเนต ทั้ง rennet coagulation time และความแน่นของลิ่มนม จึงเป็นตัวกำหนดคุณสมบัติทางเทคโนโลยีสำหรับทำชีส สอดคล้องกับที่สไลด์ระบุว่าเมื่อ casein ลดลง การจับตัวเป็นลิ่มแย่ลงและ cheese yield ต่ำลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27210496","locator":"Abstract; 83(2):242-248","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk casein content and TA were important factors in explaining the variation of MCP and IAC, supporting the central role of these two traits on technological properties."}},{"id":"milk-meat-hygiene--milk-mastitis--ผลของ-mastitis-ต่อน้ำนมและผลิตภัณฑ์--v3","statement":"การสูญเสียผลผลิตน้ำนมเพิ่มขึ้นตามจำนวนวันตรวจที่ SCC สูงกว่าหรือเท่ากับ 100,000 เซลล์ต่อมิลลิลิตร และโคที่เป็น chronic mastitis สูญเสียผลผลิตมากกว่าโคที่เพิ่งติดเชื้อใหม่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29398029","locator":"Abstract, Results; 101(4):3588-3596","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk yield loss increased as the number of test days with SCC >=100,000 cells/mL increased. ... Cows with chronic mastitis, measured by increased consecutive test days with SCC >=100,000 cells/mL, resulted in higher milk losses than cows wi"}}]},"milk-meat-hygiene--milk-mastitis--การควบคุม-และความสูญเสียทางเศรษฐกิจ":{"claims":[{"id":"milk-meat-hygiene--milk-mastitis--การควบคุม-และความสูญเสียทางเศรษฐกิจ--v1","statement":"องค์ประกอบต้นทุนของ mastitis ตรงกับที่สไลด์ระบุ ได้แก่ ผลผลิตน้ำนมที่ลดลง น้ำนมที่ต้องทิ้ง การคัดทิ้งโคก่อนกำหนด ค่าสัตวแพทย์และค่าปรึกษา ค่าแรงงาน และค่ายารักษา โดยในกรณี subclinical ต้นทุนหลักคือผลผลิตที่ลดลงร้อยละ 93 และการเสียส่วนต่างราคาคุณภาพร้อยละ 7","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33132585","locator":"Abstract, Results; 13(9):1750-1759","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the two most important cost components were the subsequent decrease in milk production and quality premium losses (93% and 7% of SCM costs, respectively). ... The average cost per CM case was 28,760.9 LE, including veterinary time and consu"}},{"id":"milk-meat-hygiene--milk-mastitis--การควบคุม-และความสูญเสียทางเศรษฐกิจ--v2","statement":"ในบรรดามาตรการควบคุม mastitis ที่เป็นไปได้ทั้งหมด สิ่งที่ได้ผลจริงในทางปฏิบัติคือการจัดการ โดยการควบคุมที่ใช้ได้จริงชุดแรกอาศัยวิธีสุขศาสตร์เฉพาะร่วมกับการใช้ยาปฏิชีวนะอย่างถูกต้อง สนับสนุนแนวทางรีดนมสะอาดและจุ่มหัวนมหลังรีดที่สไลด์เน้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-6352750","locator":"Abstract; 66(8):1773-1780","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The possible methods for control are eradication, immunization, therapy, breeding resistant cows, or by improved management factors, but in practice success has been achieved only with the latter. The first practical control was based on sp"}}]}},"milk-meat-hygiene--milk-quality-composition":{"milk-meat-hygiene--milk-quality-composition--factors-affecting-milk-composition":{"claims":[{"id":"milk-meat-hygiene--milk-quality-composition--factors-affecting-milk-composition--v1","statement":"Breed มีผลต่อ milk composition ชัดเจน — จากข้อมูล multibreed herds 139,821 records (16,566 ตัว) พบว่า Holstein-Friesian ให้น้ำนมที่มี fat, protein และ casein ต่ำที่สุด ขณะที่ Jersey ให้ค่าสูงที่สุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30221430","locator":"Anim Sci J 2018;89(11):1622-1627, Abstract (Results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Holstein-Friesian yielded milk with the lowest fat, protein, and casein concentration, and Ca, Mg, and P contents, whereas Jersey cows produced milk with the greatest fat, protein, and casein concentration, and Ca and Mg contents."}},{"id":"milk-meat-hygiene--milk-quality-composition--factors-affecting-milk-composition--v2","statement":"Animal health: subclinical mastitis ทำให้ casein-to-protein ratio และ lactose content เปลี่ยนแปลงอย่างมีนัยสำคัญ และการเปลี่ยนแปลงนี้สัมพันธ์กับ inflammation (SCC สูง) มากกว่าชนิดเชื้อ — contagious, environmental และ opportunistic pathogens ให้ผลไม่แตกต่างกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28365113","locator":"J Dairy Sci 2017;100(6):4868-4883, Abstract (Results and conclusion)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Significant variations in the casein to protein ratio and lactose content were observed in all culture-positive samples and in culture-negative samples with medium to high SCC compared to normal milk. No differences were observed among cont"}},{"id":"milk-meat-hygiene--milk-quality-composition--factors-affecting-milk-composition--v3","statement":"Diet: อาหารสูตร high concentrate/low forage เหนี่ยวนำ milk fat depression (MFD) โดยลด milk fat percentage 25% และ fat yield 27% ในขณะที่ dry matter intake, milk yield, protein และ lactose ไม่เปลี่ยน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-14519791","locator":"J Nutr 2003;133(10):3098-3102, Abstract (Results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The HC/LF diet reduced milk fat percentage by 25% and yield by 27% with no effect on dietary intake, milk production, protein or lactose."}},{"id":"milk-meat-hygiene--milk-quality-composition--factors-affecting-milk-composition--v4","statement":"กลไกของ diet-induced MFD คือ biohydrogenation theory — อาหารบางแบบเปลี่ยน pathway ของ rumen biohydrogenation ของ dietary PUFA ให้เกิด fatty acid intermediates ที่ยับยั้ง mammary fat synthesis โดย trans-10, cis-12 CLA เป็นตัวอย่างที่ถูกระบุ ไม่ใช่การขาด lipogenic precursors","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12626693","locator":"Annu Rev Nutr 2003;23:203-227, Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The biohydrogenation theory proposes that under certain dietary conditions, typical pathways of rumen biohydrogenation are altered to produce unique fatty acid intermediates that inhibit milk fat synthesis. Trans-10, cis-12 conjugated linol"}}]},"milk-meat-hygiene--milk-quality-composition--milk-composition-3-property-categories":{"claims":[{"id":"milk-meat-hygiene--milk-quality-composition--milk-composition-3-property-categories--v1","statement":"Freezing point เป็น physicochemical property ที่สัมพันธ์เชิงเส้น (linear relationship) กับ lactose concentration จึงใช้การวัด cryoscopic point ทำนาย % lactose ในน้ำนมได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17225605","locator":"J AOAC Int 2006;89(6):1581-1584, Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A lineal relationship was found between lactose concentration and freezing point, the analytical equation for which shows a close relationship regarding the 3 methods used. ... The equation obtained also enables prediction of the lactose pe"}},{"id":"milk-meat-hygiene--milk-quality-composition--milk-composition-3-property-categories--v2","statement":"Physicochemical properties ของน้ำนมดิบสัมพันธ์กับ chemical composition — ในโคนม dual-purpose เขตร้อน density มี positive correlation กับ protein, freezing point และ lactose ส่วน fat มี negative correlation กับ density, freezing point, acidity และ conductivity","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40267016","locator":"Vet Sci 2025;12(3):269, Abstract (correlation results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"density maintained significant positive correlations with the variables of protein, freezing point and lactose (< 0.05). However, fat showed significant negative correlations with density, freezing point, acidity and conductivity (< 0.05)."}}]},"milk-meat-hygiene--milk-quality-composition--ระบบเลือดและระบบประสาทของเต้านม":{"claims":[{"id":"milk-meat-hygiene--milk-quality-composition--ระบบเลือดและระบบประสาทของเต้านม--v1","statement":"อัตราการไหลของเลือดผ่านเต้านมสัมพันธ์อย่างมากกับปริมาณน้ำนม โดยต้องมีเลือดไหลผ่านเต้านมประมาณ 500 ปริมาตร ต่อการสร้างน้ำนม 1 ปริมาตร ตรงกับตัวเลข 400 ถึง 500 ที่คำบรรยายให้ไว้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-academies-pre-1988","locator":"Chapter by Ronald C. Gorewit, section Factors Affecting the Yield and Composition of Milk","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mammary gland blood flow rate is highly correlated to milk production. In fact, about 500 volumes of blood flow through the cow's udder for each volume of milk produced (Mepham, 1983; Schmidt, 1971)."}},{"id":"milk-meat-hygiene--milk-quality-composition--ระบบเลือดและระบบประสาทของเต้านม--v2","statement":"ปริมาณสารตั้งต้นที่เต้านมได้รับขึ้นกับอัตราการไหลของเลือดผ่านเต้านมและความเข้มข้นของสารในเลือด และในสัตว์ที่กินอาหารปกติ เลือดที่ไปเลี้ยงเต้านมคิดเป็นร้อยละ 15 ถึง 16 ของ cardiac output","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3889082","locator":"Volume 68, issue 4, pages 1041-1058, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In ruminants, mammary supply of substrate varies with rate of mammary blood flow and concentrations of blood substrates... In fed animals this fraction is 15 to 16% of cardiac output"}},{"id":"milk-meat-hygiene--milk-quality-composition--ระบบเลือดและระบบประสาทของเต้านม--v3","statement":"เต้านมคู่หลังตามปกติเก็บน้ำนมไว้มากกว่าคู่หน้า จึงใช้เวลารีดนานกว่า สนับสนุนข้อที่ว่าเต้าคู่หลังให้น้ำนมมากกว่าคู่หน้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28161171","locator":"Volume 100, issue 4, pages 3091-3095, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"milking time is mostly prolonged in hind quarters compared with front quarters because of the usually higher amount of stored milk"}}]},"milk-meat-hygiene--milk-quality-composition--milk-let-down-และผลของความเครียด":{"claims":[{"id":"milk-meat-hygiene--milk-quality-composition--milk-let-down-และผลของความเครียด--v1","statement":"น้ำนมที่เก็บอยู่ในเต้ามากกว่าร้อยละ 80 เป็นส่วน alveolar ซึ่งจะรีดออกได้ต่อเมื่อเกิด milk ejection จากการหลั่ง oxytocin และการหดตัวของ myoepithelium ตรงกับที่คำบรรยายระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15998500","locator":"Volume 29, issue 2, pages 268-273, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"More than 80% of the milk stored in the udder, i.e. the alveolar fraction, only available after milk ejection is induced by the release of oxytocin and myoepithelial contraction."}},{"id":"milk-meat-hygiene--milk-quality-composition--milk-let-down-และผลของความเครียด--v2","statement":"ความเครียดยับยั้ง milk ejection ได้จริง เช่น การรีดในสภาพแวดล้อมที่ไม่คุ้นเคย แต่กลไกที่พบคือการหลั่ง oxytocin จากต่อมใต้สมองลดลงหรือไม่หลั่งเลย ร่วมกับ cortisol และ beta-endorphin ที่สูงขึ้น ไม่ใช่เพียงฤทธิ์ต้าน oxytocin ที่หลอดเลือดเต้านมตามที่คำบรรยายอธิบาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15998500","locator":"Volume 29, issue 2, pages 268-273, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"We found that a disturbed milk ejection is due to a reduced release or complete absence of oxytocin from the pituitary. During milkings with disturbed milk ejection in unfamiliar surroundings, the concentrations of cortisol and beta-endorph"}},{"id":"milk-meat-hygiene--milk-quality-composition--milk-let-down-และผลของความเครียด--v3","statement":"การตอบสนองของระบบประสาท sympathetic ที่วัดจากอัตราการเต้นของหัวใจที่สูงขึ้นระหว่างเตรียมเต้านม สัมพันธ์กับการยับยั้ง milk ejection ที่มากขึ้นในโคสาว สนับสนุนแนวคิดที่ว่าการตกใจกดการปล่อยน้ำนม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12416807","locator":"Volume 85, issue 10, pages 2551-2561, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"High heart rate responses on d 2 and 4 were associated with enhanced inhibition of milk ejection."}}]},"milk-meat-hygiene--milk-quality-composition--สารตั้งต้นขององค์ประกอบน้ำนม":{"claims":[{"id":"milk-meat-hygiene--milk-quality-composition--สารตั้งต้นขององค์ประกอบน้ำนม--v1","statement":"แลคโตสเป็นองค์ประกอบที่ให้ osmotic pressure หลักของน้ำนม จึงเป็นตัวกำหนดปริมาตรน้ำนม และกลูโคสเป็นสารตั้งต้นหลักของแลคโตส ตรงกับที่คำบรรยายระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27229304","locator":"Volume 12, article 81, background section of abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Lactose, as the primary osmotic component in milk, is the major determinant of milk volume. Glucose is the primary precursor of lactose."}},{"id":"milk-meat-hygiene--milk-quality-composition--สารตั้งต้นขององค์ประกอบน้ำนม--v2","statement":"สารตั้งต้นหลักในเลือดสำหรับการสร้างน้ำนม ได้แก่ กลูโคส acetate beta-hydroxybutyrate กรดไขมันจากไตรกลีเซอไรด์ และกรดอะมิโน โดยกรดไขมันสายสั้น C4 ถึง C14 และ palmitic acid บางส่วนถูกสังเคราะห์ขึ้นในเต้านมจาก acetate สนับสนุนที่คำบรรยายว่ากรดไขมันระเหยจากรูเมนเป็นแหล่งไขมันนม และกรดอะมิโนในเลือดเป็นแหล่งโปรตีนนม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-academies-pre-1988","locator":"Chapter by Ronald C. Gorewit, section on milk synthesis","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The major blood precursors for milk synthesis are glucose, acetate, beta-hydroxybutyrate, triglyceride fatty acids, and amino acids"}}]},"milk-meat-hygiene--milk-quality-composition--โครงสร้างค้ำจุนเต้านม-suspensory-apparatus":{"claims":[{"id":"milk-meat-hygiene--milk-quality-composition--โครงสร้างค้ำจุนเต้านม-suspensory-apparatus--v1","statement":"median suspensory ligament ประกอบด้วยเนื้อเยื่อเกี่ยวพันชนิด elastic ที่มาจาก abdominal tunic ขณะที่ lateral suspensory ligament เป็นชนิด nonelastic ตรงกับที่เอกสารสรุประบุว่าเส้นกลางเป็น elastic ส่วน deep lateral ไม่ใช่เนื้อเยื่อ elastic","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-elsevier-saunders-2013","locator":"บทที่ 39 หัวข้อโครงสร้างค้ำจุนเต้านม (median และ lateral ligament)","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"median ligament ... composed of elastic connective tissue that originates from the abdominal tunic ... lateral ligament (nonelastic) ... originates from prepubic and subpubic ligaments"}},{"id":"milk-meat-hygiene--milk-quality-composition--โครงสร้างค้ำจุนเต้านม-suspensory-apparatus--v2","statement":"โครงสร้างค้ำจุนเต้านมโคประกอบด้วย medial lamina และ lateral lamina โดยฐานเต้านมยึดกับผนังหน้าท้องด้านล่างผ่าน dorsal connective tissue plate ประมาณร้อยละ 60 และยึดกับพื้นเชิงกรานผ่าน symphysial tendon ประมาณร้อยละ 40 สนับสนุนข้อที่ว่าเนื้อเยื่อที่เชื่อมด้าน dorsal ของเต้านมกับผนังช่องท้องเป็นจุดยึดสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10820903","locator":"Abstract; 29(1):51-61","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The udder base is attached to the ventral abdominal wall by means of the dorsal connective tissue plate ... Sixty per cent of the udder base is attached to the ventral abdominal wall and 40% to the pelvic floor by the symphysial tendon."}}]},"milk-meat-hygiene--milk-quality-composition--ท่อน้ำนมและหูรูดหัวนม":{"claims":[{"id":"milk-meat-hygiene--milk-quality-composition--ท่อน้ำนมและหูรูดหัวนม--v1","statement":"Fürstenberg's rosette อยู่ที่ส่วนต้น (proximal portion) ของ teat canal ซึ่งเป็นรอยต่อกับ teat cistern ไม่ได้อยู่ที่ปลายด้านในของ gland cistern ตรงกับที่เอกสารสรุปเฉลยว่าโจทย์ข้อนั้นตอบ False","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20919896","locator":"Abstract, classification of obstruction sites; 71(10):1123-6","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"categorized according to the anatomic location of the obstruction via ultrasonography into teat canal obstruction (TCO) and obstruction at the proximal portion of the teat canal (Fürstenberg rosette obstruction [FRO])"}},{"id":"milk-meat-hygiene--milk-quality-composition--ท่อน้ำนมและหูรูดหัวนม--v2","statement":"Fürstenberg's rosette เป็นโครงสร้างที่ประกอบด้วยรอยพับของเยื่อเมือก (mucosal folds) ซึ่งมีจำนวนและขนาดแตกต่างกันมากระหว่างตัว ไม่ใช่กล้ามเนื้อหูรูด จึงไม่ใช่โครงสร้างที่ทำหน้าที่ปิดกั้นน้ำนมแบบ sphincter","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25382725","locator":"Abstract; 298(7):1359-66","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The rosette was found to have significant variation in its size and number of mucosal folds."}}]}},"milk-meat-hygiene--milk-raw-std":{"milk-meat-hygiene--milk-raw-std--standard-parameters-raw-milk":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--standard-parameters-raw-milk--v1","statement":"มกษ. 6003-2553 (TAS 6003-2010) กำหนดองค์ประกอบขั้นต่ำของน้ำนมโคดิบ: fat ไม่น้อยกว่า 3.35% โดยน้ำหนัก, milk solids not fat (SNF) ไม่น้อยกว่า 8.25% โดยน้ำหนัก และ protein ไม่น้อยกว่า 3.00% โดยน้ำหนัก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 3 Quality, clauses 3.9-3.11 (ACFS unofficial English translation)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"3.9 Protein content shall not be less than 3.00% by weight. 3.10 Fat content shall not be less than 3.35% by weight. 3.11 Milk solids not fat shall not be less than 8.25% by weight."}},{"id":"milk-meat-hygiene--milk-raw-std--standard-parameters-raw-milk--v2","statement":"มกษ. 6003-2553 กำหนดว่า freezing point ของน้ำนมโคดิบต้องไม่สูงกว่า -0.520 องศาเซลเซียส และให้ตรวจด้วย thermistor cryoscopy ตามวิธี ISO 5764/IDF 108","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 3 Quality clause 3.5, and Section 10 Table 1 item 4 (methods of analysis)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"3.5 Freezing point shall not be above – 0.520°C. ... Table 1 item 4: Freezing point (section 3.5) | ISO 5764/IDF 108 | Thermistor Cryoscopy"}},{"id":"milk-meat-hygiene--milk-raw-std--standard-parameters-raw-milk--v3","statement":"มกษ. 6003-2553 กำหนด somatic cell count (SCC) ไม่เกิน 500,000 cells/ml และเกณฑ์จุลินทรีย์: standard plate count ไม่เกิน 5 x 10^5 cfu/ml, coliform count ไม่เกิน 10^4 cfu/ml, thermoduric count ไม่เกิน 10^3 cfu/ml","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 3 Quality clause 3.8 (SCC) and Section 8.3 Microbiological criteria, clauses 8.3.1-8.3.3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"3.8 Somatic cell count shall not exceed 500,000 cells/ml ... 8.3.1 Standard plate count shall not exceed 5 x 10^5 cfu/ml. 8.3.2 Coliform count shall not exceed 10^4 cfu/ml. 8.3.3 Thermoduric count shall not exceed 10^3 cfu/ml."}},{"id":"milk-meat-hygiene--milk-raw-std--standard-parameters-raw-milk--v4","statement":"มกษ. 6003-2553 กำหนดเกณฑ์ physicochemical และ platform test ของน้ำนมโคดิบ: titratable acid ไม่เกิน 0.16% และ pH 6.6 ถึง 6.8, specific gravity ไม่น้อยกว่า 1.028 ที่ 20 องศาเซลเซียส, ต้องไม่เกิด protein precipitation เมื่อทดสอบด้วย 70% ethyl alcohol และ methylene blue reduction time ต้องนานกว่า 4 ชั่วโมง หรือ resazurin reduction test อย่างน้อย grade 4.5 ที่ 1 ชั่วโมง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 3 Quality, clauses 3.3, 3.4, 3.6, 3.7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"3.3 There shall be no protein precipitation under preliminary testing with 70% ethyl alcohol. If precipitation is observed, the test shall be confirmed by the clot on boiling test. 3.4 Tritable acid shall not exceed 0.16% and pH shall be 6."}}]},"milk-meat-hygiene--milk-raw-std--objectives-of-milk-quality-determination":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--objectives-of-milk-quality-determination--v1","statement":"วัตถุประสงค์ zoonosis prevention และ residue control ถูกเขียนเป็นข้อกำหนดจริงใน มกษ. 6003-2553 คือ ต้องตรวจไม่พบจุลินทรีย์ที่ก่อโรคติดต่อจากสัตว์สู่คน เช่น วัณโรค (tuberculosis) และต้องตรวจไม่พบยาปฏิชีวนะเมื่อใช้ชุดทดสอบที่ผ่านการ validate","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 7 Veterinary drug residues, and Section 8.3 clause 8.3.4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Antibiotics shall not be detected if a validated test kit is used. ... 8.3.4 Zoonotic microorganisms such as tuberculosis shall not be found."}}]},"milk-meat-hygiene--milk-raw-std--thai-regulatory-framework-2-ministries":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--thai-regulatory-framework-2-ministries--v1","statement":"มกษ. 6003-2553 ออกภายใต้ พ.ร.บ. มาตรฐานสินค้าเกษตร พ.ศ. 2551 ในฐานะ voluntary standard (มาตรฐานทั่วไป ไม่ใช่มาตรฐานบังคับ) โดยยกเลิก มกษ. 6003-2548 ฉบับเดิม และนิยามของ น้ำนมโคดิบ คือน้ำนมจากแม่โคหลังคลอดไม่น้อยกว่า 3 วัน และต้องไม่มี colostrum ปน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Notification of the Ministry of Agriculture and Cooperatives (clauses 1-2, notified 26 August B.E. 2553) and Section 2 Definitions","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The Notification of the National Committee on Agricultural Commodity and Food Standards entitled the establishment of Thai Agricultural Commodity and Food Standard: Raw Cow Milk, dated 5 August B.E. 2548 (2005) is repealed. The Thai Agricul"}}]},"milk-meat-hygiene--milk-raw-std--มกษ-6003-2553-นิยามและคุณภาพน้ำนมโคดิบ":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--มกษ-6003-2553-นิยามและคุณภาพน้ำนมโคดิบ--v1","statement":"มาตรฐานนิยามน้ำนมโคดิบว่าเป็นน้ำนมจากแม่โคหลังคลอดไม่น้อยกว่า 3 วัน ต้องไม่มีน้ำนมเหลือง และห้ามเติมหรือแยกสิ่งใด หรือผ่านกรรมวิธีใด นอกจากการทำให้เย็น ตรงกับคำบรรยายทุกข้อ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 2 Definitions","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Raw cow milk means milk from dairy cow not less than 3 days after parturition and shall not contain colostrum. Milk shall not be either addition to it or extraction from it, or subject to any process except cooling."}},{"id":"milk-meat-hygiene--milk-raw-std--มกษ-6003-2553-นิยามและคุณภาพน้ำนมโคดิบ--v2","statement":"มาตรฐานกำหนดว่าต้องไม่มีการตกตะกอนของโปรตีนเมื่อทดสอบเบื้องต้นด้วย ethyl alcohol 70 เปอร์เซ็นต์ ถ้าตกตะกอนให้ยืนยันด้วย clot on boiling test กรดที่ไทเทรตได้ไม่เกินร้อยละ 0.16 pH 6.6 ถึง 6.8 จุดเยือกแข็งไม่สูงกว่า -0.520 องศาเซลเซียส และความถ่วงจำเพาะไม่น้อยกว่า 1.028 ที่ 20 องศาเซลเซียส ตรงกับคำบรรยาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Sections 3.3 to 3.6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"3.3 There shall be no protein precipitation under preliminary testing with 70% ethyl alcohol. If precipitation is observed, the test shall be confirmed by the clot on boiling test. 3.4 Tritable acid shall not exceed 0.16% and pH shall be 6."}},{"id":"milk-meat-hygiene--milk-raw-std--มกษ-6003-2553-นิยามและคุณภาพน้ำนมโคดิบ--v3","statement":"มาตรฐานกำหนดเวลาการลดสีของ methylene blue ต้องนานกว่า 4 ชั่วโมง หรือ resazurin ไม่ต่ำกว่าเกรด 4.5 ที่ 1 ชั่วโมง จำนวนเซลล์โซมาติกไม่เกิน 500,000 เซลล์ต่อมิลลิลิตร โปรตีนไม่น้อยกว่าร้อยละ 3.00 ไขมันไม่น้อยกว่าร้อยละ 3.35 และเนื้อนมไม่รวมมันเนยไม่น้อยกว่าร้อยละ 8.25 โดยน้ำหนัก ตรงกับตัวเลขทั้งหมดในคำบรรยาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Sections 3.7 to 3.11","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"3.7 Methylene blue reduction time shall be longer than 4 hours or Resazurin reduction test shall be at least grade 4.5 at 1 hour incubation. 3.8 Somatic cell count shall not exceed 500,000 cells/ml 3.9 Protein content shall not be less than"}}]},"milk-meat-hygiene--milk-raw-std--เกณฑ์จุลินทรีย์และสารตกค้างในนมดิบ":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--เกณฑ์จุลินทรีย์และสารตกค้างในนมดิบ--v1","statement":"มาตรฐานกำหนด standard plate count ไม่เกิน 5 คูณ 10 ยกกำลัง 5 cfu ต่อมิลลิลิตร coliform ไม่เกิน 10 ยกกำลัง 4 cfu ต่อมิลลิลิตร และ thermoduric count ไม่เกิน 10 ยกกำลัง 3 cfu ต่อมิลลิลิตร ตรงกับตัวเลขในคำบรรยาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 8.3 Microbiological criteria","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"8.3.1 Standard plate count shall not exceed 5 x 10(5) cfu/ml. 8.3.2 Coliform count shall not exceed 10(4) cfu/ml. 8.3.3 Thermoduric count shall not exceed 10(3) cfu/ml."}},{"id":"milk-meat-hygiene--milk-raw-std--เกณฑ์จุลินทรีย์และสารตกค้างในนมดิบ--v2","statement":"กฎหมายอาหารกำหนดให้น้ำนมโคสดและน้ำนมโคต้องปราศจากเชื้อโรคที่อาจติดต่อถึงคนได้ โดยยกตัวอย่างเชื้อที่ทำให้เกิดวัณโรคและเชื้อที่ทำให้เกิดโรคแท้งติดต่อ ซึ่งตรงกับ Mycobacterium bovis และ Brucella spp. ที่คำบรรยายระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--130-87--2013","locator":"ข้อ 7 (1) หน้า 64","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ต้องปราศจากเชื้อโรคอันอาจจะติดต่อถึงคนได้ เช่น เชื้อที่ทำให้เกิดวัณโรค เชื้อที่ทำให้เกิดโรคแท้งติดต่อ เป็นต้น"}},{"id":"milk-meat-hygiene--milk-raw-std--เกณฑ์จุลินทรีย์และสารตกค้างในนมดิบ--v3","statement":"มาตรฐานกำหนดว่าต้องตรวจไม่พบยาปฏิชีวนะเมื่อใช้ชุดทดสอบที่ผ่านการตรวจสอบความใช้ได้ และห้ามใช้วัตถุเจือปนอาหารในน้ำนมโคดิบ ตรงกับที่คำบรรยายระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Sections 4 and 7","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Antibiotics shall not be detected if a validated test kit is used. 4. FOOD ADDITIVES Food additives are not allowed."}}]},"milk-meat-hygiene--milk-raw-std--ประกาศ-สธ-350-2556-และ-406-2562-นิยามผลิตภัณฑ์นมโค":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--ประกาศ-สธ-350-2556-และ-406-2562-นิยามผลิตภัณฑ์นมโค--v1","statement":"ประกาศฉบับที่ 350 นิยามน้ำนมโคดิบว่าเป็นน้ำนมที่รีดได้จากแม่โคและยังไม่ผ่านกรรมวิธีฆ่าเชื้อด้วยความร้อน และนิยามน้ำนมโคสดว่าต้องผ่านพาสเจอร์ไรส์ที่อุณหภูมิไม่เกิน 80 องศาเซลเซียส มีมันเนยไม่น้อยกว่าร้อยละ 3.2 ของน้ำหนัก และไม่มีการเติมหรือแยกสิ่งใด ยกเว้นการแยกมันเนย ตรงกับคำบรรยายทุกจุด","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--130-87--2013","locator":"ข้อ 3 หน้า 61","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"น้ำนมโคดิบ หมายความว่า น้ำนมที่รีดได้จากแม่โค และไม่ผ่านกรรมวิธีการฆ่าเชื้อด้วยความร้อน น้ำนมโคสด หมายความว่า ผลิตภัณฑ์ที่ได้จากการนำน้ำนมโคดิบมาผ่านกรรมวิธีพาสเจอร์ไรส์ที่อุณหภูมิไม่เกิน 80 องศาเซลเซียส มีมันเนยไม่น้อยกว่าร้อยละ 3.2 ของน้ำ"}},{"id":"milk-meat-hygiene--milk-raw-std--ประกาศ-สธ-350-2556-และ-406-2562-นิยามผลิตภัณฑ์นมโค--v2","statement":"ประกาศฉบับเดียวกันนิยามน้ำนมโคว่าอาจปรับปริมาณเนื้อนมด้วยนมผงได้ไม่เกินร้อยละ 1 ของน้ำหนัก นิยามนมผงว่าคือน้ำนมโคดิบที่ฆ่าเชื้อแล้วระเหยน้ำออกจนเป็นผง นมข้นคือระเหยเอาน้ำบางส่วนออก นมคืนรูปคือการนำองค์ประกอบของน้ำนมโคดิบมาผสมให้เหมือนน้ำนมโคสด น้ำนมโค หรือนมข้น และนมแปลงไขมันคือการใช้ไขมันอื่นแทนมันเนย ตรงกับคำบรรยาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--130-87--2013","locator":"ข้อ 3 หน้า 61 ถึง 62","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"หรือปรับปริมาณเนื้อนมด้วยนมผงไม่เกินร้อยละ 1 ของน้ำหนัก ... นมแปลงไขมัน หมายความว่า น้ำนมโคสด น้ำนมโค นมผง นมข้น หรือ นมคืนรูปที่ใช้ไขมันอื่นบางส่วนหรือทั้งหมดแทนมันเนยที่มีอยู่"}}]},"milk-meat-hygiene--milk-raw-std--heat-treatment-ตามกฎหมาย-และการเก็บ":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--heat-treatment-ตามกฎหมาย-และการเก็บ--v1","statement":"กฎหมายกำหนดพาสเจอร์ไรส์เป็นอุณหภูมิไม่ต่ำกว่า 63 องศาเซลเซียส คงอยู่ไม่น้อยกว่า 30 นาที หรือไม่ต่ำกว่า 72 องศาเซลเซียส ไม่น้อยกว่า 15 วินาที แล้วทำให้เย็นลงทันทีที่ 5 องศาเซลเซียสหรือต่ำกว่า และกำหนดยูเอชทีเป็นอุณหภูมิไม่ต่ำกว่า 133 องศาเซลเซียส ไม่น้อยกว่า 1 วินาที ตรงกับตัวเลข LTLT HTST และ UHT ในคำบรรยาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--130-87--2013","locator":"ข้อ 6 (1) และ (3) หน้า 63","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"อุณหภูมิไม่ต่ำกว่า 63 องศาเซลเซียส และคงอยู่ที่อุณหภูมินี้ไม่น้อยกว่า 30 นาที แล้วทำให้เย็นลงทันทีที่อุณหภูมิ 5 องศาเซลเซียส หรือต่ำกว่า ... ยู เอช ที หมายความว่า กรรมวิธีฆ่าเชื้อด้วยความร้อนที่อุณหภูมิไม่ต่ำกว่า 133 องศาเซลเซียส ไม่น้อยกว่"}},{"id":"milk-meat-hygiene--milk-raw-std--heat-treatment-ตามกฎหมาย-และการเก็บ--v2","statement":"กฎหมายกำหนดให้น้ำนมโคสดหรือน้ำนมโคพาสเจอร์ไรส์ต้องเก็บที่อุณหภูมิไม่เกิน 8 องศาเซลเซียส ตลอดระยะเวลาหลังบรรจุจนถึงผู้บริโภค และบริโภคได้ไม่เกิน 10 วันนับจากวันบรรจุ ส่วนน้ำนมโคสเตอริไลส์และยูเอชทีต้องเก็บที่อุณหภูมิปกติได้ไม่น้อยกว่า 5 วันโดยคุณภาพไม่เปลี่ยน ตรงกับคำบรรยาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--130-87--2013","locator":"ข้อ 8 และ ข้อ 9 หน้า 64 ถึง 65","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"น้ำนมโคสดหรือน้ำนมโคพาสเจอร์ไรส์ ต้องเก็บรักษาไว้ที่อุณหภูมิไม่เกิน 8 องศาเซลเซียส ตลอดระยะเวลาหลังบรรจุจนถึงผู้บริโภค และระยะเวลาการบริโภคต้องไม่เกิน 10 วัน นับจากวันที่บรรจุในภาชนะบรรจุพร้อมจำหน่าย"}}]},"milk-meat-hygiene--milk-raw-std--มาตรฐานนมผง-และนมข้น":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--มาตรฐานนมผง-และนมข้น--v1","statement":"กฎหมายกำหนดนมผงให้มีความชื้นไม่เกินร้อยละ 5 ของน้ำหนัก มีมันเนยไม่น้อยกว่าร้อยละ 26 สำหรับชนิดเต็มมันเนย มากกว่าร้อยละ 1.5 แต่ไม่ถึงร้อยละ 26 สำหรับชนิดพร่องมันเนย และไม่เกินร้อยละ 1.5 สำหรับชนิดขาดมันเนย ตรวจไม่พบ E. coli ใน 0.1 กรัม และตรวจพบแบคทีเรียได้ไม่เกิน 50,000 ใน 1 กรัม ตรงกับตัวเลขในคำบรรยาย โดยเกณฑ์โปรตีนร้อยละ 34 นั้นเป็นโปรตีนนมในเนื้อนมไม่รวมมันเนย ไม่ใช่ร้อยละ 34 ของน้ำหนักทั้งหมด","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--130-87--2013","locator":"ข้อ 10 หน้า 65","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"มีความชื้นไม่เกินร้อยละ 5 ของน้ำหนัก ... มีโปรตีนนมในเนื้อนมไม่รวมมันเนยไม่น้อยกว่าร้อยละ 34 ของน้ำหนัก ... ตรวจไม่พบแบคทีเรียชนิด อี.โคไล (Escherichia coli) ในนมผง 0.1 กรัม ตรวจพบแบคทีเรียได้ไม่เกิน 50,000 ในนมผง 1 กรัม"}},{"id":"milk-meat-hygiene--milk-raw-std--มาตรฐานนมผง-และนมข้น--v2","statement":"กฎหมายกำหนดนมข้นหวานให้มีวิตามินเออย่างน้อย 330 ไมโครกรัมเรตินอลต่อ 100 กรัม ตรวจพบยีสต์และเชื้อรารวมกันได้ไม่เกิน 10 ใน 1 กรัม ตรวจไม่พบโคลิฟอร์มใน 0.1 กรัม และตรวจพบแบคทีเรียได้ไม่เกิน 10,000 ใน 1 กรัม ตรงกับตัวเลขในคำบรรยาย โดยเกณฑ์เหล่านี้ระบุไว้สำหรับนมข้นหวานโดยเฉพาะ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--130-87--2013","locator":"ข้อ 11 (8) และ (10) ถึง (13) หน้า 66","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"มีวิตามินเอไม่น้อยกว่า 330 ไมโครกรัมเรตินอล ต่อนมข้นหวาน 100 กรัม ... ตรวจพบยีสต์และเชื้อรารวมกันได้ไม่เกิน 10 ในนมข้นหวาน 1 กรัม ตรวจไม่พบแบคทีเรียชนิดโคลิฟอร์มในนมข้นหวาน 0.1 กรัม ตรวจพบแบคทีเรียได้ไม่เกิน 10,000 ในนมข้นหวาน 1 กรัม"}},{"id":"milk-meat-hygiene--milk-raw-std--มาตรฐานนมผง-และนมข้น--v3","statement":"กฎหมายกำหนดให้นมคืนรูปแต่ละชนิดต้องมีคุณภาพหรือมาตรฐานเช่นเดียวกับน้ำนมโคสด น้ำนมโค หรือนมข้นชนิดที่ตรงกัน และห้ามมีวัตถุกันเสียทั้งในนมผงและนมข้น ตรงกับคำบรรยาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--130-87--2013","locator":"ข้อ 10 (5) ข้อ 11 (3) และ ข้อ 12 หน้า 65 ถึง 66","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"นมคืนรูปชนิดเต็มมันเนยมีคุณภาพหรือมาตรฐานเช่นเดียวกับน้ำนมโคสดหรือน้ำนมโคชนิดเต็มมันเนย ... ไม่มีวัตถุกันเสีย"}}]},"milk-meat-hygiene--milk-raw-std--มาตรฐานการรับซื้อน้ำนมโค-พ-ศ-2558":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--มาตรฐานการรับซื้อน้ำนมโค-พ-ศ-2558--v1","statement":"มาตรฐานสินค้าเกษตรน้ำนมโคดิบกำหนดให้น้ำนมดิบที่เก็บในถังที่ศูนย์รวมนมต้องรักษาอุณหภูมิที่ 4 องศาเซลเซียสหรือต่ำกว่า และส่งถึงโรงงานแปรรูปภายใน 24 ชั่วโมง เกณฑ์เวลา 24 ชั่วโมงตรงกับคำบรรยาย แต่อุณหภูมิที่มาตรฐานนี้กำหนดคือ 4 องศาเซลเซียส ไม่ใช่ 8 องศาเซลเซียส","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 9.2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The temperature of raw milk kept in the storage tank at the collection center shall be maintained at 4 degrees C or below and delivered to the processing plant within 24 hours."}},{"id":"milk-meat-hygiene--milk-raw-std--มาตรฐานการรับซื้อน้ำนมโค-พ-ศ-2558--v2","statement":"มาตรฐานห้ามนำน้ำนมที่ถูกปฏิเสธมาผสมกับน้ำนมดิบคุณภาพดีอย่างเด็ดขาด ตรงกับเงื่อนไขที่คำบรรยายว่าต้องไม่ใช่ refusal milk","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 9.3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mix of rejected milk with good quality raw milk is strictly prohibited."}}]},"milk-meat-hygiene--milk-raw-std--การเก็บตัวอย่างน้ำนม":{"claims":[{"id":"milk-meat-hygiene--milk-raw-std--การเก็บตัวอย่างน้ำนม--v1","statement":"มาตรฐานสากลว่าด้วยการเก็บตัวอย่างน้ำนมและผลิตภัณฑ์นมระบุว่าโดยปกติไม่ควรเติมสารกันเสียลงในตัวอย่างที่ตั้งใจนำไปตรวจทางจุลชีววิทยาหรือทางประสาทสัมผัส ตรงกับที่เอกสารสรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-international-organiza-2008","locator":"Scope และหัวข้อว่าด้วยการเติมสารกันเสีย","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Preservatives should normally not be added to samples intended for microbiological or sensory examination"}}]}},"milk-meat-hygiene--milk-raw-storage":{"milk-meat-hygiene--milk-raw-storage--cold-chain-principles-transport":{"claims":[{"id":"milk-meat-hygiene--milk-raw-storage--cold-chain-principles-transport--v1","statement":"ตามเกณฑ์ EU (Reg. 853/2004) น้ำนมดิบต้อง cool ทันทีหลังรีดให้ไม่เกิน 8°C ถ้าเก็บ (collection) ทุกวัน หรือไม่เกิน 6°C ถ้าไม่ได้เก็บทุกวัน และระหว่าง transport ต้องรักษา cold chain โดยอุณหภูมิเมื่อถึงโรงงานปลายทางต้องไม่เกิน 10°C","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-european-union-europea-2004","locator":"Annex III, Section IX, Chapter I, Part II(B), points 2(a) and 3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk must be cooled immediately to not more than 8 oC in the case of daily collection, or not more than 6 oC if collection is not daily ... During transport the cold chain must be maintained and, on arrival at the establishment of destinati"}},{"id":"milk-meat-hygiene--milk-raw-storage--cold-chain-principles-transport--v2","statement":"การเก็บน้ำนมดิบที่อุณหภูมิ ≥6°C ทำให้ bacterial count, protease activity และ proteolysis เพิ่มขึ้นอย่างมีนัยสำคัญ ส่วน deep cooling ที่ 2°C หรือการใช้ heating ร่วมกับ refrigeration ที่ ≤4°C ยืด storage life ได้ โดย isolate ที่พบเด่นคือ Pseudomonas fluorescens และ Bacillus cereus","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28252354","locator":"J Dairy Res 2017;84(1):92-101","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"all of the samples showed increasing BC, PA and PL as a function of temperature, time and initial BC with a significant increase in those criteria ≥6 °C ... deep cooling (2 °C) and combination of heating and refrigeration (≤4 °C) significan"}},{"id":"milk-meat-hygiene--milk-raw-storage--cold-chain-principles-transport--v3","statement":"Psychrotrophic bacteria ที่เติบโตในน้ำนมดิบแช่เย็นสร้าง protease และ lipase ที่ทน heat โดยยังคง activity อยู่หลังให้ความร้อนที่ 70, 80 หรือ 90°C และ protease ทนความร้อนได้มากกว่า lipase จึงเป็นเหตุผลว่า cold chain ที่ล้มเหลวทำให้ผลิตภัณฑ์เสียได้แม้ผ่านความร้อนแล้ว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30070086","locator":"J Zhejiang Univ Sci B 2018;19(8):630-642","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Proteases and lipases produced by psychrotrophic bacteria retained activity after heat treatment at 70, 80, or 90 °C, and proteases appeared to be more heat-stable than lipases."}}]},"milk-meat-hygiene--milk-raw-storage--milk-collecting-centers-ศูนย์รวบรวมน้ำนม-mcc":{"claims":[{"id":"milk-meat-hygiene--milk-raw-storage--milk-collecting-centers-ศูนย์รวบรวมน้ำนม-mcc--v1","statement":"คุณภาพจุลชีววิทยาของน้ำนมดิบเปลี่ยนแปลงอย่างมีนัยสำคัญระหว่างจุดเก็บตัวอย่างสองจุดในระบบรวบรวมน้ำนม โดย reduction time of methylene blue (RTMB) ลดลงประมาณ 54% และ risk factor ที่ระบุได้คือ ฤดูกาล และระยะทางระหว่างฟาร์มกับโรงนม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25374932","locator":"ScientificWorldJournal 2014;2014:131593","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The average contamination by total mesophilic aerobic bacteria (TMAB), coliforms, yeasts, molds, and different pathogens in samples taken at M1 showed significant changes at M2. This was confirmed by the decrease of reduction time of methyl"}}]},"milk-meat-hygiene--milk-raw-storage--milk-collecting-points-จุดรับน้ำนม":{"claims":[{"id":"milk-meat-hygiene--milk-raw-storage--milk-collecting-points-จุดรับน้ำนม--v1","statement":"นิยามทางกฎหมายของ raw milk คือ น้ำนมที่หลั่งจาก mammary gland ของสัตว์ farmed ที่ยังไม่ผ่านความร้อนเกิน 40°C และไม่ผ่านกระบวนการใดที่ให้ผลเทียบเท่า","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-european-union-europea-2004","locator":"Annex I, point 4.1 (definition of 'raw milk')","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"'Raw milk' means milk produced by the secretion of the mammary gland of farmed animals that has not been heated to more than 40 °C or undergone any treatment that has an equivalent effect."}}]},"milk-meat-hygiene--milk-raw-storage--จุดรับน้ำนมและศูนย์รวมนม":{"claims":[{"id":"milk-meat-hygiene--milk-raw-storage--จุดรับน้ำนมและศูนย์รวมนม--v1","statement":"มาตรฐานสินค้าเกษตรแยกจุดรับน้ำนม milk collecting point ออกจากศูนย์รวมนม milk collection center โดยให้รวมน้ำนมจากแม่โคแต่ละตัวลงภาชนะสะอาดแล้วส่งไปยังศูนย์รวมนมโดยเร็ว และเวลาขนส่งจากจุดรับน้ำนมแห่งแรกถึงศูนย์รวมนมต้องไม่เกิน 2 ชั่วโมง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 9.1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Raw milk collected from individual dairy cow shall be pooled in a clean container... and quickly transferred to a milk collecting center. Time of transportation from the first milk collecting point to the milk collection center shall not ta"}}]},"milk-meat-hygiene--milk-raw-storage--หลักการรักษาคุณภาพด้วยความเย็น":{"claims":[{"id":"milk-meat-hygiene--milk-raw-storage--หลักการรักษาคุณภาพด้วยความเย็น--v1","statement":"อุณหภูมิที่ดีที่สุดในการเก็บน้ำนมคือ 4 องศาเซลเซียสหรือต่ำกว่า ตรงกับอุณหภูมิที่คำบรรยายแนะนำ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-2002","locator":"Chapter 4, section on milk cooling","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The best temperature to keep the milk is 4 degrees Celsius (or below)"}},{"id":"milk-meat-hygiene--milk-raw-storage--หลักการรักษาคุณภาพด้วยความเย็น--v2","statement":"หลักการทำความเย็นคือการยืด lag phase ของแบคทีเรียไว้ให้นานที่สุดจริง โดยแบบจำลองพบว่าเวลาก่อนเริ่มทำความเย็นเป็นช่วงวิกฤตที่สุดและไม่ควรเกิน 1 ชั่วโมง และการลดอุณหภูมิจาก 30 ลงมา 10 องศาเซลเซียสภายใน 2 ชั่วโมงทำให้ psychrotrophic bacteria แทบไม่เพิ่มจำนวน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28831963","locator":"Volume 84, issue 3, pages 318-321, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The time before the start of cooling was the most critical and should not exceed 1 h... Cooling from 30 to 10 degrees C within 2 h ensured minimal growth of psychrotrophic bacteria in the milk."}}]},"milk-meat-hygiene--milk-raw-storage--วิธีลดอุณหภูมิน้ำนมดิบ":{"claims":[{"id":"milk-meat-hygiene--milk-raw-storage--วิธีลดอุณหภูมิน้ำนมดิบ--v1","statement":"เอกสารของ FAO ระบุวิธีลดอุณหภูมิน้ำนมไว้หลายแบบ ได้แก่ การใช้น้ำเย็นแช่ การใช้น้ำแข็ง เครื่องทำความเย็น evaporative cooler surface cooler ถังทำความเย็นแบบ bulk direct expansion และ in-can rotary cooler ตรงกับรายการวิธีที่คำบรรยายไล่ไว้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-2002","locator":"Chapter 4, section on cooling equipment","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"use cold water to cool the milk ... surface coolers ... a bulk (direct expansion) milk cooling tank ... an in-can rotary cooler"}}]},"milk-meat-hygiene--milk-raw-storage--วิธีรักษาคุณภาพแบบอื่น":{"claims":[{"id":"milk-meat-hygiene--milk-raw-storage--วิธีรักษาคุณภาพแบบอื่น--v1","statement":"thermization เป็นการให้ความร้อนอย่างอ่อนที่ใช้ลดการปนเปื้อนของน้ำนมดิบก่อนนำไปแปรรูป โดยงานวิจัยนี้ใช้ที่ 60 และ 67 องศาเซลเซียส ซึ่งคร่อมช่วง 60 ถึง 66 องศาเซลเซียสที่คำบรรยายระบุ แต่ใช้เวลา 30 วินาที ไม่ใช่ 15 วินาที","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19435227","locator":"Volume 72, issue 4, pages 783-790, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"before and after thermization at 60 and 67 degrees C for 30 s. Such mild thermal treatments are commonly applied to reduce natural contaminants of raw milk before processing"}},{"id":"milk-meat-hygiene--milk-raw-storage--วิธีรักษาคุณภาพแบบอื่น--v2","statement":"ระบบ lactoperoxidase ถูกกระตุ้นโดยเติม sodium thiocyanate 14 มิลลิกรัมต่อลิตร ตามด้วย sodium percarbonate 30 มิลลิกรัมต่อลิตร ตามลำดับนี้เท่านั้น และต้องทำภายใน 2 ถึง 3 ชั่วโมงหลังรีดนม ตรงกับสารและกรอบเวลาที่คำบรรยายระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-1991","locator":"Sections 4.1 to 4.3","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"14 mg of NaSCN is added per litre of milk... Secondly, 30 mg of sodium percarbonate is added per litre of milk... The activation of the lactoperoxidase system should be carried out within 2-3 hours from the time of milking."}},{"id":"milk-meat-hygiene--milk-raw-storage--วิธีรักษาคุณภาพแบบอื่น--v3","statement":"แนวทาง Codex ระบุว่าให้ใช้ระบบ lactoperoxidase เฉพาะเมื่อไม่สามารถใช้ระบบทำความเย็นได้ ฤทธิ์เป็นแบบ bacteriostatic เป็นหลักจึงไม่สามารถใช้กลบน้ำนมคุณภาพต่ำที่มีเชื้อสูงอยู่แต่เดิม และไม่ได้ทดแทนความจำเป็นในการพาสเจอร์ไรส์ก่อนบริโภค ตรงกับที่คำบรรยายว่าไม่ทำให้นมสะอาดขึ้นและห้ามใช้กับนมพร้อมดื่ม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-1991","locator":"Sections 2.2, 3.1 and 3.6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Due to the mainly bacteriostatic effect of the system it is not possible to disguise poor quality milk, which originally contained a high bacterial population, by applying this method... The use of the lactoperoxidase method does not exclud"}},{"id":"milk-meat-hygiene--milk-raw-storage--วิธีรักษาคุณภาพแบบอื่น--v4","statement":"การใช้ hydrogen peroxide ถนอมน้ำนมใช้ที่ความเข้มข้นสูง 300 ถึง 800 ppm ซึ่งครอบคลุมร้อยละ 0.03 ถึง 0.05 ที่คำบรรยายระบุ และวิธีนี้ไม่เป็นที่ยอมรับทั่วไปเพราะควบคุมการใช้ยาก อาจถูกนำไปกลบน้ำนมสุขอนามัยต่ำ และมีข้อกังวลด้านพิษวิทยา สนับสนุนที่คำบรรยายว่าไม่นิยมใช้แล้ว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-1991","locator":"Introduction and section 2.4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"this method has not achieved any general acceptance as it has several drawbacks, most important of which is the difficulty of controlling its use... The high concentrations of hydrogen peroxide used to preserve milk (300-800 ppm), destroy t"}}]},"milk-meat-hygiene--milk-raw-storage--การขนส่งน้ำนมดิบ":{"claims":[{"id":"milk-meat-hygiene--milk-raw-storage--การขนส่งน้ำนมดิบ--v1","statement":"มาตรฐานกำหนดให้เวลาขนส่งจากจุดรับน้ำนมแห่งแรกถึงศูนย์รวมนมไม่เกิน 2 ชั่วโมง และหากส่งไม่ทันต้องลดอุณหภูมิลงถึง 4 องศาเซลเซียสหรือต่ำกว่าภายใน 2 ชั่วโมงหลังรีด แล้วส่งถึงศูนย์รวมนมภายใน 24 ชั่วโมง ตรงกับเงื่อนไข 2 ชั่วโมงหลังรีดที่คำบรรยายเน้น","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 9.1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"If milk is unable to transfer at that time, control temperature shall be reduced to 4 degrees C or below within two hours after milking and directly transferred to a collection centre within 24 hours."}},{"id":"milk-meat-hygiene--milk-raw-storage--การขนส่งน้ำนมดิบ--v2","statement":"มาตรฐานกำหนดว่ารถบรรทุกที่ส่งน้ำนมไปโรงงานแปรรูปต้องออกแบบให้รักษาอุณหภูมิได้อย่างมีประสิทธิภาพ และป้องกันการปนเปื้อนรวมถึงการปลอมปนระหว่างขนส่ง สนับสนุนข้อกำหนดเรื่องพาหนะที่มีฉนวนกันความร้อนและรักษาอุณหภูมิ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Section 9.5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk trucks for delivery to the processing plant shall be designed to effectively maintain temperature and prevent contaminations as well as adulterations during transport."}}]}},"milk-meat-hygiene--milk-products-storage":{"milk-meat-hygiene--milk-products-storage--storage-methodology-per-product-class":{"claims":[{"id":"milk-meat-hygiene--milk-products-storage--storage-methodology-per-product-class--v1","statement":"Pasteurisation ของน้ำนมดิบและผลิตภัณฑ์นมต้องใช้อย่างน้อย 72°C นาน 15 วินาที หรืออย่างน้อย 63°C นาน 30 นาที หรือ combination ที่เทียบเท่า โดยผล alkaline phosphatase (ALP) test ทันทีหลังการให้ความร้อนต้องเป็น negative","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33968255","locator":"EFSA Journal 2021;19(4):e06576","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pasteurisation of raw milk, colostrum, dairy or colostrum-based products must be achieved using at least 72°C for 15 s, at least 63°C for 30 min or any equivalent combination, such that the alkaline phosphatase (ALP) test immediately after"}},{"id":"milk-meat-hygiene--milk-products-storage--storage-methodology-per-product-class--v2","statement":"สำหรับนมโค ผล ALP test ที่ถือว่า negative คือ activity ≤ 350 milliunits ต่อลิตร (mU/L) วัดด้วย ISO 11816-1 โดย ALP activity ในน้ำนมแกะดิบสูงกว่านมโคประมาณ 3 เท่า และในน้ำนมแพะต่ำกว่านมโคประมาณ 5 เท่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33968255","locator":"EFSA Journal 2021;19(4):e06576","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For cows' milk, a negative result is when the measured activity is ≤ 350 milliunits of enzyme activity per litre (mU/L) using the ISO standard 11816-1 ... ALP activity in raw ovine milk appears to be about three times higher and in caprine"}},{"id":"milk-meat-hygiene--milk-products-storage--storage-methodology-per-product-class--v3","statement":"ระดับ somatic cell count (SCC) ที่สูงในน้ำนมดิบสัมพันธ์กับปริมาณ heat-stable protease (plasmin) และ lipase (lipoprotein lipase) ที่มากขึ้น ซึ่งย่อย protein และ fat ระหว่างการเก็บแบบ refrigerated ทำให้เกิด off-flavour ในนม pasteurized แม้ไม่มีเชื้อเติบโต","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16527874","locator":"J Dairy Sci 2006;89 Suppl 1:E15-9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Increased SCC is correlated with increased amounts of heat-stable protease (plasmin) and lipase (lipoprotein lipase) in milk. When starting with raw milk that has a low bacterial count, and in the absence of microbial growth in pasteurized"}},{"id":"milk-meat-hygiene--milk-products-storage--storage-methodology-per-product-class--v4","statement":"ในสหรัฐฯ ช่วงปี 2009-2014 ผลิตภัณฑ์นมที่ไม่ผ่าน pasteurization ก่อให้เกิดการเจ็บป่วยจาก outbreak มากกว่าผลิตภัณฑ์ที่ผ่าน pasteurization ประมาณ 840 เท่า (95% CrI 611-1,158) และการเข้าโรงพยาบาลมากกว่าประมาณ 45 เท่า (95% CrI 34-59)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28518026","locator":"Emerg Infect Dis 2017;23(6):957-964","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Unpasteurized dairy products thus cause 840 (95% CrI 611-1,158) times more illnesses and 45 (95% CrI 34-59) times more hospitalizations than pasteurized products."}}]},"milk-meat-hygiene--milk-products-storage--abnormalities-of-milk-3-categories":{"claims":[{"id":"milk-meat-hygiene--milk-products-storage--abnormalities-of-milk-3-categories--v1","statement":"Contaminated milk จาก antibiotic residue เป็นปัญหาที่ตรวจพบได้จริง ในการศึกษาที่ Sidama ประเทศเอธิโอเปีย พบ residue positive 29/324 ตัวอย่าง (9%) ด้วย Delvotest SP โดย HPLC ยืนยัน oxytetracycline 2.5% และ penicillin G 4.9% ซึ่ง penicillin G สูงถึง 142.38 µg/L เกิน Codex Alimentarius MRL อย่างชัดเจน และการไม่ปฏิบัติตาม withdrawal period สัมพันธ์กับการพบ residue อย่างมีนัยสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42130764","locator":"Vet Med Int 2026;2026:1579502","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Out of 324 milk samples tested, 29 (9%) were positive for antibiotic residues using the Delvotest SP kit. (HPLC confirmed oxytetracycline (OTC) in 8 (2.5%) samples and penicillin G (PnG) in 16 (4.9%) samples. The mean OTC concentration was"}},{"id":"milk-meat-hygiene--milk-products-storage--abnormalities-of-milk-3-categories--v2","statement":"Colostrum ถูกจัดการแยกจากน้ำนมปกติตามกฎหมาย คือต้อง store แยกและ cool ทันทีให้ไม่เกิน 8°C ถ้าเก็บทุกวัน หรือไม่เกิน 6°C ถ้าไม่ได้เก็บทุกวัน หรือแช่แข็ง จึงไม่ถูกส่งเข้ารวมกับ raw milk ที่จำหน่าย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-european-union-europea-2004","locator":"Annex III, Section IX, Chapter I, Part II(B), point 2(b)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Colostrum must be stored separately and immediately cooled to not more than 8 oC in the case of daily collection, or not more than 6 oC if collection is not daily, or frozen"}}]},"milk-meat-hygiene--milk-products-storage--dairy-milk-products-definition":{"claims":[{"id":"milk-meat-hygiene--milk-products-storage--dairy-milk-products-definition--v1","statement":"นิยามสากล: milk คือ normal mammary secretion ของสัตว์รีดนม ที่ได้จากการรีดหนึ่งครั้งหรือมากกว่า โดยไม่มีการเติมหรือแยกสิ่งใดออก และ milk product คือผลิตภัณฑ์ที่ได้จากการแปรรูปน้ำนมด้วยกระบวนการใดก็ตาม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-fao-who-codex-alimenta-1999","locator":"Section 2.1 (Milk) and Section 2.2 (Milk product)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"2.1 Milk is the normal mammary secretion of milking animals obtained from one or more milkings without either addition to it or extraction from it, intended for consumption as liquid milk or for further processing."}},{"id":"milk-meat-hygiene--milk-products-storage--dairy-milk-products-definition--v2","statement":"วัวเป็นแหล่งน้ำนมหลักของโลกจริง โดยผลิตประมาณ 83% ของน้ำนมและผลิตภัณฑ์นมที่มนุษย์บริโภคทั่วโลก ส่วนที่เหลือมาจาก buffalo, goat, sheep, camel และ equine species","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34955249","locator":"Vol 105(3):2132-2152, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Bovines produce about 83% of the milk and dairy products consumed by humans worldwide, the rest represented by bubaline, caprine, ovine, camelid, and equine species, which are particularly important in areas of extensive pastoralism."}}]},"milk-meat-hygiene--milk-products-storage--ความผิดปกติของนม-และหลักการเก็บ":{"claims":[{"id":"milk-meat-hygiene--milk-products-storage--ความผิดปกติของนม-และหลักการเก็บ--v1","statement":"กฎหมายไทยรองรับแนวคิด undesirable milk และ contaminated milk ที่สไลด์อธิบาย โดยกำหนดว่าน้ำนมโคสดหรือน้ำนมโคต้องไม่มีน้ำนมเหลืองเจือปน และต้องไม่มีสารที่อาจเป็นพิษหรือสารปนเปื้อนในปริมาณที่อาจเป็นอันตรายต่อสุขภาพ เช่น สารตกค้างจากยาฆ่าแมลง สารปฏิชีวนะ และอะฟลาทอกซิน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2556","locator":"ข้อ 7 (2) และ (5)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ไม่มีน้ำนมเหลืองเจือปน ... ไม่มีสารที่อาจเป็นพิษ สารเป็นพิษจากจุลินทรีย์ และสารปนเปื้อน ในปริมาณที่อาจเป็นอันตรายต่อสุขภาพ เช่น สารตกค้างจากยาฆ่าแมลง สารปฏิชีวนะ แอฟลาทอกซิน เป็นต้น"}}]},"milk-meat-hygiene--milk-products-storage--อายุการเก็บของแต่ละผลิตภัณฑ์":{"claims":[{"id":"milk-meat-hygiene--milk-products-storage--อายุการเก็บของแต่ละผลิตภัณฑ์--v1","statement":"กฎหมายไทยกำหนดพาสเจอร์ไรส์ไว้สองทางเลือกคือ อุณหภูมิไม่ต่ำกว่า 63 องศาเซลเซียส คงอยู่ไม่น้อยกว่า 30 นาที หรือไม่ต่ำกว่า 72 องศาเซลเซียส คงอยู่ไม่น้อยกว่า 15 วินาที แล้วต้องทำให้เย็นลงทันทีที่อุณหภูมิ 5 องศาเซลเซียสหรือต่ำกว่า ตรงกับคู่ LTLT และ HTST ที่เอกสารสรุประบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2556","locator":"ข้อ 6 (1) (1.1) และ (1.2)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"อุณหภูมิไม่ต่ำกว่า 63 องศาเซลเซียส และคงอยู่ที่อุณหภูมินี้ไม่น้อยกว่า 30 นาที แล้วทำให้เย็นลงทันทีที่อุณหภูมิ 5 องศาเซลเซียส หรือต่ำกว่า หรือ อุณหภูมิไม่ต่ำกว่า 72 องศาเซลเซียส และคงอยู่ที่อุณหภูมินี้ไม่น้อยกว่า 15 วินาที"}},{"id":"milk-meat-hygiene--milk-products-storage--อายุการเก็บของแต่ละผลิตภัณฑ์--v2","statement":"สเตอริไลส์ตามนิยามของกฎหมายไทยคือการฆ่าเชื้อน้ำนมโคที่บรรจุในภาชนะที่ปิดสนิทด้วยความร้อนที่อุณหภูมิไม่ต่ำกว่า 100 องศาเซลเซียส โดยใช้เวลาที่เหมาะสม สอดคล้องกับที่เอกสารสรุประบุว่าใช้ความร้อนสูงกว่า 100 องศาเซลเซียสเป็นเวลานาน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2556","locator":"ข้อ 6 (2)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"สเตอริไลส์ หมายความว่า กรรมวิธีฆ่าเชื้อน้ำนมโคที่บรรจุในภาชนะที่ปิดสนิทด้วยความร้อนที่อุณหภูมิไม่ต่ำกว่า 100 องศาเซลเซียส โดยใช้เวลาที่เหมาะสม"}}]}},"milk-meat-hygiene--milk-quality-determination":{"milk-meat-hygiene--milk-quality-determination--methods-of-milk-quality-testing":{"claims":[{"id":"milk-meat-hygiene--milk-quality-determination--methods-of-milk-quality-testing--v1","statement":"เกณฑ์ EU สำหรับน้ำนมโคดิบกำหนด somatic cell count (SCC) ≤ 400,000 cells/mL คิดเป็น rolling geometric average ในช่วง 3 เดือน โดยเก็บตัวอย่างอย่างน้อย 1 ตัวอย่าง/เดือน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-european-union-europea-2004","locator":"Annex III, Section IX, Chapter I, Part III (Criteria for raw milk and colostrum)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Somatic cell count: ≤ 400 000 [per ml] ... Rolling geometric average over a three-month period, with at least one sample per month, unless the competent authority specifies another methodology to take account of seasonal variations in produ"}},{"id":"milk-meat-hygiene--milk-quality-determination--methods-of-milk-quality-testing--v2","statement":"เกณฑ์ EU สำหรับน้ำนมโคดิบกำหนด plate count ที่ 30°C (total bacterial count, TBC) ≤ 100,000 cfu/mL คิดเป็น rolling geometric average ในช่วง 2 เดือน โดยเก็บตัวอย่างอย่างน้อย 2 ตัวอย่าง/เดือน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-european-union-europea-2004","locator":"Annex III, Section IX, Chapter I, Part III (Criteria for raw milk and colostrum)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Plate Count at 30°C: ≤ 100 000 [per ml] ... Rolling geometric average over a two-month period, with at least two samples per month."}},{"id":"milk-meat-hygiene--milk-quality-determination--methods-of-milk-quality-testing--v3","statement":"SCC เป็น screening test ไม่ใช่ definitive test สำหรับ intramammary infection (IMI) ที่ threshold 200,000 cells/mL จากการตรวจ quarter-composite SCC ครั้งเดียว ได้ sensitivity 44.3% และ specificity 87.3% สำหรับการติดเชื้อจาก pathogen ใดก็ตาม และ sensitivity 65.1% specificity 73.0% สำหรับ major pathogens","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27544856","locator":"J Dairy Sci 2016;99(11):9271-9286","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The overall Se and Sp at a threshold of 200,000 cells/mL for a single quarter-cSCC observation obtained closest to the time of bacteriologic culture were 44.3 and 87.3%, respectively, for cows infected with any pathogen, and 65.1 and 73.0%,"}},{"id":"milk-meat-hygiene--milk-quality-determination--methods-of-milk-quality-testing--v4","statement":"Resazurin reduction test ใช้ติดตามการปนเปื้อนของ bacteria และ yeast ในน้ำนมมานานราว 50 ปี โดยอาศัยลำดับการเปลี่ยนสี คือ resazurin (สีน้ำเงิน ไม่เรืองแสง) ถูก reduce เป็น resorufin (สีชมพู เรืองแสงสูง) แล้วถูก reduce ต่อเป็น hydroresorufin (ไม่มีสี ไม่เรืองแสง)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10951200","locator":"Eur J Biochem 2000;267(17):5421-6","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The 'resazurin reduction test' has been used for about 50 years to monitor bacterial and yeast contamination of milk, and also for assessing semen quality. Resazurin (blue and nonfluorescent) is reduced to resorufin (pink and highly fluores"}},{"id":"milk-meat-hygiene--milk-quality-determination--methods-of-milk-quality-testing--v5","statement":"Methylene blue reduction time (RTMB) สั้นลงเมื่อการปนเปื้อนของจุลินทรีย์ในน้ำนมสูงขึ้น ในการศึกษาที่แอลจีเรีย RTMB ลดลงประมาณ 54% สอดคล้องกับการเพิ่มขึ้นอย่างมีนัยสำคัญของ total mesophilic aerobic bacteria, coliforms, yeasts และ molds ระหว่างจุดเก็บตัวอย่างสองจุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25374932","locator":"ScientificWorldJournal 2014;2014:131593","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The average contamination by total mesophilic aerobic bacteria (TMAB), coliforms, yeasts, molds, and different pathogens in samples taken at M1 showed significant changes at M2. This was confirmed by the decrease of reduction time of methyl"}},{"id":"milk-meat-hygiene--milk-quality-determination--methods-of-milk-quality-testing--v6","statement":"Alcohol test สะท้อนความไม่เสถียรของ casein micelle ต่อ ionic balance ตัวอย่างน้ำนมที่ไม่เสถียรต่อ ethanol 72% v/v มีค่า pH, casein และ non-fat-solids ต่ำกว่า และมี freezing point, chloride, sodium และ potassium สูงกว่าตัวอย่างที่เสถียรที่ ethanol 78% v/v ขึ้นไป โดยตัวแปรที่เข้าสู่ logistic model ของ alcohol stability คือ chloride, potassium, ionic calcium และ somatic cell count","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15190949","locator":"J Dairy Res 2004;71(2):201-6","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Unstable samples to ethanol (72%, v/v) presented lower values of pH, somatic cells count, casein and non-fat-solids relative to ethanol stable samples (ethanol at 78%, v/v or more); whereas freezing point, chloride, sodium and potassium con"}}]},"milk-meat-hygiene--milk-quality-determination--objectives-of-milk-quality-determination":{"claims":[{"id":"milk-meat-hygiene--milk-quality-determination--objectives-of-milk-quality-determination--v1","statement":"การป้องกัน milk adulteration และความผิดปกติในทารกเป็นวัตถุประสงค์ที่มีเหตุผลรองรับจริง: การปนเปื้อน melamine ใน milk-based infant formula ที่ประเทศจีน ทำให้เกิดการระบาดของ nephrolithiasis และ acute kidney injury ในเด็ก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19212415","locator":"Vol 75(8):774-9, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Recent outbreaks of nephrolithiasis and acute kidney injury among children in China have been linked to ingestion of milk-based infant formula contaminated with melamine."}},{"id":"milk-meat-hygiene--milk-quality-determination--objectives-of-milk-quality-determination--v2","statement":"การป้องกัน zoonosis เป็นวัตถุประสงค์ที่มีเหตุผลรองรับ: brucellosis จัดเป็นหนึ่งใน neglected zoonotic diseases หลัก และผู้ป่วยส่วนใหญ่สัมพันธ์กับการบริโภคผลิตภัณฑ์นมที่ไม่ผ่าน pasteurization","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27185403","locator":"Vol 14(3):182-99, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Brucellosis is one of the main neglected zoonotic diseases. ... Most imported cases were associated with traditional risk factors such as travel/consumption of unpasteurized dairy products in endemic countries."}},{"id":"milk-meat-hygiene--milk-quality-determination--objectives-of-milk-quality-determination--v3","statement":"ความเสี่ยง milk-borne disease ยังเป็นประเด็นปัจจุบัน: มีการตรวจพบ viral load ของ highly pathogenic avian influenza H5N1 ในปริมาณสูงในน้ำนมดิบจากโคนม ทำให้เกิดความกังวลเรื่อง zoonotic transmission","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40137763","locator":"Vol 14(3), article 278, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Alarmingly, significant virus loads have been discovered in raw milk, raising worries about potential zoonotic transmission."}}]},"milk-meat-hygiene--milk-quality-determination--three-goals":{"claims":[{"id":"milk-meat-hygiene--milk-quality-determination--three-goals--v1","statement":"เป้าหมาย consumer protection มีฐานรองรับในมาตรฐานสากล: หลักการทั่วไปของ Codex กำหนดให้อาหารต้องถูกบรรยายหรือนำเสนอในลักษณะที่ปกป้องผู้บริโภคจากความสับสนหรือการถูกทำให้เข้าใจผิด และประกันการค้าที่เป็นธรรม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-fao-who-codex-alimenta-1999","locator":"Section 3, General Principles","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Foods shall be described or presented in such a manner as to ensure the correct use of dairy terms intended for milk and milk products, to protect consumers from being confused or misled and to ensure fair practices in the food trade."}},{"id":"milk-meat-hygiene--milk-quality-determination--three-goals--v2","statement":"กรอบเป้าหมายของระบบมาตรฐานอาหารสากลคือ 2 เป้าหมายหลัก ได้แก่ การคุ้มครองสุขภาพผู้บริโภค และการประกันการค้าที่เป็นธรรม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21382429","locator":"Vol 60(1):161-4, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Codex has two primary aims: to protect consumers' health and assure fair practices in food trade."}},{"id":"milk-meat-hygiene--milk-quality-determination--three-goals--v3","statement":"เป้าหมาย milk price assurance สอดคล้องกับการปฏิบัติจริงในอุตสาหกรรม: สหกรณ์โคนมจ่าย premium quality payment ให้เกษตรกรเพื่อจูงใจให้ค่า somatic cell count ต่ำ แต่ยังไม่มีข้อมูลทางวิทยาศาสตร์ที่ชัดเจนว่าระดับ SCC ใดใน bulk tank milk ที่ให้ประโยชน์ด้านคุณภาพน้ำนมเพิ่มขึ้นจริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16569277","locator":"Vol 73(3):299-305, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"dairy cooperatives give farmers a premium quality payment to encourage low SCC although there is no clear scientific data defining the level of SCC in bulk tank milk that is associated with additional benefits in terms of milk quality"}}]},"milk-meat-hygiene--milk-quality-determination--จับคู่เครื่องมือกับค่าที่วัด":{"claims":[{"id":"milk-meat-hygiene--milk-quality-determination--จับคู่เครื่องมือกับค่าที่วัด--v1","statement":"Delvotest เป็นชุดทดสอบแบบ microbial inhibitor test ที่ใช้ตรวจการตกค้างของยาต้านจุลชีพในน้ำนม และไวต่อกลุ่ม beta-lactam รวมถึง cephalonium ตรงกับที่คำบรรยายจับคู่ไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10212456","locator":"Volume 82, issue 4, pages 704-711, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Delvotest Cow Test... an on-farm version of Delvotest P, a microbial inhibitor test for antimicrobials, is being increasingly used by farmers to assess that milk from individual cows is fit for consignment to the bulk tank."}},{"id":"milk-meat-hygiene--milk-quality-determination--จับคู่เครื่องมือกับค่าที่วัด--v2","statement":"มาตรฐานน้ำนมโคดิบของไทยกำหนดวิธีวิเคราะห์โปรตีนด้วยหลักการ titrimetry แบบ Kjeldahl ตาม ISO 8968 หรือ IDF 20 และวิเคราะห์ความถ่วงจำเพาะด้วยหลักการ densitometry แบบ lactometric method ยืนยันการจับคู่ Kjeldahl กับโปรตีน และ lactodensitometer กับความถ่วงจำเพาะ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Table 1 Methods of analysis of raw milk, items 5 and 9","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"9. Protein content (section 3.10) | ISO 8968/IDF 20 | Titrimetry (Kjeldahl) ... 5. Specific gravity (section 3.6) | Standard methods for the Examination of Dairy Products, chapter 15.10 G Solid in Milk: lactometric method, APHA | Densitomet"}}]},"milk-meat-hygiene--milk-quality-determination--ค่าที่-snf-มีผลและไม่มีผล":{"claims":[{"id":"milk-meat-hygiene--milk-quality-determination--ค่าที่-snf-มีผลและไม่มีผล--v1","statement":"กฎหมายไทยนิยามพาสเจอร์ไรส์ว่าเป็นกรรมวิธีฆ่าเชื้อด้วยความร้อนที่ลดจุลินทรีย์ให้อยู่ในระดับปลอดภัยและยับยั้งการทำงานของเอนไซม์ฟอสฟาเทส ยืนยันว่า phosphatase คือเอนไซม์ที่ผูกกับการตรวจสอบการพาสเจอร์ไรส์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--130-87--2013","locator":"ข้อ 6 (1) หน้า 63","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"พาสเจอร์ไรส์ หมายความว่า กรรมวิธีฆ่าเชื้อด้วยความร้อนเพื่อลดปริมาณจุลินทรีย์ ให้อยู่ในระดับที่ปลอดภัยต่อผู้บริโภคและยับยั้งการทำงานของเอนไซม์ฟอสฟาเทส"}},{"id":"milk-meat-hygiene--milk-quality-determination--ค่าที่-snf-มีผลและไม่มีผล--v2","statement":"การเหม็นหืนของน้ำนมเกิดจากระบบ lipolysis โดยเอนไซม์ lipoprotein lipase ซึ่งปลดปล่อยกรดไขมันสายสั้นออกมา สนับสนุนที่คำบรรยายว่า lipase สัมพันธ์กับการเหม็นหืนมากที่สุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12778586","locator":"Volume 86, issue 5, pages 1751-1770, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Peculiarities of goat milk FA composition and lipolytic system play an important role in the development of either goat flavor (release of branched, medium-chain FA) or rancidity (excessive release of butyric acid). The lipoprotein lipase ("}}]},"milk-meat-hygiene--milk-quality-determination--การตรวจแบบรวดเร็วและการตรวจเต้านมอักเสบ":{"claims":[{"id":"milk-meat-hygiene--milk-quality-determination--การตรวจแบบรวดเร็วและการตรวจเต้านมอักเสบ--v1","statement":"มาตรฐานน้ำนมโคดิบของไทยระบุหลักการของทั้ง alcohol test และ clot on boiling test ว่าเป็น stability of protein in milk ตรงกับที่คำบรรยายว่าการตรวจแบบรวดเร็วอาศัยความคงตัวของโปรตีน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-national-bureau-of-agr-2010","locator":"Table 1 Methods of analysis of raw milk, items 2.1 and 2.2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"2.1 Alcohol test | IDF Special Issue No.9002 Handbook on Milk Collection | Stability of protein in milk 2.2 Clot on boiling test | IDF Special Issue No.9002 Handbook on Milk Collection | Stability of protein in milk"}},{"id":"milk-meat-hygiene--milk-quality-determination--การตรวจแบบรวดเร็วและการตรวจเต้านมอักเสบ--v2","statement":"การวัดค่าการนำไฟฟ้าของน้ำนมใช้ตรวจเต้านมอักเสบแบบไม่แสดงอาการได้แม่นยำเทียบเท่าวิธีทางอ้อมอื่น และเป็นตัวชี้วัดที่แม่นกว่ากลุ่มอื่นร่วมกับปริมาณคลอไรด์และโซเดียม สนับสนุนที่คำบรรยายว่าค่าการนำไฟฟ้าขึ้นกับ Na และ Cl เป็นสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3989085","locator":"Volume 68, issue 2, pages 449-456, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Electrical conductivity, chloride, and sodium content of milk were more accurate for predicting infection status of quarters than were other variables."}},{"id":"milk-meat-hygiene--milk-quality-determination--การตรวจแบบรวดเร็วและการตรวจเต้านมอักเสบ--v3","statement":"NAGase คือเอนไซม์ lysosomal N-acetyl-beta-D-glucosaminidase ที่ใช้เป็นตัวบ่งชี้เต้านมอักเสบทั้งแบบแสดงอาการและไม่แสดงอาการ และกิจกรรมของมันส่วนหนึ่งมาจากเซลล์เยื่อบุเต้านมที่ถูกทำลาย ไม่ใช่จากเซลล์โซมาติกอย่างเดียว ตรงกับที่คำบรรยายอธิบาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27210494","locator":"Volume 83, issue 2, pages 219-227, abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Our results indicate that NAGase activity can be used to detect both subclinical and clinical mastitis with a high level of accuracy... Incomplete correlation between NAGase activity and SCC suggests that a substantial proportion of NAGase "}}]}},"milk-meat-hygiene--milk-microbiology":{"milk-meat-hygiene--milk-microbiology--microorganisms-in-milk-2-main-groups":{"claims":[{"id":"milk-meat-hygiene--milk-microbiology--microorganisms-in-milk-2-main-groups--v1","statement":"Psychrotrophic bacteria ที่แยกได้จากน้ำนมดิบ สร้าง protease และ lipase ที่ยังคงมี activity หลังผ่านความร้อน 70, 80 หรือ 90 องศาเซลเซียส โดย protease ทนความร้อนได้มากกว่า lipase","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30070086","locator":"19(8):630-642","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Proteases and lipases produced by psychrotrophic bacteria retained activity after heat treatment at 70, 80, or 90 °C, and proteases appeared to be more heat-stable than lipases."}},{"id":"milk-meat-hygiene--milk-microbiology--microorganisms-in-milk-2-main-groups--v2","statement":"ระหว่างการเก็บน้ำนมดิบที่อุณหภูมิต่ำหลังรีดนม ประชากร psychrotroph จะกลายเป็น dominant microflora และ Pseudomonas กับ Acinetobacter เป็น genera เด่นซึ่งแสดง lipolytic activity เป็นหลัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17890340","locator":"73(22):7162-8","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"During cold storage after milk collection, psychrotrophic bacterial populations dominate the microflora, and their extracellular enzymes, mainly proteases and lipases, contribute to the spoilage of dairy products. ... The dominant genera, P"}},{"id":"milk-meat-hygiene--milk-microbiology--microorganisms-in-milk-2-main-groups--v3","statement":"Bacillus cereus group เป็น spore-forming organism ที่พบบ่อยว่าเกี่ยวข้องกับ spoilage ของนมและผลิตภัณฑ์นม และเป็น Bacillus group ที่ dominant ในนมพาสเจอร์ไรส์ที่เก็บไว้ โดยเจริญได้ในสภาวะเก็บที่ไม่เหมาะสม (8 องศาเซลเซียส)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30910086","locator":"81:32-39","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Members of the Bacillus cereus sensu lato (B. cereus group) are spore-forming organisms commonly associated with spoilage of milk and dairy products. ... Our results show that the B. cereus group is the dominant Bacillus group in stored con"}},{"id":"milk-meat-hygiene--milk-microbiology--microorganisms-in-milk-2-main-groups--v4","statement":"Mycobacterium bovis ติดต่อสู่คนโดยหลักผ่านการบริโภคผลิตภัณฑ์จากโคที่ปนเปื้อน เช่น น้ำนมที่ไม่ผ่าน pasteurization หรือเนื้อดิบ หรือผ่านการสัมผัสใกล้ชิดกับโคที่ติดเชื้อ โดยคนเป็น incidental host","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33725176","locator":"94(6):1147-1171","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Humans are the incidental hosts of M. bovis whereby its transmission to humans is primarily through the consumption of cattle products such as unpasteurized milk or raw meat products that have been contaminated with M. bovis or the transmis"}}]},"milk-meat-hygiene--milk-microbiology--sources-of-contamination-indicator-organisms":{"claims":[{"id":"milk-meat-hygiene--milk-microbiology--sources-of-contamination-indicator-organisms--v1","statement":"หลายประเทศใช้ Escherichia coli และ coliforms เป็น indicator ของ sanitary quality ในอาหาร และตั้ง limit ไว้สำหรับ cheese รวมถึง cheese ที่ทำจากนมดิบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31500718","locator":"85:103283","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Many countries use Escherichia coli and coliforms as indicators of sanitary quality of foods and have set limits for cheeses, including raw-milk cheeses."}},{"id":"milk-meat-hygiene--milk-microbiology--sources-of-contamination-indicator-organisms--v2","statement":"จากการสำรวจ raw drinking milk ที่วางขายปลีกในอังกฤษ 902 ตัวอย่าง มี 229 ตัวอย่าง (25.4%) ที่ไม่ผ่านเกณฑ์เพราะ aerobic colony count และ/หรือ coliforms สูงเกิน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29215775","locator":"124(2):535-546","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A total of 229 of 902 samples (25·4%) gave unsatisfactory results due to elevated aerobic colony counts and/or coliforms, whilst 139 of 902 samples (15·4%) were of borderline quality due to coagulase-positive staphylococci."}}]},"milk-meat-hygiene--milk-microbiology--why-milk-good-microbial-growth-medium":{"claims":[{"id":"milk-meat-hygiene--milk-microbiology--why-milk-good-microbial-growth-medium--v1","statement":"น้ำนมมีคุณค่าทางโภชนาการสูง จึงรองรับการเจริญของจุลินทรีย์ได้หลากหลายชนิด (rich microbiota)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23808865","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk, due to its high nutritional content, can support a rich microbiota."}},{"id":"milk-meat-hygiene--milk-microbiology--why-milk-good-microbial-growth-medium--v2","statement":"น้ำนมและผลิตภัณฑ์จากน้ำนมสามารถมีจุลินทรีย์ได้หลายชนิดและเป็นแหล่งสำคัญของเชื้อก่อโรคที่มากับอาหาร ถ้าไม่ผ่านกระบวนการฆ่าเชื้อ โดยมีรายงานการระบาดในคนที่สืบย้อนไปถึงการดื่มนมดิบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15992306","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk and products derived from milk of dairy cows can harbor a variety of microorganisms and can be important sources of foodborne pathogens."}}]},"milk-meat-hygiene--milk-microbiology--จุลินทรีย์ในนม-และแหล่งปนเปื้อน":{"claims":[{"id":"milk-meat-hygiene--milk-microbiology--จุลินทรีย์ในนม-และแหล่งปนเปื้อน--v1","statement":"ระหว่างการเก็บรักษาน้ำนมดิบที่อุณหภูมิต่ำหลังการรีด กลุ่มแบคทีเรีย psychrotroph จะครองสัดส่วนหลักของจุลินทรีย์ในน้ำนม และเอนไซม์นอกเซลล์ของเชื้อกลุ่มนี้ ซึ่งส่วนใหญ่คือ protease และ lipase เป็นตัวทำให้ผลิตภัณฑ์นมเสีย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17890340","locator":"Abstract; 73(22):7162-7168","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"During cold storage after milk collection, psychrotrophic bacterial populations dominate the microflora, and their extracellular enzymes, mainly proteases and lipases, contribute to the spoilage of dairy products."}}]},"milk-meat-hygiene--milk-microbiology--ปัจจัยการเจริญ-และการควบคุม":{"claims":[{"id":"milk-meat-hygiene--milk-microbiology--ปัจจัยการเจริญ-และการควบคุม--v1","statement":"การแช่เย็นไม่ได้กำจัดเชื้อ แต่กลับให้ข้อได้เปรียบเชิงคัดเลือกแก่แบคทีเรีย psychrotroph ที่สร้าง protease และ lipase ทนความร้อน ตรงกับที่สไลด์ระบุว่า refrigeration ชะลอการเจริญแต่ไม่กำจัด psychrotrophs","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26221110","locator":"Abstract; 46(1):207-217","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The practice of refrigerating raw milk at the farm has provided a selective advantage for psychrotrophic bacteria that produce heat-stable proteases and lipases causing severe quality problems to the dairy industry."}}]},"milk-meat-hygiene--milk-microbiology--indicator-bacteria":{"claims":[{"id":"milk-meat-hygiene--milk-microbiology--indicator-bacteria--v1","statement":"มาตรฐานนมโคของไทยใช้จุลินทรีย์บ่งชี้ตามที่สไลด์อธิบาย คือกำหนดจำนวนแบคทีเรียทั้งหมดในน้ำนมโคพาสเจอร์ไรส์ไม่เกิน 10,000 ต่อมิลลิลิตร ณ แหล่งผลิต กำหนดโคลิฟอร์มไม่เกิน 10 ต่อมิลลิลิตร ณ แหล่งผลิต และกำหนดว่าต้องตรวจไม่พบ Escherichia coli ใน 0.1 มิลลิลิตร ซึ่งเป็นเกณฑ์ที่เข้มที่สุดในสามตัว สอดคล้องกับการใช้ E. coli เป็นตัวบ่งชี้การปนเปื้อนอุจจาระ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2556","locator":"ข้อ 7 (11) (12) และ (13)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ตรวจไม่พบแบคทีเรียชนิด อี.โคไล (Escherichia coli) ในน้ำนมโคสดหรือน้ำนมโค 0.1 มิลลิลิตร ... ตรวจพบแบคทีเรียในน้ำนมโคสดหรือน้ำนมโคพาสเจอร์ไรส์ 1 มิลลิลิตร ได้ไม่เกิน 10,000 ณ แหล่งผลิต ... ตรวจพบแบคทีเรียชนิดโคลิฟอร์มได้ไม่เกิน 10 ในน้ำนมโคสด"}}]},"milk-meat-hygiene--milk-microbiology--spoilage-bacteria":{"claims":[{"id":"milk-meat-hygiene--milk-microbiology--spoilage-bacteria--v1","statement":"เอนไซม์ protease และ lipase ที่แบคทีเรีย psychrotroph สร้างขึ้นยังคงมีกิจกรรมหลังผ่านความร้อนที่ 70, 80 หรือ 90 องศาเซลเซียส โดย protease ทนความร้อนมากกว่า lipase ยืนยันว่าเอนไซม์เหล่านี้รอดจากการพาสเจอไรซ์และก่อการเสียได้แม้ตัวเชื้อจะถูกฆ่าแล้ว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30070086","locator":"Abstract, Results; 19(8):630-642","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Proteases and lipases produced by psychrotrophic bacteria retained activity after heat treatment at 70, 80, or 90 degrees C, and proteases appeared to be more heat-stable than lipases."}},{"id":"milk-meat-hygiene--milk-microbiology--spoilage-bacteria--v2","statement":"Pseudomonas fluorescens ที่แยกจากน้ำนมดิบแช่เย็นสร้าง metalloprotease AprX ซึ่งทำงานได้แม้ที่อุณหภูมิตู้เย็นและย่อย casein ได้ดี พร้อมกับ lipase LipM ที่ออกฤทธิ์สูงสุดกับกรดไขมันสายยาว สนับสนุนกลไกรสขมและกลิ่นหืนที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26221110","locator":"Abstract, Results; 46(1):207-217","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The AprX metalloprotease exhibited activity in a broad temperature range, including refrigeration, with a maximum activity at 37 degrees C. ... This protease had maximum activity with the substrates casein and gelatin"}},{"id":"milk-meat-hygiene--milk-microbiology--spoilage-bacteria--v3","statement":"Bacillus cereus รอดจากการพาสเจอไรซ์และเพิ่มจำนวนภายหลังในนมที่แช่เย็นได้จริง โดยนมพาสเจอไรซ์ที่ 74 องศาเซลเซียส 15 วินาที พบ B. cereus ชนิด mesophilic สูงถึง 7.0 x 10 ยกกำลัง 5 CFU ต่อมิลลิลิตร ขณะที่นมที่ผ่าน ultrapasteurization 138 องศาเซลเซียส 2 วินาที ไม่พบปัญหานี้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19610345","locator":"Abstract, Results; 72(6):1301-1305","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The count of mesophilic B. cereus was restricted to samples of superpasteurized and pasteurized milk from a single trial, reaching 4.0 x 10(1) and 7.0 x 10(5) CFU/ml, respectively."}}]},"milk-meat-hygiene--milk-microbiology--starter-cultures":{"claims":[{"id":"milk-meat-hygiene--milk-microbiology--starter-cultures--v1","statement":"Streptococcus thermophilus และ Lactobacillus delbrueckii ssp. bulgaricus ทำงานร่วมกันแบบ proto-cooperation จริง โดยการเลี้ยงร่วมให้อัตราการสร้างกรดสูงกว่า คุณสมบัติทางรีโอโลยีดีกว่า สารให้กลิ่นรสมากกว่า และคุณภาพทางประสาทสัมผัสดีกว่าการเลี้ยงเชื้อเดี่ยวทั้งสองชนิด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37641256","locator":"Abstract, Results; 107(1):123-140","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the coculture group showed higher acidification activity, improved rheological properties, richer typical volatile compounds, more desirable sensor quality after the fermentation process than the other 2 groups."}},{"id":"milk-meat-hygiene--milk-microbiology--starter-cultures--v2","statement":"Bacteriophage เป็นสาเหตุหลักของการหมักล้มเหลวในโรงงานนม ตรงกับที่สไลด์ระบุว่า bacteriophage infection ทำให้ starter culture หยุดทำงาน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28039135","locator":"Abstract, opening sentence; 83(5)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Bacteriophages are the main cause of fermentation failures in dairy plants."}}]}},"milk-meat-hygiene--milk-borne-pathogens":{"milk-meat-hygiene--milk-borne-pathogens--detail-per-pathogen-brucella-listeria-salmonella-stec-mycobacter":{"claims":[{"id":"milk-meat-hygiene--milk-borne-pathogens--detail-per-pathogen-brucella-listeria-salmonella-stec-mycobacter--v1","statement":"Coxiella burnetii ถูกจัดว่าเป็น pathogen ที่ทนความร้อนมากที่สุดในน้ำนมดิบมาโดยตลอด จึงถูกใช้เป็น reference pathogen ในการกำหนดสภาวะ pasteurization ของผลิตภัณฑ์นม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26143937","locator":"82(4):478-84","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The obligate intracellular pathogen Coxiella burnetii has long been considered the most heat resistant pathogen in raw milk, making it the reference pathogen for determining pasteurisation conditions for milk products."}},{"id":"milk-meat-hygiene--milk-borne-pathogens--detail-per-pathogen-brucella-listeria-salmonella-stec-mycobacter--v2","statement":"การศึกษาที่ wildlife-livestock-human interface ในแอฟริกาใต้ยืนยันว่า zoonotic TB จาก Mycobacterium bovis ถ่ายทอดสู่คนได้ทั้งทางน้ำนมที่ไม่ผ่าน pasteurization และทาง aerosol โดยการบริโภคน้ำนมเป็น risk factor ที่สัมพันธ์กับประวัติ TB ในครัวเรือนอย่างมีนัยสำคัญสูง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31337117","locator":"8(3):101","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Ownership of a bTB infected herd and consumption of milk were recognized as highly significant risk factors associated with a history of TB in the household using multiple correspondence analysis (MCA) and logistic regression. The findings"}},{"id":"milk-meat-hygiene--milk-borne-pathogens--detail-per-pathogen-brucella-listeria-salmonella-stec-mycobacter--v3","statement":"ในการศึกษาผู้ป่วยที่มีไข้ที่ Ijara ประเทศเคนยา การบริโภคน้ำนมที่ซื้อมาสัมพันธ์กับความเสี่ยง brucellosis ที่สูงขึ้น ขณะที่การต้มน้ำนมก่อนบริโภคสัมพันธ์กับความเสี่ยงที่ลดลงอย่างชัดเจน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32236091","locator":"14(4):e0008108","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The IT and LASSO approaches both identified consuming purchased milk as strongly associated with elevated risk and boiling milk before consumption strongly associated with reduced risk."}},{"id":"milk-meat-hygiene--milk-borne-pathogens--detail-per-pathogen-brucella-listeria-salmonella-stec-mycobacter--v4","statement":"จากการเฝ้าระวังผู้ป่วยโรคติดเชื้อทางเดินอาหารในรัฐมินนิโซตา พบ hemolytic uremic syndrome ใน 21% ของผู้ป่วยที่ติดเชื้อ Escherichia coli O157 ซึ่งมีประวัติดื่มน้ำนมดิบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24520559","locator":"20(1):38-44","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Severe illness was noted, including hemolytic uremic syndrome among 21% of Escherichia coli O157-infected patients reporting raw milk consumption, and 1 death was reported."}},{"id":"milk-meat-hygiene--milk-borne-pathogens--detail-per-pathogen-brucella-listeria-salmonella-stec-mycobacter--v5","statement":"การสำรวจฟาร์มโคนมในสหรัฐฯ ตรวจพบ Campylobacter spp. ใน bulk tank milk หรือ milk filter ที่ 24.9% ของฟาร์ม (weighted prevalence) โดย 91.8% ของ isolate เป็น Campylobacter jejuni","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28237599","locator":"100(5):3470-3479","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The weighted prevalence of operations from which we detected Campylobacter spp. in either bulk tank milk or milk filters was 24.9%. ... The majority (91.8%) of isolates were C. jejuni, but C. lari and C. coli were also isolated."}}]},"milk-meat-hygiene--milk-borne-pathogens--sources-of-contamination-3-categories":{"claims":[{"id":"milk-meat-hygiene--milk-borne-pathogens--sources-of-contamination-3-categories--v1","statement":"cheese ที่ทำจากนมดิบเป็น vehicle ที่ทราบกันของ human listeriosis โดยการปนเปื้อน Listeria monocytogenes ในน้ำนมอาจมาจาก farm environment หรือมาจากสัตว์ที่เป็น mastitis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27285819","locator":"37(4):661-676","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"However, raw milk cheese is also a known vehicle of human listeriosis and contamination of sheep cheese with Listeria monocytogenes has been reported. ... In the model, contamination of milk may originate from the farm environment or from m"}}]},"milk-meat-hygiene--milk-borne-pathogens--types-of-microorganisms-in-milk-products-4-functional-groups":{"claims":[{"id":"milk-meat-hygiene--milk-borne-pathogens--types-of-microorganisms-in-milk-products-4-functional-groups--v1","statement":"จุลินทรีย์ในน้ำนมแบ่งตามบทบาทได้เป็นกลุ่มที่ใช้หมัก (Lactococcus, Lactobacillus, Streptococcus, Propionibacterium และเชื้อรา), กลุ่มที่ทำให้เสื่อมเสีย (Pseudomonas, Clostridium, Bacillus และกลุ่มสร้างสปอร์หรือทนความร้อน) และกลุ่มก่อโรค (Listeria, Salmonella, Escherichia coli, Campylobacter รวมถึงราที่สร้าง mycotoxin)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23808865","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"once in milk, can play a number of roles, such as facilitating dairy fermentations (e.g. Lactococcus, Lactobacillus, Streptococcus, Propionibacterium and fungal populations), causing spoilage (e.g. Pseudomonas, Clostridium, Bacillus and oth"}}]},"milk-meat-hygiene--milk-borne-pathogens--แหล่งปนเปื้อนเชื้อก่อโรค":{"claims":[{"id":"milk-meat-hygiene--milk-borne-pathogens--แหล่งปนเปื้อนเชื้อก่อโรค--v1","statement":"เชื้อก่อโรคในน้ำนมมาจากสองทางหลัก คือการสัมผัสแหล่งปนเปื้อนในสิ่งแวดล้อมของฟาร์มโคนมโดยตรง และการขับเชื้อออกจากเต้านมของสัตว์ที่ติดเชื้อ ตรงกับการแบ่งแหล่งปนเปื้อนเป็น inside udder และ outside udder ในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15992306","locator":"Abstract, opening","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The presence of foodborne pathogens in milk is due to direct contact with contaminated sources in the dairy farm environment and to excretion from the udder of an infected animal."}},{"id":"milk-meat-hygiene--milk-borne-pathogens--แหล่งปนเปื้อนเชื้อก่อโรค--v2","statement":"การสำรวจฟาร์มโคนมจริงพบว่าเชื้อก่อโรคส่วนใหญ่ (ร้อยละ 44.2) แยกได้จากตัวอย่างอุจจาระโดยตรง และจุดเสี่ยงหลักในฟาร์มคืออุจจาระโค น้ำในบ่อพักมูล วัสดุรองนอน มูลนก และลำไส้หนู ยืนยันว่าอุจจาระเป็นแหล่งปนเปื้อน E. coli, Salmonella และ Listeria","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15992268","locator":"Abstract, results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Most pathogens (44.2%) were isolated directly from fecal samples. Bovine fecal samples, lagoon water, bedding, bird droppings, and rat intestinal contents constituted areas of major concern on dairy farms."}}]},"milk-meat-hygiene--milk-borne-pathogens--เชื้อก่อโรคสำคัญในนม":{"claims":[{"id":"milk-meat-hygiene--milk-borne-pathogens--เชื้อก่อโรคสำคัญในนม--v1","statement":"Salmonella enterica serotype Dublin เป็นเชื้อที่ปรับตัวเข้ากับโค (cattle-adapted) และมักก่อการติดเชื้อในกระแสเลือดในคน โดยข้อมูลเฝ้าระวังในสหรัฐฯ ปี 2005 ถึง 2013 พบผู้ป่วยต้องนอนโรงพยาบาลร้อยละ 78 และเสียชีวิตร้อยละ 4.2 ยืนยันว่าความรุนแรงสูงกว่า Salmonella ทั่วไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28820133","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Salmonella enterica serotype Dublin is a cattle-adapted bacterium that typically causes bloodstream infections in humans ... a higher percentage of persons with Salmonella Dublin infection were hospitalized and died during 2005-2013 (78% ho"}},{"id":"milk-meat-hygiene--milk-borne-pathogens--เชื้อก่อโรคสำคัญในนม--v2","statement":"Staphylococcal food poisoning เกิดจาก staphylococcal enterotoxins ในอาหารที่ปนเปื้อน S. aureus จากการจัดการที่ไม่ถูกสุขลักษณะแล้วเก็บที่อุณหภูมิสูงเกินไป โดยเฉพาะผลิตภัณฑ์เนื้อแปรรูปและผลิตภัณฑ์นม อาการเกิดเร็ว มีคลื่นไส้และอาเจียนรุนแรง และมักหายเองได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22069659","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"SEs are a major cause of food poisoning, which typically occurs after ingestion of different foods, particularly processed meat and dairy products, contaminated with S. aureus by improper handling and subsequent storage at elevated temperat"}},{"id":"milk-meat-hygiene--milk-borne-pathogens--เชื้อก่อโรคสำคัญในนม--v3","statement":"Bacillus cereus ก่ออาหารเป็นพิษ 2 แบบคือ emetic syndrome และ diarrheal syndrome โดยมีเพียง cereulide ที่ระบุได้ว่าเป็น emetic toxin และ tripartite hemolysin BL ที่ระบุได้ว่าเป็น diarrheal toxin","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15771198","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Bacillus cereus causes two types of food poisoning, the emetic and diarrheal syndromes ... To date, only cereulide and the tripartite hemolysin BL have been identified specifically as emetic and diarrheal toxins, respectively."}},{"id":"milk-meat-hygiene--milk-borne-pathogens--เชื้อก่อโรคสำคัญในนม--v4","statement":"ช่วงระยะฟักตัว 3 ถึง 70 วันของ listeriosis มาจากการระบาดครั้งใหญ่ที่รายงานปี 1987 โดยการรวบรวมข้อมูลภายหลังพบว่า median ของ invasive listeriosis อยู่ที่ 8 วัน (พิสัย 1 ถึง 67 วัน) และกลุ่มที่สัมพันธ์กับการตั้งครรภ์มีระยะฟักตัวยาวที่สุด median 27.5 วัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23305174","locator":"Abstract, background and results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The first incubation periods were documented during a large listeriosis outbreak published in 1987 by Linnan and al. in the New England Journal of Medicine (range: 3 days to 70 days) ... The overall median incubation period of invasive list"}},{"id":"milk-meat-hygiene--milk-borne-pathogens--เชื้อก่อโรคสำคัญในนม--v5","statement":"Cronobacter spp. เป็นเชื้อก่อโรคอาหารอุบัติใหม่ที่ทำให้เกิด acute meningitis และ necrotizing enterocolitis ในทารกแรกเกิดและผู้มีภูมิคุ้มกันบกพร่อง มีความเชื่อมโยงกับ powdered infant formula ทั่วโลก และอัตราตายในทารกสูงถึงร้อยละ 80","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34196749","locator":"Abstract, background","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Cronobacter spp. are emerging infectious foodborne bacteria that can cause acute meningitis and necrotizing enterocolitis in neonates and immunocompromised individuals ... it has been linked to powdered infant formula worldwide ... The esti"}},{"id":"milk-meat-hygiene--milk-borne-pathogens--เชื้อก่อโรคสำคัญในนม--v6","statement":"Shiga toxin-producing E. coli เป็นสาเหตุสำคัญของ haemorrhagic colitis และ haemolytic uraemic syndrome มี infectious dose ต่ำมาก และการติดเชื้อในคนส่วนใหญ่มาจากอาหารที่มีต้นทางจากโค เช่น เนื้อบดที่ปรุงไม่สุกและน้ำนมโคที่ไม่ผ่านการพาสเจอไรส์ (แหล่งอ้างอิงไม่ได้ระบุตัวเลข 10 ถึง 100 เซลล์)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10880188","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Shiga toxin-producing Escherichia coli (STEC) are an important cause of haemorrhagic colitis and the diarrhoea-associated form of the haemolytic uraemic syndrome ... Most human infections caused by STEC have been acquired by the consumption"}}]},"milk-meat-hygiene--milk-borne-pathogens--เชื้ออื่น-outbreaks-และการควบคุม":{"claims":[{"id":"milk-meat-hygiene--milk-borne-pathogens--เชื้ออื่น-outbreaks-และการควบคุม--v1","statement":"การพาสเจอไรส์อาจไม่ทำลายเชื้อก่อโรคในนมได้ทั้งหมด และการพาสเจอไรส์ที่ไม่สมบูรณ์ก็ทำลายเชื้อไม่หมด อีกทั้ง Listeria monocytogenes ยังอยู่รอดและเจริญได้ในสิ่งแวดล้อมหลังการพาสเจอไรส์ ทำให้เกิดการปนเปื้อนซ้ำในผลิตภัณฑ์นม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15992306","locator":"Abstract, points 5 and 6","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"(5) pasteurization may not destroy all foodborne pathogens in milk, and (6) inadequate or faulty pasteurization will not destroy all foodborne pathogens. Furthermore, pathogens such as Listeria monocytogenes can survive and thrive in post-p"}},{"id":"milk-meat-hygiene--milk-borne-pathogens--เชื้ออื่น-outbreaks-และการควบคุม--v2","statement":"น้ำนมดิบและผลิตภัณฑ์จากน้ำนมดิบของโค แพะ และแกะ ยังคงเป็นแหล่งของการติดเชื้อจาก Listeria monocytogenes, Campylobacter jejuni, Salmonella spp., Brucella spp. และ E. coli O157 และนมพาสเจอไรส์ให้ประโยชน์ทางสุขภาพเทียบเท่านมดิบโดยไม่มีความเสี่ยงติดเชื้อเพิ่ม จึงเป็นเหตุผลของมาตรการให้ความรู้เรื่องความเสี่ยงนมดิบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24344105","locator":"Abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Raw milk and milk products from cows, goats, and sheep continue to be a source of bacterial infections attributable to a number of virulent pathogens, including Listeria monocytogenes, Campylobacter jejuni, Salmonella species, Brucella spec"}}]}},"milk-meat-hygiene--milk-industry-std":{"milk-meat-hygiene--milk-industry-std--gmp-haccp-detail-processing-plant-standard":{"claims":[{"id":"milk-meat-hygiene--milk-industry-std--gmp-haccp-detail-processing-plant-standard--v1","statement":"การจัดทำแผน HACCP ในโรงงานแปรรูปนมใช้ **หลักการ 7 ข้อของ HACCP (seven principles)** เป็นกรอบวิธีการ ร่วมกับการมี pre-requisite programs อยู่ก่อน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16786735","locator":"Vol 56(1):60-8, abstract (Methodology)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The used methodology was based in the application of the seven principles of the HACCP, the information from the plant about the compliment of the pre-requisite programs (70-80%), the experience of the HACCP team"}},{"id":"milk-meat-hygiene--milk-industry-std--gmp-haccp-detail-processing-plant-standard--v2","statement":"ในสายการผลิตผลิตภัณฑ์นม ขั้นตอนที่ถูกกำหนดเป็น **CCP** ได้แก่ การรับน้ำนมดิบ (raw milk receipt) · **pasteurization** · การบรรจุ (packaging) · การเก็บรักษา (storage) เพราะเป็นจุดที่เสี่ยงต่อการปนเปื้อนมากที่สุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38646882","locator":"Vol 91(1):125-135, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In yogurt production, raw milk receipt, pasteurization, packaging, and storage are the steps most susceptible to contamination and were considered critical control points."}}]},"milk-meat-hygiene--milk-industry-std--standards-hierarchy-4-layers-from-top-to-bottom":{"claims":[{"id":"milk-meat-hygiene--milk-industry-std--standards-hierarchy-4-layers-from-top-to-bottom--v1","statement":"**Prerequisite Programs (PRPs)** ซึ่งรวม GMP และ GHP เป็น **ฐานรองรับ (foundation) ของ HACCP** — ต้องมีอยู่ก่อนจึงจะป้องกันการระบาดของโรคจากอาหารได้ ตรงกับที่ GMP อยู่ชั้นล่างสุดของลำดับมาตรฐาน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34574279","locator":"Vol 10(9):2169, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Our study focuses on the importance of Food Safety Management System (FSMS), Critical Control Points Hazard Analysis (HACCP) and the Prerequisite Programs (PRPs) as the foundation of HACCP, in preventing foodborne outbreaks."}},{"id":"milk-meat-hygiene--milk-industry-std--standards-hierarchy-4-layers-from-top-to-bottom--v2","statement":"**ISO 22000** คือมาตรฐานระบบการจัดการความปลอดภัยอาหาร (Food Safety Management System, FSMS) โดยฉบับที่ใช้อ้างอิงในปัจจุบันคือ **ISO 22000:2018**","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34574279","locator":"Vol 10(9):2169, abstract (final sentence)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Implementation of food safety management systems (ISO 22000:2018) along with incorporation of management tools such as HAZOP, FMEA, Ishikawa and Pareto have proved to be proactive in the maintenance of a positive food safety culture"}}]},"milk-meat-hygiene--milk-industry-std--standard-of-milk-collection-center-มาตรฐาน-mcc-ของไทย":{"claims":[{"id":"milk-meat-hygiene--milk-industry-std--standard-of-milk-collection-center-มาตรฐาน-mcc-ของไทย--v1","statement":"มาตรฐานสินค้าเกษตรของไทยเรื่อง **การปฏิบัติที่ดีสำหรับศูนย์รวบรวมน้ำนมดิบ** คือ **มกษ. 6401-2558** ออกโดย **มกอช. (ACFS)** ภายใต้ พ.ร.บ. มาตรฐานสินค้าเกษตร พ.ศ. 2551 ส่วน **มกษ. 6401(G)-2560** เป็นเอกสาร *แนวปฏิบัติในการใช้* มาตรฐานดังกล่าว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--national-bureau-of-ag-2015","locator":"หมายเลขมาตรฐาน มกษ. 6401-2558 — หน้าสินค้า 'ศูนย์รวบรวมน้ำนมดิบ' บนระบบสารสนเทศสินค้าเกษตรตามมาตรฐานบังคับ ของ มกอช. ไม่ระบุเลขข้อย่อย เนื่องจากยังไม่ได้ตรวจสอบตัวบทมาตรฐานฉบับเต็ม","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":""}}]},"milk-meat-hygiene--milk-industry-std--ภาพรวมระบบมาตรฐาน":{"claims":[{"id":"milk-meat-hygiene--milk-industry-std--ภาพรวมระบบมาตรฐาน--v1","statement":"Codex ระบุว่าโปรแกรมพื้นฐาน (prerequisite programmes) ที่รวม Good Hygiene Practices ต้องเป็นรากฐานของระบบ HACCP ที่มีประสิทธิภาพ ซึ่งยืนยันลำดับที่สไลด์ระบุว่า HACCP พัฒนาต่อยอดจาก GMP","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2020","locator":"HACCP Annex, Introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Prerequisite programmes that include GHPs should provide the foundation for an effective HACCP system."}}]},"milk-meat-hygiene--milk-industry-std--gmp-ศูนย์รวบรวมน้ำนมดิบ-มกษ-6401-g-2560":{"claims":[{"id":"milk-meat-hygiene--milk-industry-std--gmp-ศูนย์รวบรวมน้ำนมดิบ-มกษ-6401-g-2560--v1","statement":"มาตรฐาน มกษ. 6401 การปฏิบัติที่ดีสำหรับศูนย์รวบรวมน้ำนมดิบ กำหนดให้ลดอุณหภูมิน้ำนมดิบให้ไม่เกิน 4 องศาเซลเซียสทันที หรือกรณีใช้ถังเก็บที่มีระบบทำความเย็น ให้ลดอุณหภูมิไม่เกิน 4 องศาเซลเซียสภายใน 2 ชั่วโมง ตรงกับที่สไลด์ระบุ และครอบคลุมการรับน้ำนม การลดอุณหภูมิ การเก็บรักษา การขนส่ง และการบันทึกข้อมูล","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--department-of-livesto-2017","locator":"หมวดการลดอุณหภูมิน้ำนมดิบ","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ลดอุณหภูมิน้ำนมดิบให้มีอุณหภูมิไม่เกิน 4 องศาเซลเซียสทันที หรือกรณีใช้ถังเก็บน้ำนมดิบที่มีระบบทำความเย็น ต้องลดอุณหภูมิให้ไม่เกิน 4 องศาเซลเซียสภายใน 2 ชั่วโมง"}}]},"milk-meat-hygiene--milk-industry-std--gmp-420-โรงงานแปรรูปนม":{"claims":[{"id":"milk-meat-hygiene--milk-industry-std--gmp-420-โรงงานแปรรูปนม--v1","statement":"GMP 420 คือ ประกาศกระทรวงสาธารณสุข (ฉบับที่ 420) พ.ศ. 2563 เรื่อง วิธีการผลิต เครื่องมือเครื่องใช้ในการผลิต และการเก็บรักษาอาหาร ซึ่งออกตามความในพระราชบัญญัติอาหาร พ.ศ. 2522 ตรงตามที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2563","locator":"ชื่อประกาศและบทอาศัยอำนาจ","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ประกาศกระทรวงสาธารณสุข (ฉบับที่ 420) พ.ศ. 2563 ออกตามความในพระราชบัญญัติอาหาร พ.ศ. 2522 เรื่อง วิธีการผลิต เครื่องมือเครื่องใช้ในการผลิต และการเก็บรักษาอาหาร"}},{"id":"milk-meat-hygiene--milk-industry-std--gmp-420-โรงงานแปรรูปนม--v2","statement":"กฎหมายไทยนิยามพาสเจอไรซ์น้ำนมโคว่าเป็นการฆ่าเชื้อด้วยความร้อนเพื่อลดจุลินทรีย์ให้อยู่ระดับปลอดภัยและยับยั้งการทำงานของเอนไซม์ฟอสฟาเทส โดยใช้อุณหภูมิไม่ต่ำกว่า 63 องศาเซลเซียส ไม่น้อยกว่า 30 นาที หรือไม่ต่ำกว่า 72 องศาเซลเซียส ไม่น้อยกว่า 15 วินาที แล้วทำให้เย็นลงทันทีที่ 5 องศาเซลเซียสหรือต่ำกว่า ตรงกับตัวเลข LTLT/HTST และการทำให้เย็นทันทีในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2556","locator":"ข้อ 6 (1) (1.1) และ (1.2)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"พาสเจอร์ไรส์ หมายความว่า กรรมวิธีฆ่าเชื้อด้วยความร้อนเพื่อลดปริมาณจุลินทรีย์ให้อยู่ในระดับที่ปลอดภัยต่อผู้บริโภคและยับยั้งการทำงานของเอนไซม์ฟอสฟาเทส ... (1.1) อุณหภูมิไม่ต่ำกว่า 63 องศาเซลเซียส และคงอยู่ที่อุณหภูมินี้ไม่น้อยกว่า 30 นาที แล้"}},{"id":"milk-meat-hygiene--milk-industry-std--gmp-420-โรงงานแปรรูปนม--v3","statement":"การควบคุมอุณหภูมิผลิตภัณฑ์หลังพาสเจอไรซ์ไม่เกิน 8 องศาเซลเซียส เป็นข้อกำหนดตามกฎหมายไทย โดยต้องเก็บที่อุณหภูมิไม่เกิน 8 องศาเซลเซียสตลอดระยะเวลาหลังบรรจุจนถึงผู้บริโภค","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2556","locator":"ข้อ 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"น้ำนมโคสดหรือน้ำนมโคพาสเจอร์ไรส์ ต้องเก็บรักษาไว้ที่อุณหภูมิไม่เกิน 8 องศาเซลเซียส ตลอดระยะเวลาหลังบรรจุจนถึงผู้บริโภค"}},{"id":"milk-meat-hygiene--milk-industry-std--gmp-420-โรงงานแปรรูปนม--v4","statement":"การใช้ผล phosphatase test เป็นตัวยืนยันประสิทธิภาพพาสเจอไรซ์ที่ 72 องศาเซลเซียส 15 วินาที หรือ 63 องศาเซลเซียส 30 นาที เป็นเกณฑ์สากล โดยผล alkaline phosphatase ต้องเป็นลบทันทีหลังผ่านความร้อน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33968255","locator":"Abstract, opening sentence; 19(4):e06576","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pasteurisation of raw milk, colostrum, dairy or colostrum-based products must be achieved using at least 72 degrees C for 15 s, at least 63 degrees C for 30 min or any equivalent combination, such that the alkaline phosphatase (ALP) test im"}},{"id":"milk-meat-hygiene--milk-industry-std--gmp-420-โรงงานแปรรูปนม--v5","statement":"การใช้ peroxidase test กับนมที่ผ่านความร้อนสูงระดับ 80 องศาเซลเซียสมีพื้นฐานจริง เพราะ lactoperoxidase ถูกทำลายหมดที่ 80 องศาเซลเซียส นาน 15 วินาที จึงใช้แยกนมที่ผ่านความร้อนสูงออกจากนมดิบได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24966440","locator":"Abstract; 51(7):1416-1420","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Heat treatment of milk at 80 degrees C (15 s) completely inactivates both milk enzymes."}},{"id":"milk-meat-hygiene--milk-industry-std--gmp-420-โรงงานแปรรูปนม--v6","statement":"โทษปรับไม่เกินหนึ่งหมื่นบาทตามมาตรา 49 แห่งพระราชบัญญัติอาหาร พ.ศ. 2522 ใช้กับผู้ฝ่าฝืนประกาศที่ออกตามมาตรา 6 (7) ซึ่งเป็นฐานอำนาจของประกาศเรื่องวิธีการผลิตและการเก็บรักษาอาหาร","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2522","locator":"มาตรา 49","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ผู้ใดฝ่าฝืนประกาศซึ่งออกตามมาตรา 6 (7) ต้องระวางโทษปรับไม่เกินหนึ่งหมื่นบาท"}}]},"milk-meat-hygiene--milk-industry-std--haccp":{"claims":[{"id":"milk-meat-hygiene--milk-industry-std--haccp--v1","statement":"HACCP ตามมาตรฐาน Codex ประกอบด้วย 7 หลักการ และการนำไปใช้เขียนเป็นลำดับ 12 ขั้นตอน คือ 5 ขั้นตอนเตรียมการ (ตั้งทีม อธิบายผลิตภัณฑ์ ระบุการใช้ เขียน flow diagram และยืนยันหน้างาน) แล้วต่อด้วย 7 หลักการ ตรงกับที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2020","locator":"Annex, section on Application, Steps 1 to 12","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The annex sets out the seven principles of HACCP and an Application section listing the steps for creating a HACCP plan, beginning with Step 1 assemble HACCP team and ending with step 12 establish documentation and record keeping, the first"}},{"id":"milk-meat-hygiene--milk-industry-std--haccp--v2","statement":"ข้อสังเกตท้ายหน้านี้ถูกต้อง นิยาม UHT ตามกฎหมายไทยคือกรรมวิธีฆ่าเชื้อด้วยความร้อนที่อุณหภูมิไม่ต่ำกว่า 133 องศาเซลเซียส ไม่น้อยกว่า 1 วินาที แล้วบรรจุในภาชนะและในสภาวะที่ปราศจากเชื้อ ดังนั้นค่ากฎหมายคือขั้นต่ำ 1 วินาที ส่วน critical limit ที่โรงงานตั้งไว้ 4 วินาทีเป็นการตั้งเข้มกว่ากฎหมายได้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2556","locator":"ข้อ 6 (3)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ยู เอช ที หมายความว่า กรรมวิธีฆ่าเชื้อด้วยความร้อนที่อุณหภูมิไม่ต่ำกว่า 133 องศาเซลเซียส ไม่น้อยกว่า 1 วินาที แล้วบรรจุในภาชนะและในสภาวะที่ปราศจากเชื้อ"}}]}},"milk-meat-hygiene--milk-processing":{"milk-meat-hygiene--milk-processing--heat-treatment-time-temp-product-specific-lines":{"claims":[{"id":"milk-meat-hygiene--milk-processing--heat-treatment-time-temp-product-specific-lines--v1","statement":"Pasteurization ของน้ำนมมี 2 รูปแบบหลัก — **LTLT (low temperature long time) = 63°C นาน 30 นาที** และ **HTST (high temperature short time) = 72°C นาน 15 วินาที**","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21381400","locator":"Issue 128:81-4, abstract (plant pasteurization experiment)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"We conducted plant pasteurization experiment at four pasteurization conditions (high temperature, short time (HTST); 82, 77, 72 degrees C for 15 seconds and low temperature, long time (LTLT); 63 degrees C for 30 minutes)"}},{"id":"milk-meat-hygiene--milk-processing--heat-treatment-time-temp-product-specific-lines--v2","statement":"ในการทดสอบระดับโรงงาน ทั้ง HTST (72, 77, 82°C/15 วินาที) และ LTLT (63°C/30 นาที) ไม่พบโคโลนีของ **Mycobacterium avium subsp. paratuberculosis (MAP)** ในน้ำนมที่ผ่านความร้อน ทั้งสายพันธุ์ ATCC19698 และ OKY-20","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21381400","locator":"Issue 128:81-4, abstract (conclusion)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In conclusion, there appeared no colony of the two MAP strains formed from the milk pasteurized at the four pasteurization conditions examined."}},{"id":"milk-meat-hygiene--milk-processing--heat-treatment-time-temp-product-specific-lines--v3","statement":"**UHT ที่ 135°C นาน ~5 วินาที กำจัดสปอร์ได้หมด** ขณะที่ pasteurization ทั่วไป (75-95°C/15 วินาที) ทำลายเชื้อรูป vegetative ได้แต่ **ไม่กำจัดสปอร์** — นี่คือเหตุผลที่ UHT เก็บที่อุณหภูมิห้องได้ แต่นมพาสเจอร์ไรส์ต้องแช่เย็น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41829232","locator":"Vol 15(5):959, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This study systematically compared the effects of instantaneous ultra-high-temperature treatment (INF, 145-155 °C/0.09 s) with that of conventional pasteurization (75-95 °C/15 s) as well as ultra-high-temperature treatment (UHT, 135 °C/5 s)"}},{"id":"milk-meat-hygiene--milk-processing--heat-treatment-time-temp-product-specific-lines--v4","statement":"**Alkaline phosphatase (ALP)** เป็นเอนไซม์ธรรมชาติในน้ำนมที่ใช้ยืนยันว่า pasteurization เพียงพอ โดยเกณฑ์สาธารณสุขของสหรัฐฯ และยุโรปสำหรับเครื่องดื่มนมพาสเจอร์ไรส์คือ **ALP ไม่เกิน 350 mU/ลิตร**","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21740717","locator":"Vol 74(7):1144-54, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Alkaline phosphatase is a ubiquitous milk enzyme that historically has been used to verify adequate pasteurization of milk for public health purposes... The U.S. and European public health limit for alkaline phosphatase in pasteurized drink"}},{"id":"milk-meat-hygiene--milk-processing--heat-treatment-time-temp-product-specific-lines--v5","statement":"ความร้อนสูงกระทบโปรตีนในนม — หลัง **UHT** พบว่า lactoferrin และ IgG **เสียสภาพหมด (complete denaturation)** และค่า **furosine** (ดัชนีปฏิกิริยา glycation) สูงราว **67 mg/100 g protein** เทียบกับราว **15 mg/100 g protein** ที่ 95°C/15 วินาที","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41829232","locator":"Vol 15(5):959, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The retention of lactoferrin and immunoglobulin G was about 30% and 12% after INF treatment, respectively, which were higher than that of 13% and 8% in the 85 °C/15 s group, and complete denaturation in the 95 °C/15 s and UHT groups... furo"}}]},"milk-meat-hygiene--milk-processing--standard-processing-workflow-8-unit-operations":{"claims":[{"id":"milk-meat-hygiene--milk-processing--standard-processing-workflow-8-unit-operations--v1","statement":"Homogenization คือ mechanical treatment หลักที่ใช้ในอุตสาหกรรมนม ทำให้ milk fat globule มีขนาดเล็กลง และเปลี่ยนสถาปัตยกรรม (องค์ประกอบและการจัดเรียง) ของ fat/water interface","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26568788","locator":"Vol 95(6):863-893, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The main mechanical treatment used in the dairy industry, homogenization, decreases the size of milk fat globules, changes the architecture (composition and organization) of the fat/water interface and affects the interactions between lipid"}},{"id":"milk-meat-hygiene--milk-processing--standard-processing-workflow-8-unit-operations--v2","statement":"Heat treatment แบบ HTST pasteurization และ Cleaning In Place (CIP) เป็น unit operation มาตรฐานของโรงงานแปรรูปน้ำนมพร้อมดื่ม โดยการปนเปื้อนหลัง pasteurization (post-pasteurization contamination) ด้วย gram-negative bacteria ทำให้คุณภาพและ shelf-life ของนมเสียไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32475674","locator":"Vol 103(8):7569-7584, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Postpasteurization contamination (PPC) with gram-negative bacteria adversely affects the quality and shelf-life of milk through the development of flavor, odor, texture, and visual defects."}}]},"milk-meat-hygiene--milk-processing--dairy-processing-diagram":{"claims":[{"id":"milk-meat-hygiene--milk-processing--dairy-processing-diagram--v1","statement":"Evaporation ร่วมกับ spray drying เป็นขั้นตอนการผลิตจริงของผลิตภัณฑ์นมชนิดเข้มข้น/ผง โดยผลิตภัณฑ์อย่าง milk protein concentrate ผลิตจาก skim milk ผ่านลำดับขั้นตอน pasteurization ตามด้วย membrane filtration, evaporation และ spray drying","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33856251","locator":"Vol 62(25):6973-6989, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk protein concentrates (MPCs), which are produced from skim milk following a series of manufacturing steps including pasteurization, membrane filtration, evaporation and spray drying, represent a relatively new category of dairy ingredie"}},{"id":"milk-meat-hygiene--milk-processing--dairy-processing-diagram--v2","statement":"หลักการของ diagram ที่ว่า unit operations ต่าง ๆ แปลงน้ำนมไปเป็นผลิตภัณฑ์นมหลากชนิด ตรงกับนิยามสากล ซึ่งกำหนดว่า milk product คือผลิตภัณฑ์ที่ได้จากการแปรรูปน้ำนมด้วยกระบวนการใดก็ตาม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-fao-who-codex-alimenta-1999","locator":"Section 2.2 (Definitions, Milk product)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk product is a product obtained by any processing of milk, which may contain food additives, and other ingredients functionally necessary for the processing."}}]},"milk-meat-hygiene--milk-processing--heat-treatment-และ-heat-exchangers":{"claims":[{"id":"milk-meat-hygiene--milk-processing--heat-treatment-และ-heat-exchangers--v1","statement":"ช่วงอุณหภูมิ UHT ที่สไลด์ระบุ 135 ถึง 140 องศาเซลเซียส 1 ถึง 3 วินาที สอดคล้องกับเกณฑ์กฎหมายไทยที่กำหนด UHT ไม่ต่ำกว่า 133 องศาเซลเซียส ไม่น้อยกว่า 1 วินาที ส่วน sterilization เป็นการฆ่าเชื้อน้ำนมที่บรรจุในภาชนะปิดสนิทแล้วด้วยความร้อนไม่ต่ำกว่า 100 องศาเซลเซียส ตามเวลาที่เหมาะสม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2556","locator":"ข้อ 6 (2) และ (3)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"สเตอริไลส์ หมายความว่า กรรมวิธีฆ่าเชื้อน้ำนมโคที่บรรจุในภาชนะที่ปิดสนิทด้วยความร้อนที่อุณหภูมิไม่ต่ำกว่า 100 องศาเซลเซียส โดยใช้เวลาที่เหมาะสม ... ยู เอช ที หมายความว่า กรรมวิธีฆ่าเชื้อด้วยความร้อนที่อุณหภูมิไม่ต่ำกว่า 133 องศาเซลเซียส ไม่น"}},{"id":"milk-meat-hygiene--milk-processing--heat-treatment-และ-heat-exchangers--v2","statement":"ช่วงอุณหภูมิและเวลาในตารางแปรรูปเป็นค่าที่ใช้จริงในงานทดลอง โดยมีการเปรียบเทียบ ultrapasteurization ที่ 138 องศาเซลเซียส 2 วินาที กับ pasteurization ที่ 74 องศาเซลเซียส 15 วินาที ซึ่งอยู่ในช่วงเดียวกับที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19610345","locator":"Abstract, Methods; 72(6):1301-1305","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Samples were submitted to ultrapasteurization (138 degrees C for 2 s), superpasteurization (96 degrees C for 13 s), and pasteurization (74 degrees C for 15 s)"}}]},"milk-meat-hygiene--milk-processing--ผลิตภัณฑ์นม":{"claims":[{"id":"milk-meat-hygiene--milk-processing--ผลิตภัณฑ์นม--v1","statement":"โยเกิร์ตต้องใช้ Streptococcus thermophilus ร่วมกับ Lactobacillus delbrueckii ssp. bulgaricus จริง เพราะการเลี้ยงร่วมกันให้อัตราการสร้างกรดสูงกว่าและคุณภาพดีกว่าการใช้เชื้อชนิดเดียว และการเลือกอัตราส่วนเชื้อที่เหมาะสมมีผลต่อคุณภาพและความคงตัวระหว่างเก็บ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37641256","locator":"Abstract, Conclusion; 107(1):123-140","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Our study emphasized the importance of selecting an appropriate bacterial consortium at the optimal inoculum ratio to achieve favorable fermentation performance and enhanced postacidification stability during storage."}},{"id":"milk-meat-hygiene--milk-processing--ผลิตภัณฑ์นม--v2","statement":"การผลิตนมสเตอริไลซ์ต้องบรรจุในภาชนะที่ปิดสนิทก่อนแล้วจึงให้ความร้อน ตรงกับที่สไลด์ระบุ โดยกฎหมายไทยนิยามว่าเป็นการฆ่าเชื้อน้ำนมโคที่บรรจุในภาชนะที่ปิดสนิทด้วยความร้อนที่อุณหภูมิไม่ต่ำกว่า 100 องศาเซลเซียส","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2556","locator":"ข้อ 6 (2)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"สเตอริไลส์ หมายความว่า กรรมวิธีฆ่าเชื้อน้ำนมโคที่บรรจุในภาชนะที่ปิดสนิทด้วยความร้อนที่อุณหภูมิไม่ต่ำกว่า 100 องศาเซลเซียส"}},{"id":"milk-meat-hygiene--milk-processing--ผลิตภัณฑ์นม--v3","statement":"เวย์โปรตีนเป็นโปรตีนคุณภาพสูงที่มีกรดอะมิโนจำเป็นครบและเกินค่าอ้างอิงมาตรฐาน FAO/WHO/UNU และมีคุณค่าทางโภชนาการเหนือกว่าโซเดียมเคซีเนตเมื่อประเมินด้วยองค์ประกอบกรดอะมิโน chemical score ดัชนีกรดอะมิโนจำเป็น และค่า biological value ที่ทำนายได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16421963","locator":"Abstract, Results; 7(2):90-98","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"WPC 80, sodium caseinate and their hydrolysates were high-quality proteins and had a surplus of essential amino acids compared with the FAO/WHO/UNU (1985) reference standard. The nutritive value of WPC 80 and its hydrolysates was superior t"}}]},"milk-meat-hygiene--milk-processing--ขั้นตอนหลักของ-dairy-processing":{"claims":[{"id":"milk-meat-hygiene--milk-processing--ขั้นตอนหลักของ-dairy-processing--v1","statement":"เครื่องแยกครีมแบบ hermetic (ปิดสนิท) สร้างแรงดันสูงได้ จึงแยกครีมที่มีไขมันเกิน 72 เปอร์เซ็นต์ได้ ขณะที่เครื่องแบบ paring-disc ทำไม่ได้ ยืนยันว่า close separator ให้ครีมที่ milk fat เข้มข้นที่สุดตามที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-tetra-pak-processing-s-1995","locator":"บท Centrifugal Separators and Milk Standardization หัวข้อ hermetic separator ของฉบับออนไลน์ dairyprocessinghandbook.tetrapak.com","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"High pressures can be created in the hermetic separator, which makes it possible to separate cream with a fat content exceeding 72%."}},{"id":"milk-meat-hygiene--milk-processing--ขั้นตอนหลักของ-dairy-processing--v2","statement":"Standardization คือการปรับปริมาณไขมันของน้ำนมหรือผลิตภัณฑ์นม โดยการเติมครีมหรือ skim milk ตามความเหมาะสมเพื่อให้ได้ปริมาณไขมันตามที่กำหนด ตรงกับนิยามในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-tetra-pak-processing-s-1995","locator":"บท Centrifugal Separators and Milk Standardization หัวข้อ standardization ของฉบับออนไลน์ dairyprocessinghandbook.tetrapak.com","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Standardization involves adjustment of the fat content of milk, or a milk product, by addition of cream or skim milk as appropriate to obtain a given fat content."}}]},"milk-meat-hygiene--milk-processing--homogenization":{"claims":[{"id":"milk-meat-hygiene--milk-processing--homogenization--v1","statement":"การโฮโมจีไนซ์ทำให้ไขมันนมกระจายตัวละเอียดขึ้นและเพิ่ม colloidal dispersion ของ fat globule (วัดจาก zeta potential ที่สูงขึ้น) ผลคือน้ำนมมีค่าความสว่าง L* สูงขึ้นเพราะอนุภาคไขมันที่เล็กลงกระเจิงแสงมากขึ้น ซึ่งเป็นกลไกเดียวกับที่ทำให้นมเป็นเนื้อเดียวกันและไม่แยกชั้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38672914","locator":"Abstract, results on colloidal dispersion and colour","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"UHT, RTR, and homogenization increased the colloidal dispersion of globules, as indicated by increased zeta potential ... homogenization led to higher L* values, indicating increased whiteness due to finer dispersion of the fat and casein m"}},{"id":"milk-meat-hygiene--milk-processing--homogenization--v2","statement":"การโฮโมจีไนซ์ทำลาย milk fat globule membrane และเปลี่ยนการเกิด lipolysis ของไขมันนม จึงเป็นเหตุผลเชิงกลไกว่าทำไมการโฮโมจีไนซ์น้ำนมที่ยังมีเอนไซม์ lipase ทำงานอยู่จึงเร่งการเกิดกลิ่นหืน และทำไมจึงนิยมโฮโมจีไนซ์หลังผ่านความร้อนที่ยับยั้งเอนไซม์แล้ว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40436574","locator":"Abstract, conclusion on homogenization","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Homogenization significantly reduced DHA bioaccessibility, possibly by damaging the milk fat globule membranes and affecting lipolysis."}}]},"milk-meat-hygiene--milk-processing--สวนจิตรลดา-และ-อ-ส-ค":{"claims":[{"id":"milk-meat-hygiene--milk-processing--สวนจิตรลดา-และ-อ-ส-ค--v1","statement":"อ.ส.ค. ระบุตัวเองว่าส่งเสริมอาชีพการเลี้ยงโคนมและผลิตนมไทย-เดนมาร์คมาตั้งแต่ปี 2504 โดยชูจุดยืนว่าผลิตจากนมโคสดแท้ 100% ไม่ผสมนมผง ตรงกับที่เอกสารสรุปบันทึกว่าผลิตภัณฑ์ อ.ส.ค. มาจากนมโคสด 100%","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2026","locator":"หน้าแรกของเว็บไซต์ (คำบรรยายองค์กร)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ส่งเสริมอาชีพการเลี้ยงโคนม และผลิตนมไทย-เดนมาร์ค มาตั้งแต่ 2504 เพื่อให้คนไทยได้ดื่มนมโคสดแท้ 100% ไม่ผสมนมผง"}},{"id":"milk-meat-hygiene--milk-processing--สวนจิตรลดา-และ-อ-ส-ค--v2","statement":"วัตถุประสงค์การจัดตั้ง อ.ส.ค. ครอบคลุมทั้งการส่งเสริมการเลี้ยงโคนมและสัตว์อื่นที่ให้น้ำนม และการฝึกอบรมบุคคลให้มีความรู้ความชำนาญในการเลี้ยงโคนมและการผลิตน้ำนม ซึ่งตรงกับพันธกิจข้อ ส่งเสริมการเลี้ยงโคนมเป็นอาชีพ และ สร้างแหล่งความรู้ด้านกิจการโคนม ที่เอกสารสรุปไว้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2026","locator":"หน้า วัตถุประสงค์การจัดตั้ง และภารกิจองค์กร","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ส่งเสริมการเลี้ยงโคนมและสัตว์อื่นที่ให้น้ำนม และฝึกอบรมบุคคลให้มีความรู้ความชำนาญในการเลี้ยงโคนมและการผลิตน้ำนมและเนื้อ"}}]}},"milk-meat-hygiene--milk-cleaning":{"milk-meat-hygiene--milk-cleaning--cleaning-agents-disinfectants-detail":{"claims":[{"id":"milk-meat-hygiene--milk-cleaning--cleaning-agents-disinfectants-detail--v1","statement":"ชุด **CIP มาตรฐาน** ของโรงงานนมคือ water rinse → **sodium hydroxide (โซดาไฟ) 1% ที่ 65°C นาน 10 นาที** → water rinse → **nitric acid (กรดไนตริก) 1.0% ที่ 65°C นาน 10 นาที** → water rinse","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16216371","locator":"Vol 106(3):254-62, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"a standard clean-in-place (CIP) regime (water rinse, 1% sodium hydroxide at 65 degrees C for 10 min, water rinse, 1.0% nitric acid at 65 degrees C for 10 min, water rinse)"}},{"id":"milk-meat-hygiene--milk-cleaning--cleaning-agents-disinfectants-detail--v2","statement":"เมื่อแบคทีเรียเกาะติดผิว **stainless steel** เป็น biofilm แล้ว ชุด CIP มาตรฐาน (caustic + acid) **ไม่สามารถกำจัดออกได้อย่างสม่ำเสมอ (not reproducibly)**","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16216371","locator":"Vol 106(3):254-62, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Once bacteria attached to surfaces, a standard clean-in-place (CIP) regime (water rinse, 1% sodium hydroxide at 65 degrees C for 10 min, water rinse, 1.0% nitric acid at 65 degrees C for 10 min, water rinse) did not reproducibly ensure thei"}},{"id":"milk-meat-hygiene--milk-cleaning--cleaning-agents-disinfectants-detail--v3","statement":"ในการศึกษาระดับห้องปฏิบัติการ **การเพิ่มขั้นตอน sanitizer เข้าไปใน CIP ไม่ได้ช่วยให้กำจัด biofilm ดีขึ้น** ขณะที่การใช้ caustic additive ร่วมกับ acid blend ลดจำนวนเซลล์ที่เก็บได้จากผิว stainless steel ลง **3.8 log**","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16216371","locator":"Vol 106(3):254-62, abstract (results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The combination of NaOH plus Eliminator and Nitroplus achieved a 3.8 log reduction in the number of cells recovered from the stainless steel surface. The incorporation of a sanitizer step into the CIP did not appear to enhance biofilm remov"}}]},"milk-meat-hygiene--milk-cleaning--ส่วนที่-1-ข้อกำหนดสำหรับสถานที่ผลิตอาหารทุกประเภท":{"claims":[{"id":"milk-meat-hygiene--milk-cleaning--ส่วนที่-1-ข้อกำหนดสำหรับสถานที่ผลิตอาหารทุกประเภท--v1","statement":"แบคทีเรียส่วนใหญ่ที่แยกได้บ่อยในห่วงโซ่น้ำนม **สร้าง biofilm ได้** เช่น **Staphylococcus aureus** (และ staphylococci อื่น) · **Bacillus spp.** · **Listeria monocytogenes** · **Pseudomonas spp.** ซึ่งเข้าไปตั้งรกรากบนเครื่องรีดนมและเครื่องมือแปรรูปนม และ **ทนต่อสารฆ่าเชื้อ (biocides) ได้มากกว่ารูป planktonic**","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39603496","locator":"Vol 108(8):8157-8175, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Biofilm formation allows microorganisms including bacteria to persist on abiotic or biotic surfaces, to resist treatments with biocides (disinfectants and antibiotics)... most of the bacterial species isolated frequently in the dairy chain"}}]},"milk-meat-hygiene--milk-cleaning--9-ข้อกำหนดขั้นพื้นฐาน":{"claims":[{"id":"milk-meat-hygiene--milk-cleaning--9-ข้อกำหนดขั้นพื้นฐาน--v1","statement":"ข้อกำหนดพื้นฐานด้านสุขลักษณะส่วนใหญ่ที่ระบุไว้ ได้แก่ สถานประกอบการและสิ่งอำนวยความสะดวก, การควบคุมการปฏิบัติงาน, การบำรุงรักษาและการสุขาภิบาล, สุขลักษณะส่วนบุคคล, การขนส่ง และการฝึกอบรม ตรงกับหัวข้อหลักของหลักการทั่วไปด้านสุขลักษณะอาหารของ Codex","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2020","locator":"Chapter on Good Hygiene Practices, top-level section headings (primary production, establishment design of facilities and equipment, training and competence, establishment maintenance cleaning disinfection and pest control, personal hygiene, control of operation, product information and consumer awareness, transportation). Numbering changed in the 2020 revision and is not quoted here because I did not re-verify it.","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":""}}]},"milk-meat-hygiene--milk-cleaning--คุณสมบัติของ-disinfectant-ในอุดมคติ":{"claims":[{"id":"milk-meat-hygiene--milk-cleaning--คุณสมบัติของ-disinfectant-ในอุดมคติ--v1","statement":"สารออกฤทธิ์ (biocides) ที่ใช้เป็น antiseptic และ disinfectant ส่วนใหญ่มีฤทธิ์ต้านจุลชีพแบบกว้าง (broad-spectrum antimicrobial activity) ซึ่งเป็นคุณสมบัติข้อแรกที่สไลด์กำหนดไว้สำหรับ disinfectant ในอุดมคติ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9880479","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Most of these active agents demonstrate broad-spectrum antimicrobial activity; however, little is known about the mode of action of these agents in comparison to antibiotics."}}]},"milk-meat-hygiene--milk-cleaning--กลไกการทำลายเชื้อของ-disinfectant-ในการผลิตนม":{"claims":[{"id":"milk-meat-hygiene--milk-cleaning--กลไกการทำลายเชื้อของ-disinfectant-ในการผลิตนม--v1","statement":"สารฆ่าเชื้อที่ใช้กันมานานประกอบด้วยกลุ่มหลักคือ alcohols, phenols, iodine และ chlorine ซึ่งมีกลไกการออกฤทธิ์ต่างจากยาปฏิชีวนะ และการจำแนกสารฆ่าเชื้อตามกลไกการออกฤทธิ์เป็นวิธีมาตรฐานในการทำความเข้าใจสารกลุ่มนี้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9880479","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A wide variety of active chemical agents (biocides) are found in these products, many of which have been used for hundreds of years, including alcohols, phenols, iodine, and chlorine ... This review considers what is known about the mode of"}},{"id":"milk-meat-hygiene--milk-cleaning--กลไกการทำลายเชื้อของ-disinfectant-ในการผลิตนม--v2","statement":"แนวทางของ CDC ระบุว่ากลไกหลักของแอลกอฮอล์คือการทำให้โปรตีนเสียสภาพ (denaturation of proteins) ตรงกับที่สไลด์จัดแอลกอฮอล์ไว้ในกลุ่มที่ทำให้โครงสร้างโปรตีนและไขมันเสียสภาพ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-centers-for-disease-co-2008","locator":"Chemical Disinfectants, Alcohol, Mode of Action","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The bactericidal action of alcohol is attributed to denaturation of proteins."}}]},"milk-meat-hygiene--milk-cleaning--สารฆ่าเชื้อรายกลุ่ม":{"claims":[{"id":"milk-meat-hygiene--milk-cleaning--สารฆ่าเชื้อรายกลุ่ม--v1","statement":"Glutaraldehyde ที่ความเข้มข้นมากกว่าร้อยละ 2 เป็นสารฆ่าสปอร์ได้ ต้องกระตุ้น (activate) ให้เป็นด่างที่ pH ประมาณ 7.5 ถึง 8.5 ก่อนใช้ และเหมาะสำหรับอุปกรณ์ที่ไม่ทนความร้อน ตรงกับที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-centers-for-disease-co-2008","locator":"Chemical Disinfectants, Glutaraldehyde","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Glutaraldehyde solutions exceeding 2% are sporicidal, require activation to alkaline pH 7.5-8.5, and are recommended for heat-sensitive equipment."}},{"id":"milk-meat-hygiene--milk-cleaning--สารฆ่าเชื้อรายกลุ่ม--v2","statement":"ตัวออกฤทธิ์จริงของคลอรีนคือ hypochlorous acid และประสิทธิภาพขึ้นกับ pH ของสารละลาย ตรงกับที่สไลด์ระบุว่า HOCl คือตัวออกฤทธิ์และทำงานดีเมื่อ pH ต่ำ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-centers-for-disease-co-2008","locator":"Chemical Disinfectants, Chlorine and Chlorine Compounds","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The active agent of chlorine is hypochlorous acid, and its effectiveness is significantly influenced by the pH of the solution."}},{"id":"milk-meat-hygiene--milk-cleaning--สารฆ่าเชื้อรายกลุ่ม--v3","statement":"Iodophores ออกฤทธิ์โดยปล่อยไอโอดีนอิสระ และฤทธิ์ลดลงเมื่อมีสารอินทรีย์ ยืนยันข้อที่แนวข้อสอบเน้นว่าประสิทธิภาพของ iodophore ลดลงเมื่อมีสารอินทรีย์สะสม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-centers-for-disease-co-2008","locator":"Chemical Disinfectants, Iodophors","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Iodophors release free iodine, though their activity is diminished in the presence of organic matter."}},{"id":"milk-meat-hygiene--milk-cleaning--สารฆ่าเชื้อรายกลุ่ม--v4","statement":"Quaternary ammonium compounds ถูกทำให้เสื่อมฤทธิ์โดยสารลดแรงตึงผิวชนิดประจุลบ (anionic detergents หรือ surfactants) น้ำกระด้าง และสารอินทรีย์ และออกฤทธิ์ที่ cell membrane ตรงกับข้อจำกัดที่สไลด์ระบุไว้ทั้งสามข้อ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-centers-for-disease-co-2008","locator":"Chemical Disinfectants, Quaternary Ammonium Compounds","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Quaternary ammonium compounds are inactivated by anionic detergents or surfactants, hard water and organic matter, and their mechanism targets the cell membrane."}}]},"milk-meat-hygiene--milk-cleaning--phenol-coefficient-p-c":{"claims":[{"id":"milk-meat-hygiene--milk-cleaning--phenol-coefficient-p-c--v1","statement":"Phenol coefficient เป็นค่ามาตรฐานที่ใช้เปรียบเทียบประสิทธิภาพของสารฆ่าเชื้อกับ phenol ภายใต้เงื่อนไขการทดสอบเดียวกัน และมีวิธีการทดสอบที่กำหนดไว้เป็นมาตรฐานในวรรณกรรมสุขศาสตร์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"doi-10-1017-s0022172400018829","locator":"Volume 33, issue 4, pages 485-494, title and method","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Determination of the Phenol Coefficient of Disinfectants by the Cover-Slip Method"}}]},"milk-meat-hygiene--milk-cleaning--กติกาการทำความสะอาดสายการผลิตนม-cip":{"claims":[{"id":"milk-meat-hygiene--milk-cleaning--กติกาการทำความสะอาดสายการผลิตนม-cip--v1","statement":"การฆ่าเชื้อ pasteurizer ด้วยน้ำร้อนใช้การหมุนเวียนน้ำที่ 90 ถึง 95 องศาเซลเซียส นาน 10 ถึง 15 นาที โดยอุณหภูมิขากลับต้องไม่ต่ำกว่า 85 องศาเซลเซียส ดังนั้นตัวเลข 85 องศาเซลเซียสในสไลด์คืออุณหภูมิขากลับขั้นต่ำ ไม่ใช่อุณหภูมิของน้ำที่ป้อนเข้าไป","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-tetra-pak-processing-s-1995","locator":"บท Cleaning of Dairy Equipment หัวข้อ disinfection ของฉบับออนไลน์ dairyprocessinghandbook.tetrapak.com","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This is typically done by circulating hot water at 90 – 95 °C for 10 – 15 minutes after the returning temperature is at least 85 °C."}},{"id":"milk-meat-hygiene--milk-cleaning--กติกาการทำความสะอาดสายการผลิตนม-cip--v2","statement":"การ pre-rinse ต้องทำทันทีหลังจบการผลิตเพื่อไม่ให้คราบนมแห้งติดผิว และคราบไขมันนม (milk fat) จะถูกชะออกได้ง่ายกว่าเมื่อใช้น้ำอุ่น แต่ต้องไม่เกิน 55 องศาเซลเซียสเพื่อเลี่ยงการตกตะกอนของโปรตีน ซึ่งสอดคล้องกับที่สไลด์ระบุว่าล้างด้วยน้ำอุ่นเพื่อเอา milk fat ที่ตกค้างออก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-tetra-pak-processing-s-1995","locator":"บท Cleaning of Dairy Equipment หัวข้อ pre-rinsing ของฉบับออนไลน์ dairyprocessinghandbook.tetrapak.com","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk fat residues are more easily flushed out if the pre-rinsing water is warm, but to avoid coagulation of proteins, the temperature should not exceed 55 °C."}}]}},"milk-meat-hygiene--milk-biosec-dairy":{"milk-meat-hygiene--milk-biosec-dairy--lecture-identity":{"claims":[{"id":"milk-meat-hygiene--milk-biosec-dairy--lecture-identity--v1","statement":"การเลี้ยงแบบ closed herd (ไม่นำสัตว์จากภายนอกเข้าฝูง) ลดความเสี่ยงของการนำเชื้อที่กระทบ udder health เข้าฟาร์ม และถ้าจำเป็นต้องซื้อสัตว์เข้าฝูง ต้องประเมินประวัติ udder health ของสัตว์นั้น ร่วมกับตรวจร่างกายและตรวจโรคติดต่อก่อนนำเข้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19762787","locator":"92(10):4717-29, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Maintaining a closed herd decreases the risk of introduction of pathogens that affect udder health directly or indirectly. If animals are purchased, their udder health history should be evaluated and they should be examined and tested for c"}},{"id":"milk-meat-hygiene--milk-biosec-dairy--lecture-identity--v2","statement":"สัตว์ที่นำเข้าฝูงใหม่ต้องถูกคัดกรอง contagious intramammary infection (IMI) ก่อนที่ฝูงเดิมจะสัมผัสกับสัตว์นั้น และต้องมีระบบเฝ้าระวังเพื่อตรวจจับ contagious IMI ให้เร็วที่สุดหลังนำสัตว์เข้าฝูง เพื่อป้องกันการระบาดของ contagious mastitis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12064164","locator":"18(1):115-31, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"To prevent costly outbreaks of contagious mastitis, introduced animals must be screened for contagious IMI before the resident herd is exposed to them. Screening programs must be instituted to detect the appearance of contagious IMI as soon"}},{"id":"milk-meat-hygiene--milk-biosec-dairy--lecture-identity--v3","statement":"การซื้อโคหรือโคสาวเข้าฝูง เป็นปัจจัยที่เพิ่มความเสี่ยงต่อการเกิดการติดเชื้อ Streptococcus agalactiae ใหม่ในระดับฝูง (herd infection) จากการศึกษาแบบ case-control ในฟาร์มโคนมเดนมาร์ก โดยวินิจฉัยฝูงติดเชื้อจากการตรวจทางจุลชีววิทยาของ bulk tank milk","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8038790","locator":"25(2-3):227-34, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Results from logistic regression clearly indicate that purchase of cows or heifers increases the risk of a new Streptococcus agalactiae herd infection. Hygiene management risk factors inside the farm were also identified."}}]},"milk-meat-hygiene--milk-biosec-dairy--lecture-outline-3-หัวข้อหลัก":{"claims":[{"id":"milk-meat-hygiene--milk-biosec-dairy--lecture-outline-3-หัวข้อหลัก--v1","statement":"มาตรฐานฟาร์มโคนมของไทยที่ใช้อ้างอิงคือ มาตรฐานสินค้าเกษตร มกษ. 6402-2562 (TAS 6402-2019) การปฏิบัติทางการเกษตรที่ดีสำหรับฟาร์มโคนม ออกโดยสำนักงานมาตรฐานสินค้าเกษตรและอาหารแห่งชาติ (มกอช.) กระทรวงเกษตรและสหกรณ์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--acfs--2019","locator":"ยืนยันได้เฉพาะเลขมาตรฐาน ชื่อเรื่อง ปี และหน่วยงานที่ออก จากหน้าปกไฟล์ราชการ (opsmoac.go.th) ยังไม่ได้อ่านเนื้อในเพื่อระบุเลขข้อ จึงไม่ระบุ clause","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"มาตรฐานสินค้าเกษตร มกษ. 6402-2562 THAI AGRICULTURAL STANDARD TAS 6402-2019"}},{"id":"milk-meat-hygiene--milk-biosec-dairy--lecture-outline-3-หัวข้อหลัก--v2","statement":"แนวปฏิบัติสากล FAO/IDF Guide to Good Dairy Farming Practice ระบุว่าเกษตรกรโคนมต้องใช้ GAP ครอบคลุม 5 ด้าน ได้แก่ animal health, milking hygiene, animal feeding and water, animal welfare และ environment","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-2004","locator":"หัวข้อ Guiding objective for good dairy farming practice (ฉบับ HTML ไม่มีเลขหน้า)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"To achieve this, dairy farmers need to apply GAP in the following areas: animal health; milking hygiene; animal feeding and water; animal welfare; and environment."}}]},"milk-meat-hygiene--milk-biosec-dairy--มาตรฐานฟาร์มโคนม-gap":{"claims":[{"id":"milk-meat-hygiene--milk-biosec-dairy--มาตรฐานฟาร์มโคนม-gap--v1","statement":"มาตรฐานสินค้าเกษตร มกษ. 6402-2562 การปฏิบัติทางการเกษตรที่ดีสำหรับฟาร์มโคนม ครอบคลุมข้อกำหนดตั้งแต่องค์ประกอบฟาร์ม การจัดการฟาร์ม บุคลากร สุขภาพสัตว์ สวัสดิภาพสัตว์ สิ่งแวดล้อม และการบันทึกข้อมูล เพื่อให้ได้น้ำนมดิบคุณภาพและโคนมสุขภาพดี ตรงกับหมวดการตรวจประเมินที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--national-bureau-of-ag-2019","locator":"ขอบข่ายและข้อกำหนดของมาตรฐาน","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"มาตรฐานนี้ครอบคลุมข้อกำหนดตั้งแต่องค์ประกอบฟาร์ม การจัดการฟาร์ม บุคลากร สุขภาพสัตว์ สวัสดิภาพสัตว์ สิ่งแวดล้อม และการบันทึกข้อมูล เพื่อเพิ่มประสิทธิภาพการผลิต ให้โคนมมีสุขภาพดี และได้น้ำนมดิบที่มีคุณภาพ"}}]},"milk-meat-hygiene--milk-biosec-dairy--มาตรฐานฟาร์มแพะนม-และการใช้ยาสัตว์":{"claims":[{"id":"milk-meat-hygiene--milk-biosec-dairy--มาตรฐานฟาร์มแพะนม-และการใช้ยาสัตว์--v1","statement":"มาตรฐานน้ำนมแพะดิบของไทยนิยามว่าเป็นน้ำนมที่รีดจากแม่แพะหลังคลอดแล้วไม่น้อยกว่า 3 วัน ปราศจากน้ำนมเหลือง โดยไม่แยกองค์ประกอบออกหรือเติมวัตถุอื่นใด และไม่ผ่านกรรมวิธีใดยกเว้นการทำให้เย็น ตรงกับนิยามในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide--national-bureau-of-ag-2008","locator":"บทนิยาม (definition of raw milk)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"น้ำนมดิบ หมายถึง น้ำนมที่รีดจากแม่สัตว์หลังจากคลอดลูกแล้วไม่น้อยกว่า 3 วัน และต้องปราศจากน้ำนมเหลือง (colostrum) โดยมิได้แยกออกหรือเติมวัตถุอื่นใด และไม่ได้ผ่านกรรมวิธีใด ๆ ยกเว้นการทำให้เย็น"}},{"id":"milk-meat-hygiene--milk-biosec-dairy--มาตรฐานฟาร์มแพะนม-และการใช้ยาสัตว์--v2","statement":"WOAH กำหนดให้ผู้ใช้ยาสัตว์ต้องปฏิบัติตามและบันทึกระยะเวลาหยุดยา (withdrawal period) ที่แนะนำ เพื่อให้ระดับสารตกค้างในอาหารที่ได้จากสัตว์ไม่ก่อความเสี่ยงต่อผู้บริโภค ยืนยันข้อกำหนดเรื่องระยะหยุดยาก่อนส่งน้ำนม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Article 6.10.7.2.6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"comply with and record the recommended withdrawal periods to ensure that residue levels in animal-derived food do not present a risk for the consumer"}},{"id":"milk-meat-hygiene--milk-biosec-dairy--มาตรฐานฟาร์มแพะนม-และการใช้ยาสัตว์--v3","statement":"การใช้ยาสัตว์นอกฉลาก (extra-label หรือ off-label use) อนุญาตได้ในสถานการณ์ที่เหมาะสม แต่เป็นความรับผิดชอบของสัตวแพทย์ที่ต้องกำหนดเงื่อนไขการใช้อย่างรับผิดชอบ และต้องเก็บบันทึกการใช้ยาต้านจุลชีพทุกครั้ง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Articles 6.10.6.3 and 6.10.7.2.9","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The extra-label or off-label use of VMP containing antimicrobial agents may be permitted in appropriate circumstances ... It is the veterinarian's responsibility to define the conditions of responsible use ... keep adequate records of all V"}},{"id":"milk-meat-hygiene--milk-biosec-dairy--มาตรฐานฟาร์มแพะนม-และการใช้ยาสัตว์--v4","statement":"การปนเปื้อน aflatoxin B1 ในอาหารสัตว์ (เช่น ข้าวโพด) ส่งผ่านมาเป็น aflatoxin M1 ในน้ำนมโคนม โดยมีเกณฑ์กำกับที่ 0.05 ไมโครกรัมต่อกิโลกรัม จึงเป็นเหตุผลที่มาตรฐานฟาร์มกำหนดให้สุ่มตรวจ aflatoxin B1 ในอาหารสัตว์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31247003","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This study aimed to investigate the impacts of climate change on aflatoxin B1 production in maize and its consequences on aflatoxin M1 contamination in dairy cow's milk ... the chance of finding aflatoxin M1 in milk above the EC limit of 0."}}]},"milk-meat-hygiene--milk-biosec-dairy--สุขศาสตร์ทุ่งหญ้า":{"claims":[{"id":"milk-meat-hygiene--milk-biosec-dairy--สุขศาสตร์ทุ่งหญ้า--v1","statement":"ระบบแทะเล็มแบบหมุนเวียนเข้มข้น (แทะเล็มสั้นราว 5 วัน พักแปลงยาวราว 103 วัน) ทำให้ความชุกของตัวอ่อนพยาธิในแปลงหญ้าลดลงจริง โดยแกะ tracer ในระบบนี้มีค่าไข่พยาธิในอุจจาระต่ำกว่าระบบอื่นอย่างมีนัยสำคัญ และผลดีเกิดจากการลดการสัมผัสตัวอ่อนพยาธิ ไม่ใช่จากความต้านทานของตัวสัตว์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21924833","locator":"Abstract, results and conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The tracer sheep (used to determine pasture infectivity) on IRG had significantly lower WECs during winter, spring and summer than those under the other management systems ... This demonstrates that the effects of IRG on WEC are mediated by"}}]},"milk-meat-hygiene--milk-biosec-dairy--วงจรใบรับรอง-และการตรวจประเมิน":{"claims":[{"id":"milk-meat-hygiene--milk-biosec-dairy--วงจรใบรับรอง-และการตรวจประเมิน--v1","statement":"นิยามตามกรมปศุสัตว์ระบุว่า ข้อบกพร่องไม่รุนแรง (Minor Nonconformity) คือสิ่งที่ไม่เป็นไปตามข้อกำหนดในบางส่วนและไม่มีผลร้ายแรงต่อระบบการผลิต ส่วนข้อบกพร่องรุนแรง (Major Nonconformity) คือสิ่งที่ไม่เป็นไปตามข้อกำหนดและส่งผลร้ายแรงต่อระบบการผลิต และข้อสังเกต (Recommendation) ไม่ถือเป็นข้อบกพร่องแต่หากละเลยอาจนำไปสู่ข้อบกพร่องได้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2558","locator":"บทนิยามและอักษรย่อ รหัส PM-GAP-GLO-01 ข้อ 3.25 ถึง 3.27","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ข้อบกพร่องไม่รุนแรง (Minor Nonconformity) หมายถึง สิ่งที่ไม่เป็นไปตามข้อกำหนดการปฏิบัติทางการเกษตรที่ดีหรือมาตรฐานฟาร์มเลี้ยงสัตว์ในบางส่วน และไม่มีผลร้ายแรงต่อระบบการผลิต"}},{"id":"milk-meat-hygiene--milk-biosec-dairy--วงจรใบรับรอง-และการตรวจประเมิน--v2","statement":"การตรวจกรณีพิเศษ (Special Audit) คือการตรวจสถานประกอบการที่ได้รับการรับรองซึ่งมีปัญหา มีการร้องเรียน หรือมีการโอนกิจการ และการตรวจชนิดนี้อาจไม่แจ้งให้ผู้ประกอบการทราบล่วงหน้า ตรงกับที่สไลด์ระบุว่าเข้าตรวจโดยไม่แจ้งฟาร์มล่วงหน้า","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2558","locator":"บทนิยาม PM-GAP-GLO-01 ข้อ 3.23 และข้อกำหนดทั่วไป PM-GAP-GER-01 ข้อ 10","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"การตรวจกรณีพิเศษ (Special Audit) หมายถึง การตรวจสถานประกอบการที่ได้รับการรับรอง ซึ่งมีปัญหา มีการร้องเรียน มีการโอนกิจการ หรืออื่นๆ การตรวจชนิดนี้อาจไม่แจ้งให้ผู้ประกอบการทราบล่วงหน้า"}},{"id":"milk-meat-hygiene--milk-biosec-dairy--วงจรใบรับรอง-และการตรวจประเมิน--v3","statement":"เหตุเพิกถอนการรับรองข้อหนึ่งคือไม่ปฏิบัติตามระบบที่ได้รับการรับรองหลังจากถูกพักใช้การรับรอง 2 ครั้งภายในระยะเวลา 3 ปี ตรงกับที่สไลด์ระบุ และผู้ที่ถูกเพิกถอนจะไม่ได้รับการพิจารณารับรองอีกเป็นเวลา 3 ปี","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2558","locator":"ข้อกำหนดทั่วไป PM-GAP-GER-01 ข้อ 13.1.3 และ 13.6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"13.1.3 ไม่ปฏิบัติตามระบบที่ได้รับการรับรองหลังจากถูกพักใช้การรับรอง 2 ครั้ง ภายในระยะเวลา 3 ปี"}}]}},"milk-meat-hygiene--meat-hygiene-intro":{"milk-meat-hygiene--meat-hygiene-intro--meat-as-a-food-definition-4-categories":{"claims":[{"id":"milk-meat-hygiene--meat-hygiene-intro--meat-as-a-food-definition-4-categories--v1","statement":"ตามนิยามของ Codex Code of Hygienic Practice for Meat คำว่า meat หมายถึงทุกส่วนของสัตว์ที่ตั้งใจให้ใช้เป็นอาหาร หรือได้รับการตัดสินแล้วว่า safe and suitable สำหรับการบริโภคของมนุษย์ ซึ่งครอบคลุมกว้างกว่าเฉพาะ muscle tissue","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2005","locator":"Definitions section, entry for 'meat'. ไม่ได้ยืนยันเลขข้อย่อยที่แน่นอน จึงไม่ระบุ clause number","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":""}},{"id":"milk-meat-hygiene--meat-hygiene-intro--meat-as-a-food-definition-4-categories--v2","statement":"IARC นิยาม red meat ว่าเป็น mammalian muscle meat ทั้งหมด ซึ่งรวม beef, veal, pork, lamb, mutton, horse และ goat และจากการประเมินของ IARC Working Group จัด processed meat ไว้ใน Group 1 (carcinogenic to humans) ส่วน red meat อยู่ใน Group 2A (probably carcinogenic to humans)","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-international-agency-f-2018","locator":"Working Group evaluation (ประกาศผลการประเมินเดือนตุลาคม 2015, monograph เล่มเต็มตีพิมพ์ปี 2018) ไม่ได้ยืนยันเลขหน้า","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":""}}]},"milk-meat-hygiene--meat-hygiene-intro--meat-components-5-tissue-types":{"claims":[{"id":"milk-meat-hygiene--meat-hygiene-intro--meat-components-5-tissue-types--v1","statement":"Intramuscular connective tissue (IMCT) โดยเฉพาะส่วน perimysium เป็นโครงสร้างที่กำหนด mechanical integrity ของเนื้อที่ปรุงสุกมากที่สุด และการทำสุกจะเพิ่มความแข็งแรงของ IMCT ในช่วง 20-50 องศาเซลเซียส แต่ลดบทบาทของมันลงเมื่ออุณหภูมิสูงขึ้นหรือใช้เวลานานขึ้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22063743","locator":"Meat Sci 2005;70(3):435-47, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The perimysial component of IMCT varies most in amount between muscles and is also the IMCT structure most involved in defining the mechanical integrity of cooked meat. ... Cooking increases IMCT strength in the range 20-50 °C and decreases"}}]},"milk-meat-hygiene--meat-hygiene-intro--nutrition-structure-global-trends":{"claims":[{"id":"milk-meat-hygiene--meat-hygiene-intro--nutrition-structure-global-trends--v1","statement":"สีของเนื้อสดถูกกำหนดโดย myoglobin โดย deoxymyoglobin ให้สีม่วง, oxymyoglobin ให้สีแดงสด และเมื่อ oxidize ไปเป็น metmyoglobin จะให้สีน้ำตาล ทั้งนี้เนื้อวัวที่มี myoglobin สูงจะเกิดการเปลี่ยนสี (discoloration) ได้ง่ายกว่าเนื้อไก่ขาว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28846443","locator":"Crit Rev Food Sci Nutr 59(2):228-252, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A decreased redness is attributed to a large degree to the oxidation of the bright red oxymyoglobin or the purplish deoxymyoglobin into the brownish metmyoglobin, as well as to the denaturation of myoglobin. Surely, the high myoglobin conte"}}]},"milk-meat-hygiene--meat-hygiene-intro--muscle-fiber-types":{"claims":[{"id":"milk-meat-hygiene--meat-hygiene-intro--muscle-fiber-types--v1","statement":"Type I (slow-twitch oxidative fiber) มี myoglobin และ oxidative metabolic enzyme ในไมโทคอนเดรียสูง และสัดส่วน MyHC I ที่มากขึ้นทำให้เนื้อมีค่าความแดง (redness) สูงขึ้น ตรงกับที่สไลด์จัด Type I เป็น red fiber ที่ myoglobin สูง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32593014","locator":"Abstract, discussion of MyHCI fiber and meat redness","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The slow-twitch oxidative fiber (MyHCI) is rich in myoglobin and mitochondrial oxidative metabolic enzymes, and the increased expression of MyHCI fiber in pork has resulted in higher redness value."}},{"id":"milk-meat-hygiene--meat-hygiene-intro--muscle-fiber-types--v2","statement":"สัดส่วน fiber ชนิด IIx และ IIb (white/glycolytic fiber) สัมพันธ์ทางบวกกับ drip loss และกับการลดลงของ pH หลังตาย ส่วน type IIa สัมพันธ์ทางลบกับการลดลงของ pH จึงยืนยันว่าชนิดของ muscle fiber กำหนดคุณภาพเนื้อจริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26214468","locator":"Abstract, correlation results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The drip loss parameter was positively correlated with type IIx+IIb fiber content (r = 0.55, P < 0.05). Decreased pH was strongly positively correlated with type IIx+IIb fiber content (r = 0.61, P < 0.01) and negatively correlated with type"}},{"id":"milk-meat-hygiene--meat-hygiene-intro--muscle-fiber-types--v3","statement":"การเลี้ยงที่ทำให้ fiber มีขนาดใหญ่ขึ้นจะมาพร้อมกับสัดส่วน type IIb ที่มากขึ้น และ type IIb สัมพันธ์ทางลบกับคุณภาพเนื้อบางลักษณะ สอดคล้องกับที่สไลด์ระบุว่า white fiber (IIB) มี fiber diameter ใหญ่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33062658","locator":"Abstract, conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"rearing the Krskopolje pig breed in a conventional system would result in an increased fiber size and a greater proportion of type IIb myofibers, which are known to be negatively correlated with some meat quality traits"}}]},"milk-meat-hygiene--meat-hygiene-intro--โปรตีนและ-dipeptides-ระบุชนิดเนื้อ":{"claims":[{"id":"milk-meat-hygiene--meat-hygiene-intro--โปรตีนและ-dipeptides-ระบุชนิดเนื้อ--v1","statement":"อัตราส่วนของ histidine dipeptides (anserine ต่อ carnosine) ในกล้ามเนื้อลายแตกต่างกันมากระหว่างชนิดสัตว์ จึงใช้ตรวจการปลอมปนเนื้อต่างชนิดในผลิตภัณฑ์เนื้อได้จริงด้วย HPLC","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-4062740","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The ratio of the histidine dipeptides anserine and carnosine which are present in skeletal muscle, are so different between sheep, cattle, horse and kangaroo that detection of adulteration can be rapidly achieved by chromatography on a Part"}}]},"milk-meat-hygiene--meat-hygiene-intro--ไขมัน-แร่ธาตุ-คาร์โบไฮเดรต-วิตามิน":{"claims":[{"id":"milk-meat-hygiene--meat-hygiene-intro--ไขมัน-แร่ธาตุ-คาร์โบไฮเดรต-วิตามิน--v1","statement":"ความแข็ง (firmness/hardness) ของไขมันซากในสุกร โค และแกะ สัมพันธ์ใกล้ชิดกับความเข้มข้นของ stearic acid (18:0) ซึ่งเป็นกรดไขมันอิ่มตัว ยืนยันว่าความแข็งของไขมันขึ้นกับสัดส่วน SFA ต่อ UFA","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22063928","locator":"Abstract, closing sentence","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In pork, beef and lamb the melting point of lipid and the firmness/hardness of carcass fat is closely related to the concentration of stearic acid (18:0)."}},{"id":"milk-meat-hygiene--meat-hygiene-intro--ไขมัน-แร่ธาตุ-คาร์โบไฮเดรต-วิตามิน--v2","statement":"องค์ประกอบกรดไขมันเป็นตัวกำหนดทั้งความแข็งหรือความเหลวของเนื้อเยื่อไขมัน และความคงตัวต่อการเกิด oxidation ของกล้ามเนื้อ ซึ่งส่งผลต่อกลิ่นรสและสีของเนื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22062452","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Fatty acid composition determines the firmness/oiliness of adipose tissue and the oxidative stability of muscle, which in turn affects flavour and muscle colour."}}]},"milk-meat-hygiene--meat-hygiene-intro--นิยามและประเภทเนื้อสัตว์":{"claims":[{"id":"milk-meat-hygiene--meat-hygiene-intro--นิยามและประเภทเนื้อสัตว์--v1","statement":"Codex นิยาม meat ว่าเป็นทุกส่วนของสัตว์ที่มุ่งหมายให้ หรือถูกตัดสินแล้วว่าปลอดภัยและเหมาะสมสำหรับการบริโภคของมนุษย์ ซึ่งตรงกับนิยามในสไลด์ที่ว่าเนื้อสัตว์คือเนื้อเยื่อสัตว์ที่เหมาะสมใช้เป็นอาหาร","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2005","locator":"Section 3 Definitions, page 6 of 52","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Meat: All parts of an animal that are intended for, or have been judged as safe and suitable for, human consumption."}},{"id":"milk-meat-hygiene--meat-hygiene-intro--นิยามและประเภทเนื้อสัตว์--v2","statement":"Meat hygiene หมายถึงทุกเงื่อนไขและมาตรการที่จำเป็นเพื่อประกันความปลอดภัยและความเหมาะสมของเนื้อสัตว์ตลอดห่วงโซ่อาหาร และหลักการทั่วไปข้อ iii ระบุว่าโปรแกรม meat hygiene ต้องมีเป้าหมายหลักคือการคุ้มครองสุขภาพประชาชน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2005","locator":"Section 4 General Principles of Meat Hygiene, principle iii, page 8 of 52","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Meat hygiene programmes should have as their primary goal the protection of public health and should be based on a scientific evaluation of meat-borne risks to human health"}},{"id":"milk-meat-hygiene--meat-hygiene-intro--นิยามและประเภทเนื้อสัตว์--v3","statement":"ขอบเขตของเนื้อสัตว์ตาม Codex ครอบคลุมทั้งสัตว์เลี้ยง (domestic ungulates, solipeds, domestic birds, lagomorphs) สัตว์ป่าที่เลี้ยงในระบบฟาร์ม (farmed game, farmed game birds รวม ratites) และสัตว์ป่า (wild game) จึงยืนยันว่า game meat คือเนื้อจากสัตว์ที่ไม่ใช่สัตว์เลี้ยงเป็นหมวดหมู่ที่มีอยู่จริงในมาตรฐานสากล","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2005","locator":"Section 2 Scope and Use of This Code, paragraph 7, page 4 of 52","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For the purposes of this code, meat is that derived from domestic ungulates, domestic solipeds, domestic birds, lagomorphs, farmed game, farmed game birds (including ratites) and wild game."}}]}},"milk-meat-hygiene--meat-seafood":{"milk-meat-hygiene--meat-seafood--spoilage-mechanisms-seafood-toxins-detail":{"claims":[{"id":"milk-meat-hygiene--meat-seafood--spoilage-mechanisms-seafood-toxins-detail--v1","statement":"Scombroid poisoning หรือ histamine fish poisoning เกิดจากแบคทีเรียที่ใช้เอนไซม์ histidine decarboxylase เปลี่ยน free histidine ในเนื้อปลาไปเป็น histamine โดยการลดอุณหภูมิที่ไม่เพียงพอหลังจับปลาเป็นตัวส่งเสริมการสร้าง histamine และปลาที่มี free histidine สูงคือกลุ่มที่พบเป็นสาเหตุบ่อยที่สุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20152850","locator":"Toxicon 2010;56(2):231-43, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Inadequate cooling following harvest promotes bacterial histamine production, and can result in outbreaks of scombroid poisoning. Fish with high levels of free histidine, the enzyme substrate converted to histamine by bacterial histidine de"}},{"id":"milk-meat-hygiene--meat-seafood--spoilage-mechanisms-seafood-toxins-detail--v2","statement":"Histamine-forming bacteria ที่เชื่อมโยงกับ scombroid fish poisoning ส่วนใหญ่เป็นแบคทีเรีย Gram-negative เช่น Morganella spp. และ Photobacterium spp. ซึ่งมียีน hdc สำหรับสร้าง histidine decarboxylase และพบได้ที่เหงือก ทางเดินอาหาร และผิวหนังของปลา โดยเฉพาะปลาในวงศ์ Scombridae","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36916556","locator":"J Food Prot 2023;86(3):100049, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Previous studies linked a plethora of Gram-negative HFB including Morganella spp. and Photobacterium spp. to scombroid fish poisoning from many types of seafood, especially the Scombridae family. These bacteria possess the hdc gene to produ"}},{"id":"milk-meat-hygiene--meat-seafood--spoilage-mechanisms-seafood-toxins-detail--v3","statement":"Paralytic shellfish poisoning (PSP) เกิดจาก saxitoxins ที่สร้างโดย dinoflagellate Alexandrium catenella แล้วสะสมผ่านห่วงโซ่อาหารในหอยกรองอาหาร โดยเกณฑ์ความปลอดภัยด้านอาหารทะเลที่ใช้อ้างอิงคือ 80 ไมโครกรัม STX equivalents ต่อเนื้อหอย 100 กรัม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35550288","locator":"Harmful Algae 2022;114:102205, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This algal species produces neurotoxins that impact marine wildlife health and cause the human illness known as paralytic shellfish poisoning (PSP). ... PSTs (saxitoxin equivalents, STX eq.) were detected in all trophic levels with concentr"}},{"id":"milk-meat-hygiene--meat-seafood--spoilage-mechanisms-seafood-toxins-detail--v4","statement":"Ciguatera fish poisoning เป็นโรคจาก seafood toxin ที่มีรายงานบ่อยที่สุดในโลก อาการเป็นชุดผสมของระบบทางเดินอาหาร ระบบประสาทและ neuropsychological และระบบหัวใจหลอดเลือด ซึ่งอาจคงอยู่เป็นวัน สัปดาห์ หรือเป็นเดือน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28335428","locator":"Mar Drugs 2017;15(3):72, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Ciguatera Fish Poisoning (CFP) is the most frequently reported seafood-toxin illness in the world. ... The illness produces a complex array of gastrointestinal, neurological and neuropsychological, and cardiovascular symptoms, which may las"}},{"id":"milk-meat-hygiene--meat-seafood--spoilage-mechanisms-seafood-toxins-detail--v5","statement":"Tetrodotoxin (TTX) เป็น neurotoxin ที่พบครั้งแรกในปลาปักเป้า แต่ตรวจพบได้ในสัตว์หลายกลุ่มที่มีแบคทีเรียสร้าง TTX อาศัยอยู่ ออกฤทธิ์หลักโดยยับยั้ง voltage-gated sodium channels และขนาดที่ทำให้คนเสียชีวิตอยู่ในช่วงประมาณ 1.5 ถึง 2.0 มิลลิกรัม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34437388","locator":"Toxins (Basel) 2021;13(8):517, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tetrodotoxin (TTX) is a potent neurotoxin that was first identified in pufferfish but has since been isolated from an array of taxa that host TTX-producing bacteria. ... TTX is primarily a powerful sodium channel inhibitor that targets volt"}},{"id":"milk-meat-hygiene--meat-seafood--spoilage-mechanisms-seafood-toxins-detail--v6","statement":"ในปลาแช่เย็น Shewanella baltica ถูกจัดเป็น specific spoilage organism โดยสามารถ reduce trimethylamine-N-oxide (TMAO) ไปเป็น trimethylamine (TMA) และสร้าง H2S ทำให้ค่า TVB-N สูงกว่ากลุ่ม Pseudomonas อย่างมีนัยสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27747903","locator":"Lett Appl Microbiol 64(1):86-93, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All of them were able to grow aerobically from 4 to 30°C, and reduce trimethylamine-N-oxide to trimethylamine (TMA) and produce H S except SB01, PF05 and PF07. ... the TVB-N value of S. baltica was significantly higher than that of Pseudomo"}}]},"milk-meat-hygiene--meat-seafood--chemical-composition-of-seafood":{"claims":[{"id":"milk-meat-hygiene--meat-seafood--chemical-composition-of-seafood--v1","statement":"seafood ครอบคลุมสัตว์หลายกลุ่มที่ต่างไฟลัมกัน (ปลา, กุ้ง, หอยสองฝา) และองค์ประกอบทางเคมีต่างกันมากระหว่างกลุ่ม โดยในการศึกษาเดียวกัน moisture อยู่ในช่วง 74.6-89.5 g/100 g และ protein 6.8-21 g/100 g","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23894993","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the moisture content ranged from 74.6-80.6g/100g for snook 76.9-80.0g/100g for shrimp and 77.9-89.5g/100g for green mussel. After the moisture, the protein was the most abundant chemical fraction (6.8 to 21g/100g)"}}]},"milk-meat-hygiene--meat-seafood--composition-comparison-fish-vs-other-proteins":{"claims":[{"id":"milk-meat-hygiene--meat-seafood--composition-comparison-fish-vs-other-proteins--v1","statement":"ในปลาทะเล ปริมาณ ash ค่อนข้างคงที่ (1.10-1.61%) ขณะที่ moisture (48.01-83.05%) และ fat (0.87-30.48%) แปรผันกว้างมากระหว่างชนิด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20874243","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Moisture, fat, ash, and carbohydrate contents of raw fish ranged between 48.01% and 83.05%, 0.87% and 30.48%, 1.10% and 1.61%, and 0.09% and 8.70%, respectively."}},{"id":"milk-meat-hygiene--meat-seafood--composition-comparison-fish-vs-other-proteins--v2","statement":"ไขมันคือองค์ประกอบหลักที่แปรผันมากที่สุดระหว่างชนิดปลา ซึ่งอธิบายว่าทำไมช่วง lipid ของปลาในตารางจึงกว้างกว่าองค์ประกอบอื่น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28231154","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The lipid content was the most varying main component within the different species, ranging between 1.2% to 2.0% and 0.3% to 3.0% for farmed turbot and barramundi, respectively. Pangasius flesh had a mean lipid content of 7.8%."}}]},"milk-meat-hygiene--meat-seafood--องค์ประกอบของเนื้อปลา":{"claims":[{"id":"milk-meat-hygiene--meat-seafood--องค์ประกอบของเนื้อปลา--v1","statement":"คอลลาเจนของปลาไม่ทนความร้อน (thermolabile) กว่าคอลลาเจนของสัตว์เลือดอุ่น และมี cross-link น้อยกว่าและสลายง่ายกว่า จึงเป็นเหตุผลที่เนื้อปลานุ่มและสุกเร็วกว่าเนื้อสัตว์บก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-1995","locator":"Chapter 4, connective tissue proteins","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The collagen in fish is much more thermolabile and contains fewer but more labile cross-links than collagen from warm-blooded vertebrates."}},{"id":"milk-meat-hygiene--meat-seafood--องค์ประกอบของเนื้อปลา--v2","statement":"องค์ประกอบหลักของ non-protein nitrogen fraction ในเนื้อปลาคือ volatile bases เช่น ammonia และ trimethylamine oxide (TMAO), creatine, free amino acids, nucleotides และ purine bases และในปลากระดูกอ่อนจะมี urea ด้วย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-1995","locator":"Chapter 4, extractives (NPN fraction)","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The major components in this fraction are: volatile bases such as ammonia and trimethylamine oxide (TMAO), creatine, free amino-acids, nucleotides and purine bases, and, in the case of cartilaginous fish, urea."}},{"id":"milk-meat-hygiene--meat-seafood--องค์ประกอบของเนื้อปลา--v3","statement":"TMAO พบในปลาทะเลทุกชนิดแต่แทบไม่พบในปลาน้ำจืด และเชื่อกันว่ามีบทบาทด้าน osmoregulation หมายเหตุว่าแหล่งอ้างอิงจำแนกตามแกนทะเลเทียบน้ำจืด ไม่ใช่แกน demersal เทียบ pelagic อย่างที่สไลด์ระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-1995","locator":"Chapter 4, TMAO","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"TMAO is found in all marine fish species ... but is virtually absent from freshwater species ... it is now generally believed that TMAO has an osmoregulatory role."}},{"id":"milk-meat-hygiene--meat-seafood--องค์ประกอบของเนื้อปลา--v4","statement":"แบคทีเรียกลุ่มก่อการเน่าเสียใช้ TMAO เป็นตัวรับอิเล็กตรอน แล้วรีดิวซ์เป็น trimethylamine (TMA) ซึ่งเป็นองค์ประกอบเด่นของปลาที่กำลังเน่า และให้กลิ่นคาวปลาแบบเฉพาะตัว","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-1995","locator":"Chapter 5, bacterial spoilage","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The reduced component, TMA, which is one of the dominant components of spoiling fish, has a typical fishy odour."}}]},"milk-meat-hygiene--meat-seafood--ไขมันและสารอาหารอื่นของสัตว์น้ำ":{"claims":[{"id":"milk-meat-hygiene--meat-seafood--ไขมันและสารอาหารอื่นของสัตว์น้ำ--v1","statement":"ปริมาณคาร์โบไฮเดรตในกล้ามเนื้อปลาต่ำมาก โดยทั่วไปต่ำกว่า 0.5 เปอร์เซ็นต์ สอดคล้องกับที่สไลด์ระบุว่า glycogen ในกล้ามเนื้อปลาต่ำกว่าสัตว์เลี้ยงลูกด้วยนม","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-1995","locator":"Chapter 4, carbohydrate","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The carbohydrate content in fish muscle is very low, usually below 0.5 %."}},{"id":"milk-meat-hygiene--meat-seafood--ไขมันและสารอาหารอื่นของสัตว์น้ำ--v2","statement":"เป้าหมายทางโภชนาการของการปรับองค์ประกอบกรดไขมันคือเพิ่มอัตราส่วน PUFA ต่อ SFA ให้สูงขึ้นและทำให้สมดุล n-6 ต่อ n-3 ดีขึ้น ซึ่งเป็นเหตุผลเบื้องหลังการใช้ค่า PUFA/SFA ratio เป็นเกณฑ์เปรียบเทียบ (แหล่งอ้างอิงไม่ได้ระบุตัวเลขขั้นต่ำ 0.45)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22063928","locator":"Abstract, opening sentence","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Interest in meat fatty acid composition stems mainly from the need to find ways to produce healthier meat, i.e. with a higher ratio of polyunsaturated (PUFA) to saturated fatty acids and a more favourable balance between n-6 and n-3 PUFA."}}]},"milk-meat-hygiene--meat-seafood--การประเมินความสดของปลาและอาหารทะเล":{"claims":[{"id":"milk-meat-hygiene--meat-seafood--การประเมินความสดของปลาและอาหารทะเล--v1","statement":"ในปลาตระกูล gadoid นั้น TMA เป็นองค์ประกอบส่วนใหญ่ของ total volatile bases (TVB หรือ TVN) จนถึงระยะเน่าเสีย และเมื่อ TMAO ถูกใช้หมดแล้วค่า TVB ยังคงสูงขึ้นจาก NH3 และ amine ระเหยอื่น ดังนั้น TVB-N จึงเป็นดัชนีความสดที่ใช้ได้จริงแต่ต้องตีความตามระยะการเก็บ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-1995","locator":"Chapter 5, chemical indices of spoilage","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In cod and other gadoid fishes, TMA constitutes most of the so-called total volatile bases, TVB (also called total volatile nitrogen, TVN) until spoilage."}},{"id":"milk-meat-hygiene--meat-seafood--การประเมินความสดของปลาและอาหารทะเล--v2","statement":"US FDA กำหนดให้ indole ตั้งแต่ 25 ไมโครกรัมต่อ 100 กรัมตัวอย่างขึ้นไป (วิเคราะห์ตามวิธี AOAC 981.07) เป็นตัวชี้วัดทางเคมีของการเน่าสลาย (decomposition) ในผลิตภัณฑ์กุ้งทุกชนิด ตรงกับที่สไลด์ระบุว่าใช้ indole ประเมินความสดของกุ้ง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-u-s-food-and-drug-admi-2011","locator":"Section on chemical indicators of decomposition in shrimp","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For indole levels greater than or equal to 25 micrograms indole per 100 grams sample, based on the AOAC, 18th Edition, Method 35.1.35 (981.07), this is an appropriate chemical indicator of decomposition for all shrimp products."}},{"id":"milk-meat-hygiene--meat-seafood--การประเมินความสดของปลาและอาหารทะเล--v3","statement":"การผลิต indole ในกุ้งถูกใช้เป็นดัชนีบ่งชี้การเน่าสลายของกุ้ง โดยมีงานวิจัยเชิงทดลองยืนยันความสัมพันธ์ระหว่างการสร้าง indole กับระดับการเน่าสลายของกุ้ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"doi-10-1007-s00217-005-1171-y","locator":"Volume 221, pages 320-328, title and study aim","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Indole production and deepwater pink shrimp (Parapenaeus longirostris) decomposition"}},{"id":"milk-meat-hygiene--meat-seafood--การประเมินความสดของปลาและอาหารทะเล--v4","statement":"จุลชีพประจำถิ่นบนปลาน้ำอุณหภูมิพอเหมาะประกอบด้วยแบคทีเรียแกรมลบรูปแท่งที่เจริญได้ที่อุณหภูมิต่ำ ได้แก่ Pseudomonas, Moraxella, Acinetobacter, Shewanella และ Flavobacterium โดย Shewanella putrefaciens เป็นเชื้อก่อการเน่าเสียหลักในปลาทะเลที่แช่น้ำแข็ง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-food-and-agriculture-o-1995","locator":"Chapter 5, bacterial flora of fish","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The microflora on temperate water fish is dominated by psychrotrophic Gram-negative rod-shaped bacteria belonging to the genera Pseudomonas, Moraxella, Acinetobacter, Shewanella and Flavobacterium."}},{"id":"milk-meat-hygiene--meat-seafood--การประเมินความสดของปลาและอาหารทะเล--v5","statement":"Melanosis หรือการเกิดจุดดำในกุ้งเกิดจากเอนไซม์ polyphenoloxidase (PPO) ซึ่งเป็นชื่อที่ถูกต้องของเอนไซม์กลุ่มนี้ โดย PPO มีสมบัติเชิงจลนศาสตร์แบบ tyrosinase ดังนั้นคำว่า tylosinase ในเอกสารเป็นการสะกดผิดของ tyrosinase และชื่อทางเนื้อหาที่ถูกต้องคือ polyphenoloxidase","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30958915","locator":"Abstract, practical application","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Melanosis (black spot formation) triggered by polyphenoloxidase (PPO) drastically reduces the shelf-life of shrimp."}}]},"milk-meat-hygiene--meat-seafood--สารพิษในอาหารทะเล":{"claims":[{"id":"milk-meat-hygiene--meat-seafood--สารพิษในอาหารทะเล--v1","statement":"Tetrodotoxin เป็นสารพิษที่สร้างโดยแบคทีเรียในทะเล และแม้ปริมาณเพียงเล็กน้อยที่สร้างโดยจุลชีพในทางเดินอาหารของสัตว์ก็มีส่วนทำให้สัตว์นั้นมีพิษ ยืนยันข้อความในสไลด์ว่าพิษปลาปักเป้าสร้างโดยแบคทีเรีย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28513564","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This review is devoted to the marine bacterial producers of tetrodotoxin (TTX), a potent non-protein neuroparalytic toxin ... even minimal amounts of TTX produced by intestinal microflora of an animal can contribute to its toxicity."}},{"id":"milk-meat-hygiene--meat-seafood--สารพิษในอาหารทะเล--v2","statement":"Tetrodotoxin ออกฤทธิ์โดยยับยั้งกลไกการเปิดของ sodium channel ในการนำกระแสประสาทอย่างจำเพาะ โดยไม่กระทบการซึมผ่านของ K+ จึงอธิบายว่าทำไมอาการเด่นของพิษปลาปักเป้าจึงเป็นอาการทางระบบประสาท","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26178523","locator":"Abstract, opening sentence","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tetrodotoxin (TTX) is a deadly neurotoxin which selectively inhibits Na(+) activation mechanism of nerve impulse, without affecting the permeability of K(+) ions."}}]}},"milk-meat-hygiene--meat-microbiology":{"milk-meat-hygiene--meat-microbiology--introduction-where-contamination-starts":{"claims":[{"id":"milk-meat-hygiene--meat-microbiology--introduction-where-contamination-starts--v1","statement":"Salmonella อาศัยอยู่ในทางเดินอาหารของโคที่สุขภาพดีได้ตามปกติ และถูกถ่ายทอดมาปนเปื้อนที่ผิว carcass ระหว่างขั้นตอน hide removal และ evisceration","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26125489","locator":"Vol 210, pages 149-55 (abstract, opening statement and results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Salmonella is a foodborne pathogen that commonly inhabits the gastrointestinal tract of a healthy feedlot cattle and can be transferred to the carcass surface during hide removal and evisceration procedures."}},{"id":"milk-meat-hygiene--meat-microbiology--introduction-where-contamination-starts--v2","statement":"หนัง (hide) เป็นแหล่งปนเปื้อนหลักที่มี bacterial load สูงกว่าผิว carcass ชัดเจน โดยพบ mean total plate count บน exterior hide ในช่วง 8.2 ถึง 12.5 log CFU/100 cm2 ขณะที่ผิว carcass หลังลอกหนังแต่ก่อนทำ decontamination อยู่ในช่วง 6.1 ถึง 9.1 log CFU/100 cm2","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10945584","locator":"Vol 63, issue 8, pages 1080-6 (abstract, results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sponge swab samples yielded mean (log CFU/100 cm2) total plate counts (TPC), total coliform counts (TCC), and Escherichia coli counts (ECC) on the exterior hide in the ranges of 8.2 to 12.5, 6.0 to 7.9, and 5.5 to 7.5, respectively, while c"}}]},"milk-meat-hygiene--meat-microbiology--intrinsic-extrinsic-factors-standard-pathogen-panel":{"claims":[{"id":"milk-meat-hygiene--meat-microbiology--intrinsic-extrinsic-factors-standard-pathogen-panel--v1","statement":"Process hygiene criteria สำหรับ aerobic colony count และ Enterobacteriaceae บน carcass ตาม Commission Regulation (EC) No 2073/2005 อ้างอิงกับ destructive sampling (excision) เท่านั้น แต่อนุญาตให้ใช้ sampling scheme อื่น เช่น swab และใช้ indicator organism อื่น เช่น E. coli ได้ ถ้าพิสูจน์ได้ว่าให้หลักประกันความปลอดภัยเทียบเท่ากัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17706823","locator":"Vol 118, issue 2, pages 180-5 (abstract, aim and rationale)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These criteria apply only to destructive sampling of total aerobic counts and Enterobacteriaceae, but alternative sampling schemes, as well as alternative indicator organisms such as E. coli, are allowed if equivalent guarantees of food saf"}},{"id":"milk-meat-hygiene--meat-microbiology--intrinsic-extrinsic-factors-standard-pathogen-panel--v2","statement":"Campylobacter jejuni เป็นสาเหตุอันดับต้นของ bacterial gastroenteritis ทั่วโลก และการติดเชื้อมักถ่ายทอดผ่านการบริโภคเนื้อสัตว์ปีกดิบหรือปรุงไม่สุก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34041858","locator":"Vol 68, issue 6, pages 638-649 (abstract, opening statement)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Campylobacter jejuni is the leading cause of bacterial gastroenteritis globally, and infections are often transmitted through consumption of raw or undercooked poultry."}},{"id":"milk-meat-hygiene--meat-microbiology--intrinsic-extrinsic-factors-standard-pathogen-panel--v3","statement":"pH และ temperature ทำงานร่วมกันเป็น hurdle ต่อ Listeria monocytogenes โดยที่อุณหภูมิ chill 5 องศาเซลเซียส เชื้อเจริญได้ที่ pH 7.0 แต่ไม่เจริญที่ pH 5.13","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2118897","locator":"Vol 69, issue 1, pages 63-72 (abstract, results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At 5 degrees C growth occurred at pH 7.0 but not at pH 5.13."}},{"id":"milk-meat-hygiene--meat-microbiology--intrinsic-extrinsic-factors-standard-pathogen-panel--v4","statement":"Pseudomonas ที่สร้าง protease เป็นกลุ่มเด่นของ spoilage flora ในเนื้อดิบที่เก็บแบบ aerobic ที่อุณหภูมิ chill โดยมี Enterobacteriaceae ตามมาห่าง ๆ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17133818","locator":"Vol 69, issue 11, pages 2729-37 (abstract, opening statement and results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Proteolytic pseudomonads dominate the spoilage flora of aerobically chill-stored proteinaceous raw foods. ... Pseudomonads dominated the psychrotrophic flora, followed distantly by members of the Enterobacteriaceae."}}]},"milk-meat-hygiene--meat-microbiology--หลักการควบคุมจุลินทรีย์บนเนื้อสัตว์":{"claims":[{"id":"milk-meat-hygiene--meat-microbiology--หลักการควบคุมจุลินทรีย์บนเนื้อสัตว์--v1","statement":"เชื้อกลุ่มที่ทำให้เนื้อเน่าเสียจริง (specific/ephemeral spoilage organisms) ถูกกำหนดโดยปัจจัยที่เกิดขึ้นระหว่างการแปรรูป การขนส่ง และการเก็บรักษา จึงเป็นเหตุผลที่การควบคุมสุขอนามัยในกระบวนการและอุณหภูมิการเก็บคือหัวใจของการควบคุมจุลินทรีย์บนเนื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22062098","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These ESO are the consequence of factors that dynamically persist or imposed during, e.g., processing, transportation and storage in the market."}}]},"milk-meat-hygiene--meat-microbiology--เชื้อเด่นตามสภาวะการเก็บ":{"claims":[{"id":"milk-meat-hygiene--meat-microbiology--เชื้อเด่นตามสภาวะการเก็บ--v1","statement":"Pseudomonads ที่สร้างเอนไซม์ย่อยโปรตีนเป็นเชื้อเด่นของ spoilage flora ในอาหารดิบที่มีโปรตีนสูงซึ่งเก็บแบบ aerobic ที่อุณหภูมิเย็น รวมทั้งเนื้อบด เนื้อไก่ ปลา และน้ำนมดิบ ตรงกับที่สไลด์ระบุว่า Pseudomonas spp. คือสาเหตุสำคัญที่สุดของ aerobic spoilage บน chilled meat","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17133818","locator":"Abstract, opening sentence","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Proteolytic pseudomonads dominate the spoilage flora of aerobically chill-stored proteinaceous raw foods."}},{"id":"milk-meat-hygiene--meat-microbiology--เชื้อเด่นตามสภาวะการเก็บ--v2","statement":"ในเนื้อบรรจุสุญญากาศที่เก็บเย็น Clostridium spp. มี spoilage potential สูงที่สุดในบรรดาเชื้อที่ทดสอบ และเป็นตัวขับการเสื่อมคุณภาพ โดย C. estertheticum ทำให้เกิด blown pack spoilage สอดคล้องกับที่สไลด์จัด Clostridium เป็นตัวการของ deep spoilage","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35953182","locator":"Abstract, results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Among all test organisms, Clostridium spp. had the highest spoilage potential and had a major effect on the spoilage rate of VP lamb (based on sensory assessment). C. estertheticum caused premature 'blown pack' spoilage"}},{"id":"milk-meat-hygiene--meat-microbiology--เชื้อเด่นตามสภาวะการเก็บ--v3","statement":"ในเนื้อโคบรรจุสุญญากาศเก็บที่ 2 ถึง 7 องศาเซลเซียส กลุ่มเชื้อที่ตรวจติดตามคือ lactic acid bacteria, Clostridium spp. และ Brochothrix thermosphacta ร่วมกับ Pseudomonas และ Enterobacteriaceae ซึ่งยืนยันว่า LAB และ Brochothrix เป็นสมาชิกหลักของ microflora ในเนื้อบรรจุสุญญากาศ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27886641","locator":"Abstract, methods and results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Samples were taken periodically and tested for total viable count mesophilic (TVCm), TVC psychrophilic (TVCp), total Enterobacteriaceae count (TEC), presumptive Pseudomonas spp., lactic acid bacteria (LAB), Clostridium spp. and Brochothrix "}}]},"milk-meat-hygiene--meat-microbiology--คำตอบข้อเขียนที่รุ่นก่อนบันทึกไว้":{"claims":[{"id":"milk-meat-hygiene--meat-microbiology--คำตอบข้อเขียนที่รุ่นก่อนบันทึกไว้--v1","statement":"ปัจจัยความเครียดก่อนฆ่าและการจัดการหลังฆ่าในระยะแรก เช่น อัตราการลดอุณหภูมิซาก ทำให้เกิด protein denaturation ตั้งแต่ระยะต้นหลังตาย ส่งผลให้ water-holding capacity ต่ำและเนื้อสัมผัสด้อยลง ซึ่งเป็นกลไกของภาวะ PSE ในเนื้อสุกร","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22062597","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Some of these factors are known to cause protein denaturation at the early stage of postmortem and directly contribute to poor water-holding capacity and inferior texture in fresh meat and later in processed products."}}]},"milk-meat-hygiene--meat-microbiology--เกณฑ์จุลชีววิทยาของกรมปศุสัตว์-dld":{"claims":[{"id":"milk-meat-hygiene--meat-microbiology--เกณฑ์จุลชีววิทยาของกรมปศุสัตว์-dld--v1","statement":"ประกาศกรมปศุสัตว์ เรื่อง เกณฑ์ด้านจุลชีววิทยาของสินค้าปศุสัตว์เพื่อการส่งออก กำหนดว่าตัวอย่างเนื้อสัตว์ต้องตรวจไม่พบ Salmonella spp. ในตัวอย่าง 25 กรัม จึงถือว่าไม่ปนเปื้อน และกำหนด S. aureus ไม่เกิน 100 cfu/g ซึ่งตรงกับตัวเลขในสไลด์ทั้งสองค่า","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2551","locator":"เกณฑ์ Microbiological Guideline for Chilled/Frozen Meat & Poultry Meat; ข้อความเกณฑ์ถูกอ้างคำต่อคำในเอกสารวิชาการกรมปศุสัตว์เขต 6 (ดำรงศักดิ์ ทาทอง และคณะ) หน้าวิธีการศึกษา","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ตัวอย่างเนื้อสัตว์ ตรวจวิเคราะห์เชื้อ Salmonella spp. ไม่พบในตัวอย่าง 25 กรัม ถือว่า ไม่ปนเปื้อน"}},{"id":"milk-meat-hygiene--meat-microbiology--เกณฑ์จุลชีววิทยาของกรมปศุสัตว์-dld--v2","statement":"รายการพารามิเตอร์ที่เกณฑ์ด้านจุลชีววิทยาของเนื้อสัตว์แช่เย็นและแช่แข็งของกรมปศุสัตว์กำหนด ได้แก่ จำนวนจุลินทรีย์ทั้งหมด, Salmonella spp., Staphylococcus aureus, Coliforms, Enterococcus spp. และ E. coli ซึ่งตรงกับชุดพารามิเตอร์ของเนื้อดิบในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide---2551","locator":"Microbiological Guideline for Chilled/Frozen Meat & Poultry Meat; อ้างในบทนำของเอกสารวิชาการกรมปศุสัตว์เขต 6","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ได้แก่ จำนวนจุลินทรีย์ทั้งหมด Salmonella spp., Staphylococcus aureus, Coliforms Enterococcus spp. และ E. coli"}}]}},"milk-meat-hygiene--meat-storage":{"milk-meat-hygiene--meat-storage--factors-affecting-microorganisms-in-meat":{"claims":[{"id":"milk-meat-hygiene--meat-storage--factors-affecting-microorganisms-in-meat--v1","statement":"อุณหภูมิเก็บรักษาเป็น extrinsic factor ที่กำหนดชนิดจุลินทรีย์ในเนื้อ โดยเนื้อหมูที่เก็บ -2°C กับ 4°C มี bacterial community คล้ายกันมาก แต่ที่ 10°C ทั้ง psychrophilic และ mesophilic bacteria ขึ้นได้ และองค์ประกอบใกล้เคียงกับเนื้อที่เก็บอุณหภูมิห้อง (25°C)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35954075","locator":"Foods 2022;11(15):2307","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The microbial composition exhibited high similarity between pork meat stored at -2 °C and 4 °C"}},{"id":"milk-meat-hygiene--meat-storage--factors-affecting-microorganisms-in-meat--v2","statement":"บรรยากาศรอบเนื้อ (gas atmosphere/packaging) เป็น extrinsic factor ที่กำหนดกลุ่มจุลินทรีย์เด่น โดยซากโคที่เก็บ 0°C แบบ aerobic มี Pseudomonas spp. เป็นกลุ่มเด่น ส่วนแบบ vacuum (anaerobic) มี Serratia spp. เป็นกลุ่มเด่น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34416953","locator":"Food Microbiol 2021;100:103849","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The predominant group was Pseudomonas spp. under aerobic conditions and Serratia spp. under anaerobic conditions."}}]},"milk-meat-hygiene--meat-storage--specific-storage-methods-chilling-freezing-map-curing-drying":{"claims":[{"id":"milk-meat-hygiene--meat-storage--specific-storage-methods-chilling-freezing-map-curing-drying--v1","statement":"ในเนื้อแดงแช่เย็นที่เก็บแบบ aerobic จุลินทรีย์หลักที่ทำให้เกิด spoilage คือ psychrotrophic Pseudomonas species ซึ่งทนสภาวะเครียดได้ดีกว่าจุลินทรีย์ psychrotroph กลุ่มอื่น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33336914","locator":"Compr Rev Food Sci Food Saf 2019;18(5):1622-1635","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Psychrotrophic Pseudomonas species are the key microorganisms that cause spoilage in aerobically stored chilled meat."}},{"id":"milk-meat-hygiene--meat-storage--specific-storage-methods-chilling-freezing-map-curing-drying--v2","statement":"MAP ยับยั้ง total aerobic bacteria และ lactic acid bacteria ในเนื้อโคบรรจุกล่องที่เก็บและขนส่งที่ 4±2°C ได้ดีกว่า vacuum packaging","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31333861","locator":"J Anim Sci Technol 2019;61(1):47-53","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"MAP was more effective than vacuum packaging for the inhibition of total aerobic, lactic acid bacteria"}},{"id":"milk-meat-hygiene--meat-storage--specific-storage-methods-chilling-freezing-map-curing-drying--v3","statement":"Codex ใช้ -18°C เป็นอุณหภูมิอ้างอิงของ quick frozen food โดยต้องรักษา product temperature ที่ -18°C หรือต่ำกว่า ตลอด cold chain ทั้งห้องเย็น การขนส่ง และตู้แช่ ณ จุดขายปลีก","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-1976","locator":"CXC 8-1976 (adopted 1976; revised 1978, 1983, 2008). Frozen storage, transport and retail provisions. Exact clause numbering of the adopted 2008 revision was NOT verified.","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"maintain a product temperature of -18°C or lower with a minimum of fluctuation"}},{"id":"milk-meat-hygiene--meat-storage--specific-storage-methods-chilling-freezing-map-curing-drying--v4","statement":"Nitrite ถูกใช้ควบคุม Clostridium botulinum ในผลิตภัณฑ์เนื้อหมักมาแต่เดิม แต่ใน dry fermented sausage ปัจจัย pH, aw และ competitive microbiota อาจมีบทบาทมากกว่า nitrite โดยการศึกษาแบบ challenge test ตรวจไม่พบ botulinum neurotoxin แม้ในสูตรที่ไม่ใส่ nitrate/nitrite เลย เมื่อ pH ลดต่ำกว่า 5.0-5.2 และ aw ลดจาก 0.96 เหลือ 0.88-0.90","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26619314","locator":"Int J Food Microbiol 2016;218:66-70","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Botulinum neurotoxin was not detected in any of the sausages, including those manufactured without nitrate and nitrite."}}]},"milk-meat-hygiene--meat-storage--what-to-think-when-designing-storage-6-dimensions":{"claims":[{"id":"milk-meat-hygiene--meat-storage--what-to-think-when-designing-storage-6-dimensions--v1","statement":"การเลือกวิธีเก็บรักษาต้องชั่งน้ำหนักระหว่าง safety กับ meat quality พร้อมกัน เพราะสภาวะที่คุมการเจริญของจุลินทรีย์ได้ดีที่สุดอาจให้คุณภาพด้านสีแย่กว่า โดย MAP 100% CO2 ยืดอายุการเก็บได้ประมาณ 7 วันเทียบกับ vacuum แต่ vacuum กลับให้สีที่น่าพอใจกว่า แลกกับ weight loss ที่สูงกว่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27376249","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The HC atmosphere inhibited microbial growth and delayed changes in the microbial community composition, extending the lamb's shelf life by approximately 7days compared with the VP atmosphere. Lamb packaged in the VP atmosphere had a more d"}}]}},"milk-meat-hygiene--meat-quality":{"milk-meat-hygiene--meat-quality--definition-of-fresh-meat":{"claims":[{"id":"milk-meat-hygiene--meat-quality--definition-of-fresh-meat--v1","statement":"Codex Code of Hygienic Practice for Meat นิยาม fresh meat ว่าเป็นเนื้อที่นอกจาก refrigeration แล้ว ไม่ได้ผ่านการ treat เพื่อการถนอมอาหารด้วยวิธีอื่นนอกจาก protective packaging และยังคง natural characteristics ไว้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2005","locator":"CXC 58-2005 (CAC/RCP 58-2005), Section 3 Definitions, paragraph 13 (page 5 of 52)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Meat that apart from refrigeration has not been treated for the purpose of preservation other than through protective packaging"}}]},"milk-meat-hygiene--meat-quality--properties-of-meat-4-key-attributes":{"claims":[{"id":"milk-meat-hygiene--meat-quality--properties-of-meat-4-key-attributes--v1","statement":"Myoglobin เป็น sarcoplasmic heme protein ที่กำหนดสีของเนื้อเป็นหลัก และ chemistry ของ myoglobin เป็น species specific โดยผู้บริโภคใช้สีของเนื้อสดเป็นตัวชี้วัด wholesomeness ณ จุดขาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23190143","locator":"Annu Rev Food Sci Technol 2013;4:79-99","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Myoglobin is the sarcoplasmic heme protein primarily responsible for the meat color, and the chemistry of myoglobin is species specific."}},{"id":"milk-meat-hygiene--meat-quality--properties-of-meat-4-key-attributes--v2","statement":"สีเนื้อขึ้นกับ redox state ของ myoglobin โดยการรีดิวซ์ metmyoglobin กลับไปเป็น oxymyoglobin ทำให้สีเนื้อเปลี่ยนจากสีน้ำตาลเป็นสีแดงสด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25221843","locator":"J Agric Food Chem 2014;62(39):9472-8","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The reduction of MetMb to MbO2 changes the color of meat from brown to the more desirable bright red."}},{"id":"milk-meat-hygiene--meat-quality--properties-of-meat-4-key-attributes--v3","statement":"μ-calpain (micro-calpain) เป็นเอนไซม์หลักที่รับผิดชอบ postmortem proteolysis ของโปรตีนกล้ามเนื้อ ซึ่งเป็นกลไกของ meat tenderization ระหว่างการบ่มเนื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16971586","locator":"J Anim Sci 2006;84(10):2834-40","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"micro-calpain is largely responsible for postmortem proteolysis of muscle proteins"}}]},"milk-meat-hygiene--meat-quality--quality-defects-wholesomeness-criteria-detail":{"claims":[{"id":"milk-meat-hygiene--meat-quality--quality-defects-wholesomeness-criteria-detail--v1","statement":"PSE pork สัมพันธ์กับ recessive halothane allele ซึ่งทำให้ Ca release channel / ryanodine receptor (RYR1) ที่ sarcoplasmic reticulum ผิดปกติ ปล่อย Ca2+ ออกมาไม่หยุดเมื่อสัตว์เจอ stress ก่อนฆ่า ทำให้ pH ของกล้ามเนื้อลดลงอย่างรวดเร็วหลังฆ่า เกิดเนื้อ pale, soft, exudative ที่ WHC ต่ำและ drip loss สูง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27854153","locator":"Anim Biotechnol 2017;28(2):148-155","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Abnormal lactic acid metabolism caused by stress prior to slaughter leads to the sudden drop in postmortem muscle pH producing the PSE pork."}},{"id":"milk-meat-hygiene--meat-quality--quality-defects-wholesomeness-criteria-detail--v2","statement":"Dark cutting beef แบบ classic (DFD) จัดกลุ่มด้วย ultimate pH ของ longissimus thoracis มากกว่า 6.0 และมี lactate กับ glucidic potential ต่ำที่สุด สีเข้ม รวมทั้ง purge, drip loss และ cooking loss ลดลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25173716","locator":"Meat Sci 2014;98(4):842-9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ten B4 with LT pH>6.0 (CL, classic), and ten B4 with LT pH<6.0 (AT, atypical)"}}]}},"milk-meat-hygiene--meat-molecular":{"milk-meat-hygiene--meat-molecular--applications-species-id-authentication-adulteration-qpcr":{"claims":[{"id":"milk-meat-hygiene--meat-molecular--applications-species-id-authentication-adulteration-qpcr--v1","statement":"Cytochrome c oxidase subunit I (COI) เป็นบริเวณ DNA ที่นิยมใช้เป็น barcode มากที่สุดสำหรับ species identification ในสัตว์ รวมทั้งปลาและ shellfish โดย DNA barcoding ที่อาศัย Sanger sequencing เป็นวิธีที่ใช้มากที่สุดในการพิสูจน์ชนิดของ seafood","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32838560","locator":"Crit Rev Food Sci Nutr 2021;61(22):3904-3935","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Cytochrome c oxidase subunit I (COI) gene has been the preferential targeted DNA region in animal species identification"}},{"id":"milk-meat-hygiene--meat-molecular--applications-species-id-authentication-adulteration-qpcr--v2","statement":"การตรวจชนิดสัตว์ในผลิตภัณฑ์เนื้อแปรรูปควรใช้ amplicon สั้นและจับหลายยีน โดย multiplex PCR-RFLP ที่จับยีนไมโทคอนเดรีย cytochrome b และ ND5 ด้วย target ขนาด 73-146 bp ยังคงตรวจได้แม้ตัวอย่างผ่าน boiling และ autoclaving","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27501408","locator":"J Agric Food Chem 2016;64(32):6343-54","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"all targets (73, 90, 106, 120, 138, and 146 bp) were stable under extreme boiling and autoclaving treatments"}},{"id":"milk-meat-hygiene--meat-molecular--applications-species-id-authentication-adulteration-qpcr--v3","statement":"Real-time PCR ที่ใช้ primer จำเพาะสุกรจับยีน cytochrome b ซึ่งเป็น multi-copy target ใช้พิสูจน์ Halal/Kosher ของ gelatine ได้ โดยระดับการปลอมปนต่ำสุดที่ตรวจพบคือ 1.0% w/w ใน marshmallow และ gum drop","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22098822","locator":"Meat Sci 2012;90(3):686-9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The minimum level of adulteration that could be detected was 1.0% w/w for marshmallows and gum drops."}},{"id":"milk-meat-hygiene--meat-molecular--applications-species-id-authentication-adulteration-qpcr--v4","statement":"PCR-RFLP ที่ขยายชิ้นส่วนยีน cytochrome b แล้วตัดด้วย restriction enzyme AluI ใช้แยกเนื้อลาออกจากเนื้อม้าได้ และเมื่อสำรวจผลิตภัณฑ์เนื้อ 224 ตัวอย่างในอิหร่านพบเนื้อ haram รวม 7.58% ของตัวอย่างทั้งหมด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24426061","locator":"J Food Sci Technol 2014;51(1):148-52","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the mitochondrial DNA segment (cytochrome-b gene) was amplified and products were digested with AluI restriction enzyme"}},{"id":"milk-meat-hygiene--meat-molecular--applications-species-id-authentication-adulteration-qpcr--v5","statement":"Limit of detection ของการตรวจ porcine DNA ใน gelatine ต่างกันมากตามวิธีสกัด DNA และชุดตรวจที่ใช้ โดยวิธีที่พัฒนาขึ้น (TübiGel) ตรวจได้ที่ 0.01% porcine gelatin ขณะที่ชุดตรวจการค้าสองชุดตรวจได้ที่ 0.1% และมากกว่า 5% ตามลำดับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33818304","locator":"Food Addit Contam Part A Chem Anal Control Expo Risk Assess 2021;38(6):881-891","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"detection limit of 0.01% porcine gelatin, whilst the Biotecon method had 0.1% and R-Biopharm method detected >5%"}}]},"milk-meat-hygiene--meat-molecular--what-is-molecular-biology-technique":{"claims":[{"id":"milk-meat-hygiene--meat-molecular--what-is-molecular-biology-technique--v1","statement":"ในงาน meat science เทคนิคระดับโมเลกุลหมายถึงวิธีที่วัดโมเลกุล DNA หรือโปรตีนโดยตรง และปัจจุบันวิธี DNA-based ได้เข้ามาแทนที่วิธีเดิม (anatomical, histological, chemical, electrophoretic, immunological) เป็นส่วนใหญ่ เพราะมี specificity และ sensitivity สูงกว่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24915324","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"However, by virtue of their inherent limitations, most of these techniques have been replaced by the recent DNA-based molecular techniques."}},{"id":"milk-meat-hygiene--meat-molecular--what-is-molecular-biology-technique--v2","statement":"วิธีวิเคราะห์เพื่อระบุชนิดสัตว์ในเนื้อแบ่งตามโมเลกุลเป้าหมายได้เป็น protein-based กับ DNA-based โดย protein-based (electrophoretic, immunological) มักแยกสปีชีส์ที่ใกล้ชิดกันได้ไม่ดี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32380410","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Various analytical methods often based on protein or DNA measurements are utilized to identify meat species. Protein-based methods, including electrophoretic and immunological techniques, are at times unsuitable for discriminating closely r"}}]},"milk-meat-hygiene--meat-molecular--genomic-techniques-combination-of-4-sub-disciplines":{"claims":[{"id":"milk-meat-hygiene--meat-molecular--genomic-techniques-combination-of-4-sub-disciplines--v1","statement":"งาน genomics ในปศุสัตว์เป็นการทำงานร่วมกันของหลายสาขาจริง คือ genome sequencing และ assembly ร่วมกับ bioinformatics, การคัดเลือกลักษณะเชิงปริมาณ (quantitative production traits) และการกำจัด deleterious recessive variant ซึ่งเป็นงานฝั่ง Mendelian genetics","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32331872","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The cattle reference genome assembly has underpinned major innovations in beef and dairy genetics through genome-enabled selection, including removal of deleterious recessive variants and selection for favorable alleles affecting quantitati"}}]}},"milk-meat-hygiene--meat-slaughter":{"milk-meat-hygiene--meat-slaughter--layout-zoning-water-consumption-waste-handling-detail":{"claims":[{"id":"milk-meat-hygiene--meat-slaughter--layout-zoning-water-consumption-waste-handling-detail--v1","statement":"หนัง (hide) ของโคคือแหล่งหลักของการปนเปื้อนซากระหว่างกระบวนการชำแหละ และการขนส่ง + การพักใน lairage ทำให้ความชุกของ Escherichia coli O157:H7 บนหนังเพิ่มจาก 50.3% ตอนขึ้นรถที่ feedlot เป็น 94.4% ตอนถลกหนังในโรงฆ่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17340859","locator":"70(2):280-6","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Hide has been established as the main source of carcass contamination during cattle processing... The prevalence of E. coli O157:H7 on hides increased from 50.3 to 94.4% between the time cattle were loaded onto tractor-trailers at the feedl"}},{"id":"milk-meat-hygiene--meat-slaughter--layout-zoning-water-consumption-waste-handling-detail--v2","statement":"ความชุกของ EHEC O157 บนซากโคลดลงตามลำดับขั้นของสายการผลิต คือ 43% ที่ pre-evisceration, 18% ที่ post-evisceration (ก่อน antimicrobial intervention) และ 2% หลังซากเข้าห้องเย็น แสดงว่า sanitary procedure ในสายการผลิตลดการปนเปื้อนได้จริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10725380","locator":"97(7):2999-3003","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Carcass samples were taken at three points during processing: preevisceration, postevisceration before antimicrobial intervention, and postprocessing after carcasses entered the cooler... Prevalence of EHEC O157 in the three postprocessing"}},{"id":"milk-meat-hygiene--meat-slaughter--layout-zoning-water-consumption-waste-handling-detail--v3","statement":"ในสายการฆ่าสุกร ขั้นตอน scalding, singeing และ chilling ลดจำนวนจุลินทรีย์บนซาก ส่วน dehairing และ polishing ทำให้การปนเปื้อนเพิ่มขึ้นอย่างมีนัยสำคัญ จึงเสนอให้ scalding, singeing และ chilling เป็นจุดที่รวมเข้าในระบบ HACCP","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17133797","locator":"69(11):2568-75","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"mean TVCs and the percentage of Enterobacteriaceae-positive carcasses were reduced (P < 0.05) after scalding (1.9 log CFU cm(-2) and 12%, respectively), singeing (1.9 log CFU cm(-2) and 66%, respectively), and blast chilling (2.3 log CFU cm"}},{"id":"milk-meat-hygiene--meat-slaughter--layout-zoning-water-consumption-waste-handling-detail--v4","statement":"คอกพักสัตว์ (lairage) เป็นแหล่งสำคัญของการปนเปื้อน Salmonella บนซากสุกร โดย serotype และ MLVA/PFGE profile ที่พบบนซากมักเชื่อมโยงกับ holding pen มากกว่าที่พบจาก caecum content หรือ lymph node ของตัวสัตว์เอง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23261811","locator":"161(1):44-52","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The Salmonella serotypes identified on the carcasses of the 16 tracked batches were frequently linked to lairage, whereas the serotypes detected at the farm, transport or pig-related samples (i.e., caecum content and lymph nodes) were only"}}]},"milk-meat-hygiene--meat-slaughter--slaughterhouse-abattoir-definition-5-design-factors":{"claims":[{"id":"milk-meat-hygiene--meat-slaughter--slaughterhouse-abattoir-definition-5-design-factors--v1","statement":"โรงฆ่าสัตว์ (slaughterhouse หรือ abattoir) หมายถึงสถานที่ที่ใช้ฆ่าและชำแหละสัตว์ซึ่งเนื้อนั้นมีจุดประสงค์เพื่อการบริโภคของมนุษย์ ซึ่งเป็นนิยามตามหลักปฏิบัติสากลด้านสุขลักษณะเนื้อสัตว์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2005","locator":"Definitions section. I could not verify the clause number against the current edition, so none is given rather than guessed.","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":""}},{"id":"milk-meat-hygiene--meat-slaughter--slaughterhouse-abattoir-definition-5-design-factors--v2","statement":"วิธีปฏิบัติระหว่างการถลกหนังและควักไส้ (the practice to be followed) เป็นตัวกำหนดการปนเปื้อนจุลินทรีย์ของซากได้มากกว่าการล้างหรือทำความสะอาดสัตว์และซากภายหลัง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-14968981","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"of the various actions that can be taken to obtain carcasses that are free of visible contamination, only minimizing the visible contamination of meat during skinning and eviscerating operations may also ensure a degree of control over the "}}]},"milk-meat-hygiene--meat-slaughter--location-requirements":{"claims":[{"id":"milk-meat-hygiene--meat-slaughter--location-requirements--v1","statement":"สถานที่ผลิตอาหารรวมถึงโรงฆ่าสัตว์ต้องตั้งอยู่ห่างจากพื้นที่ที่มีมลพิษหรือพื้นที่เสี่ยงต่อการปนเปื้อน และต้องมีน้ำสะอาดเพียงพอพร้อมระบบระบายน้ำและกำจัดของเสียที่ใช้ได้จริง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2020","locator":"Chapter on Good Hygiene Practices, sections on establishment design and facilities (water supply, drainage and waste disposal). Section numbers changed in the 2020 revision and I did not re-verify them, so none is quoted.","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":""}}]}},"milk-meat-hygiene--meat-ante-post-mortem":{"milk-meat-hygiene--meat-ante-post-mortem--am-pm-lesion-judgement-table-per-organ-disposition":{"claims":[{"id":"milk-meat-hygiene--meat-ante-post-mortem--am-pm-lesion-judgement-table-per-organ-disposition--v1","statement":"Routine abattoir meat inspection ตรวจจับซากที่ติด Mycobacterium bovis ได้เพียงส่วนน้อย โดยมี sensitivity 28.2% เมื่อเทียบกับ detailed abattoir inspection และ 55.2% เมื่อเทียบกับ culture + microscopy ทำให้พลาดซากที่มีรอยโรค TB ถึง 71.8%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20691081","locator":"10:462","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The sensitivity (Sn) and specificity (Sp) of RA inspection were 28.2% (95/337) [95%CI: 23.4-33.0] and 99.3% (2963/2985) [95%CI: 99.0-99.6], respectively, when DA inspection was considered as reference test. When culture and microscopy (CM)"}},{"id":"milk-meat-hygiene--meat-ante-post-mortem--am-pm-lesion-judgement-table-per-organ-disposition--v2","statement":"รอยโรค tuberculosis ในโคที่ตรวจพบตอน postmortem อยู่ที่ปอดและ lymph node ที่เกี่ยวข้องประมาณ 59% และ lymph node ของหัวประมาณ 35% จึงเป็นตำแหน่งที่ต้องกรีดตรวจเป็นหลัก และ routine inspection มี sensitivity เพียง 23.8% เทียบกับ detailed inspection","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23080340","locator":"45(3):855-64","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"About 59.45 % of tuberculous lesions were observed in the lungs and associated lymph nodes, whereas 35.13 % lesions were from the lymph nodes of the head... The sensitivity of RA meat inspection was 23.8 % in comparison to the detailed abat"}},{"id":"milk-meat-hygiene--meat-ante-post-mortem--am-pm-lesion-judgement-table-per-organ-disposition--v3","statement":"Routine meat inspection มี sensitivity ต่ำมากต่อ bovine cysticercosis โดยแบบจำลอง scenario-analysis ของเบลเยียมประเมิน sensitivity ของ meat inspection สำหรับ cysticerci ทั้งที่ยังมีชีวิตและที่เสื่อมสภาพไว้เพียง 0.54% (95% CI 0.37-0.71%) เทียบกับความชุกจริงที่ประเมินได้ 42.5%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30466649","locator":"161:1-8","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The model estimated the current prevalence of BCC to be 42.5% (95% CI: 32.4-60.7%) and the sensitivity of the MI for viable and degenerated cysticerci at only 0.54% (95% CI: 0.37-0.71%)."}},{"id":"milk-meat-hygiene--meat-ante-post-mortem--am-pm-lesion-judgement-table-per-organ-disposition--v4","statement":"ในโคขุนที่ตรวจ postmortem แบบ routine พบ Cysticercus bovis บ่อยที่สุดที่หัวใจ รองลงมาคือตับและกล้ามเนื้อ masseter และ postmortem inspection มี sensitivity 52.4% เมื่อเทียบกับ stereoscopic microscopy เป็น gold standard","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25803448","locator":"12(5):462-5","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The sensitivity of the postmortem inspection, when compared to a gold standard of stereoscopic microscopy, was 52.4%... Cysticerci were most frequently found in the heart, followed by liver and masseter muscles."}}]},"milk-meat-hygiene--meat-ante-post-mortem--general-principles-am-vs-pm":{"claims":[{"id":"milk-meat-hygiene--meat-ante-post-mortem--general-principles-am-vs-pm--v1","statement":"การตรวจซากสุกรในสหภาพยุโรปเปลี่ยนเป็น visual inspection อย่างเดียวตาม Regulation (EU) No 219/2014 เพราะการ palpation และ incision อาจทำให้เกิด cross-contamination และแพร่ zoonotic agent แต่การตัด palpation/incision ออกทำให้การตรวจพบรอยโรคตับลดลง 59% และรอยโรคปอดลดลง 38.5%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36590018","locator":"11(4):10761","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"According to Regulation (EU) No 219/2014, pig carcasses inspection is exclusively visual as palpation and incision could lead to cross-contamination and spread of relevant zoonotic agents... Carcasses undergone the only visual inspection ha"}},{"id":"milk-meat-hygiene--meat-ante-post-mortem--general-principles-am-vs-pm--v2","statement":"Abattoir surveillance สำหรับ bovine tuberculosis มี herd-level detection sensitivity ต่ำ โดยแบบจำลองในไอร์แลนด์ประเมินไว้เฉลี่ย 0.24 ภายใต้ current meat inspection และลดเหลือ 0.16 ถึง 0.08 หากเปลี่ยนไปใช้ visual-only inspection","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29876359","locator":"5:82","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The simulated mean herd-level detection sensitivity estimates were 0.24 for CMI, and 0.16, 0.12, 0.10 and 0.08 for VOI2-5, assuming a 2-, 3-, 4- and 5-fold decrease, respectively, in the animal-level detection sensitivity of VOI relative to"}}]},"milk-meat-hygiene--meat-ante-post-mortem--meat-inspection-objectives":{"claims":[{"id":"milk-meat-hygiene--meat-ante-post-mortem--meat-inspection-objectives--v1","statement":"วัตถุประสงค์ของ meat inspection ในโรงฆ่าสัตว์คือการรับประกันความปลอดภัยของเนื้อเพื่อคุ้มครองสุขภาพผู้บริโภค และเป็นเครื่องมือสำคัญในการควบคุมโรคสัตว์ไปพร้อมกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36851472","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"From the point of public health, the objective of the slaughterhouse is to guarantee the safety of meat in which meat inspection represent an essential tool to control animal diseases and guarantee the public health."}},{"id":"milk-meat-hygiene--meat-ante-post-mortem--meat-inspection-objectives--v2","statement":"AM inspection ตรวจจับความผิดปกติของสัตว์ก่อนฆ่าได้จริง (ผิวหนังสกปรก 69.1%, BCS ต่ำ 24.3%, น้ำมูก 19.5%) และ PM inspection ตรวจพบรอยโรคในอวัยวะ (ตับ 39.7%, ปอด 37.2%) จึงเป็นสองขั้นที่ทำงานต่อเนื่องกันเพื่อคัดแยกสัตว์และซากที่ผิดปกติออกจากห่วงโซ่อาหาร","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38903683","locator":"Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Soiled skin (69.1%), poor body condition (24.3%), and nostril discharge (19.5%) were common among both species at ante-mortem examination. Gross lesions were frequent in livers (39.7%) and lungs (37.2%)"}},{"id":"milk-meat-hygiene--meat-ante-post-mortem--meat-inspection-objectives--v3","statement":"การตรวจก่อนฆ่า (ante-mortem) และหลังฆ่า (post-mortem) ร่วมกับการชำแหละอย่างถูกสุขลักษณะเพื่อให้ปนเปื้อนน้อยที่สุด เป็นข้อกำหนดตามหลักปฏิบัติสากลด้านสุขลักษณะเนื้อสัตว์ ไม่ใช่แค่แนวทางของผู้สอน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-codex-alimentarius-com-2005","locator":"Sections covering ante-mortem and post-mortem inspection and hygienic dressing. I did not re-verify the clause numbers against the current edition, so no clause number is given here.","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":""}}]}},"milk-meat-hygiene--meat-cutting-grading":{"milk-meat-hygiene--meat-cutting-grading--immobilization-exsanguination":{"claims":[{"id":"milk-meat-hygiene--meat-cutting-grading--immobilization-exsanguination--v1","statement":"การทำให้สลบด้วยไฟฟ้ามีผลต่อการเกิด blood splash (hemorrhage เข้าไปในเนื้อ) โดยวิธี head-back ลดอุบัติการณ์ blood splash ในซากลูกแกะได้ชัดเจนเมื่อเทียบกับวิธี head-only","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22054488","locator":"5(5):347-53","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The head-back stunning method markedly decreased the incidence of carcass blood splash in comparison with the splash observed in lambs stunned by the head application method."}}]},"milk-meat-hygiene--meat-cutting-grading--conversion-of-muscle-to-meat":{"claims":[{"id":"milk-meat-hygiene--meat-cutting-grading--conversion-of-muscle-to-meat--v1","statement":"สภาวะของสัตว์ก่อนฆ่ามีผลต่อคุณภาพเนื้อจริง โดยไก่เนื้อที่ถูกขนส่งภายใต้อุณหภูมิสิ่งแวดล้อมสูงเกิดเนื้อแบบ PSE-like ซึ่งมี glycolysis หลังฆ่าเร็วผิดปกติ ร่วมกับ phosphorylation ของ glycometabolic enzymes ที่สูงขึ้นในระยะ early postmortem","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32169763","locator":"319:126531","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Broiler chickens were randomly distributed to unstressed control and transport under high environmental temperature groups. PM muscle samples of transport-stressed broilers were classified into normal or pale, soft and exudative (PSE)-like."}}]},"milk-meat-hygiene--meat-cutting-grading--rigor-mortis-ageing-cutting-grading-detail":{"claims":[{"id":"milk-meat-hygiene--meat-cutting-grading--rigor-mortis-ageing-cutting-grading-detail--v1","statement":"การจำแนก DFD ในเนื้อโคใช้ ultimate pH ที่ 48 ชั่วโมงหลังฆ่า โดยเนื้อปกติมี pHu ต่ำกว่า 5.8, atypical DFD อยู่ระหว่าง 5.8 ถึง 6.0 และ typical DFD มี pHu ตั้งแต่ 6.0 ขึ้นไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38103397","locator":"209:109415","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The steaks were divided according to their pHu (normal pH < 5.8, atypical darkness, firmness, and dryness [DFD] > 5.8 pH < 6, and typical DFD pH ≥ 6)."}},{"id":"milk-meat-hygiene--meat-cutting-grading--rigor-mortis-ageing-cutting-grading-detail--v2","statement":"เนื้อโค normal pH มี ultimate pH ราว 5.47 ± 0.02 ส่วนซาก dark cutting มี ultimate pH สูงราว 6.69 ± 0.09 และ dark cutting steaks มีค่า lightness (L*), redness (a*) และ yellowness (b*) ต่ำที่สุดไม่ว่าจะ aging ด้วยวิธีใด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33223267","locator":"172:108365","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Strip loins from six normal pH carcasses (pH = 5.47 ± 0.02) and dark cutting (DC) strip loins from six high pH carcasses (pH = 6.69 ± 0.09) were obtained... In general, DC steaks had the lowest lightness (L*), redness (a*), and yellowness ("}},{"id":"milk-meat-hygiene--meat-cutting-grading--rigor-mortis-ageing-cutting-grading-detail--v3","statement":"การ ageing ทำให้เนื้อนุ่มขึ้นผ่าน proteolysis ของ myofibrillar protein (desmin, titin, filamin) โดย μ-calpain และอัตราการเกิดขึ้นกับ ultimate pH โดยในเนื้อ pHu สูง (≥ 6.2) μ-calpain เกิด autolysis เร็วกว่าและ titin กับ filamin ถูกย่อยเร็วกว่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24769876","locator":"97(4):548-57","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"bull LD (n = 94) were aged at -1.5°C for up to 28 days post mortem. μ-Calpain autolysed faster in high ultimate pH (pH(u)) meat (pH(u)≥6.2) and this was concomitant with the more rapid degradation of titin and filamin in this pH(u) group."}},{"id":"milk-meat-hygiene--meat-cutting-grading--rigor-mortis-ageing-cutting-grading-detail--v4","statement":"Porcine stress syndrome ซึ่งทำให้เกิดเนื้อ PSE สัมพันธ์กับ mutation C เป็น T ที่ base pair 1843 ของ skeletal muscle ryanodine receptor (ryr1) cDNA และการตรวจด้วย DNA-based assay ทำนาย genotype ทั้งแบบ homozygous และ heterozygous ได้แม่นยำกว่า halothane challenge test","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8392044","locator":"71(6):1395-9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The DNA-based assay for a C to T mutation at base pair 1,843 of the skeletal muscle ryanodine receptor (ryr1) cDNA, which is very highly correlated with PSS, was also determined for these animals... The results of this study indicate that t"}}]}},"milk-meat-hygiene--meat-pest-control":{"milk-meat-hygiene--meat-pest-control--problems-of-pest-3-main-impacts":{"claims":[{"id":"milk-meat-hygiene--meat-pest-control--problems-of-pest-3-main-impacts--v1","statement":"หนู (wild rats) ในเขตเมืองเป็น reservoir ของ pathogenic Leptospira และปล่อยเชื้อออกทางปัสสาวะ คนติดเชื้อจากการสัมผัสน้ำผิวดินหรือดินที่ปนเปื้อนปัสสาวะสัตว์ติดเชื้อ (ในหนูป่าเมือง Fukuoka เพาะเชื้อขึ้นจาก kidney 72.2% และจากปัสสาวะ 30.8%)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25890990","locator":"59(6):322-30","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"urban rats carry pathogenic leptospires and people acquire these pathogens through contact with surface water or soil contaminated by the urine of the infected animals"}},{"id":"milk-meat-hygiene--meat-pest-control--problems-of-pest-3-main-impacts--v2","statement":"Plague เป็น flea-borne zoonosis ที่เกิดจากแบคทีเรียแกรมลบ coccobacillus ชื่อ Yersinia pestis โดยตรวจพบ pla gene ของเชื้อได้ทั้งใน rodents, shrews และ fleas ในพื้นที่ระบาด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29433443","locator":"18(1):2","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Plague is a flea-borne zoonotic and invasive disease caused by a gram negative coccobacillus bacterium called Yersinia pestis. ... The plasminogen activator gene (pla gene) of Y. pestis was detected in 42.8% bubo aspirates, 6.9% rodents, 3."}},{"id":"milk-meat-hygiene--meat-pest-control--problems-of-pest-3-main-impacts--v3","statement":"Murine typhus (endemic typhus) เกิดจาก Rickettsia typhi ซึ่งมีหนู Rattus rattus และ Rattus norvegicus เป็น mammalian host และหมัดหนู Xenopsylla cheopis เป็น vector หลัก (ในการศึกษาที่ Kisangani พบ R. typhi ในหนู 13% และใน X. cheopis pools ถึง 72%)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24445202","locator":"90(3):463-8","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"An overall prevalence of 17% Bartonella species and 13% Rickettsia typhi, the agent of murine typhus, was found in the cosmopolitan rat species, Rattus rattus and Rattus norvegicus that were infested by a majority of Xenopsylla cheopis flea"}}]},"milk-meat-hygiene--meat-pest-control--types-of-pest-3-categories":{"claims":[{"id":"milk-meat-hygiene--meat-pest-control--types-of-pest-3-categories--v1","statement":"แมลงสาบเป็น carrier ของแบคทีเรียที่สำคัญทางการแพทย์ มีรายงานอย่างน้อย 78 bacterial species จาก 42 genera โดย Blattella germanica เป็นชนิดที่พบปนเปื้อนบ่อยที่สุดและมีความหลากหลายของเชื้อมากที่สุด รองลงมาคือ Periplaneta americana","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31219601","locator":"56(6):1534-1554","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At least 78 bacterial species and 42 genera from 24 families and 11 orders of bacteria were reported to have contaminated cockroaches. ... Blattella germanica is the most commonly contaminated cockroach species, with the widest bacterial sp"}},{"id":"milk-meat-hygiene--meat-pest-control--types-of-pest-3-categories--v2","statement":"แมลงวันบ้าน (Musca domestica) ที่กินอาหารปนเปื้อนสามารถส่งผ่าน foodborne pathogens ได้แก่ Salmonella enterica, Cronobacter sakazakii, Escherichia coli O157:H7 และ Listeria monocytogenes ไปยังไข่ของมัน และ S. enterica กับ C. sakazakii ยังถูกส่งต่อไปถึงตัวเต็มวัยรุ่น F1 โดยพบที่ผิวลำตัวมากกว่าในทางเดินอาหารประมาณ 2.4 เท่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26228457","locator":"15:150","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All foodborne pathogens were present in samples containing pooled house fly eggs. ... Only S. enterica and C. sakazakii were transmitted to F1 generation adults and their presence was 2.4 times more likely on their body surfaces than in the"}}]},"milk-meat-hygiene--meat-pest-control--control-methods-ipm-traps-baits-exclusion":{"claims":[{"id":"milk-meat-hygiene--meat-pest-control--control-methods-ipm-traps-baits-exclusion--v1","statement":"การควบคุมนกกิ้งโครง European starling (Sturnus vulgaris) ในฟาร์มโค ทำให้ตรวจไม่พบ Salmonella enterica ใน feed bunk และลดลงมากใน water trough แต่ไม่ได้ลด herd prevalence ในตัวโค ผู้วิจัยจึงสรุปว่าไม่ควรใช้การควบคุมนกเป็นมาตรการเดี่ยว แต่ควรเป็นส่วนหนึ่งของแผนควบคุมโรคแบบครอบคลุม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21324202","locator":"7:9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Within the starling-controlled CAFO, detections of S. enterica contamination disappeared from feed bunks and substantially declined within water troughs following starling control operations. ... Starling control was not observed to reduce"}}]}},"milk-meat-hygiene--meat-egg-micro":{"milk-meat-hygiene--meat-egg-micro--significance-of-microbe-with-egg":{"claims":[{"id":"milk-meat-hygiene--meat-egg-micro--significance-of-microbe-with-egg--v1","statement":"Salmonella enterica serovar Enteritidis เป็นเชื้อที่ทำให้เกิด egg-associated salmonellosis ในคน โดยในสหรัฐฯ การนำ egg quality assurance program (EQAP) มาใช้สัมพันธ์กับอุบัติการณ์ที่ลดลง คือไข่ที่ผลิตภายใต้ EQAP เพิ่มขึ้น 1% สัมพันธ์กับ S. Enteritidis incidence ลดลง 0.14% (p < 0.05)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15504264","locator":"10(10):1782-9","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Regression analysis showed that a 1% increase in the number of eggs produced under an EQAP was associated with a 0.14% decrease in S. Enteritidis incidence (p < 0.05). These data indicate that EQAPs probably played a major role in reducing"}}]},"milk-meat-hygiene--meat-egg-micro--egg-shell-structure-and-function":{"claims":[{"id":"milk-meat-hygiene--meat-egg-micro--egg-shell-structure-and-function--v1","statement":"ความหนาเปลือกไข่ พื้นที่เปลือก และจำนวนรู (pores) ไม่ใช่ปัจจัยที่กำหนดการ penetrate ของแบคทีเรียผ่านเปลือกไข่ แต่ cuticle deposition ต่างหากที่สัมพันธ์ โดยไข่ที่ถูก penetrate มี cuticle deposition เฉลี่ยต่ำกว่าไข่ที่ไม่ถูก penetrate และเชื้อแกรมลบที่เคลื่อนที่ได้ penetrate บ่อยที่สุด (Pseudomonas sp. 60%, Alcaligenes sp. 58%, S. Enteritidis 43%)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16822571","locator":"112(3):253-60","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The eggshell characteristics such as area eggshell, shell thickness and number of pores did not influence the bacterial eggshell penetration. For each individual bacterial strain the mean cuticle deposition was lower for penetrated compared"}}]},"milk-meat-hygiene--meat-egg-micro--egg-contamination-routes-salmonella-vertical-horizontal-processi":{"claims":[{"id":"milk-meat-hygiene--meat-egg-micro--egg-contamination-routes-salmonella-vertical-horizontal-processi--v1","statement":"Vertical transmission ของ Salmonella Enteritidis สู่ไข่เกิดจากการที่เชื้อ colonize ที่ ovary และ oviduct ของแม่ไก่ไข่ ซึ่งเป็นตำแหน่งหลักของการติดเชื้อในระบบสืบพันธุ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-14676008","locator":"32(6):583-90","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The ovaries and the oviducts of the laying hens are the major sites of SE colonization from which vertical transmission to eggs occurs."}},{"id":"milk-meat-hygiene--meat-egg-micro--egg-contamination-routes-salmonella-vertical-horizontal-processi--v2","statement":"S. Enteritidis penetrate ผ่านเปลือกไข่ได้จริง (horizontal หรือ trans-shell route) โดยหลังเก็บ 14 วันที่ 20 องศาเซลเซียส ความชื้นสัมพัทธ์ 60% พบการ penetrate 6.0% ในไข่ free-range และ 16.0% ในไข่ขาว generic แต่สูงถึง 30-34% ในไข่ generic brown, organic และ omega-3 และพบบ่อยขึ้นเมื่อไม่มี cuticle spots","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17388050","locator":"70(3):623-8","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At 14 days of storage, only 6.0% of the eggs from free-range hens and 16.0% of the generic (i.e., eggs from hens in conventional battery cages that were given standard feed) white eggs were penetrated. The generic brown, organic, and omega-"}},{"id":"milk-meat-hygiene--meat-egg-micro--egg-contamination-routes-salmonella-vertical-horizontal-processi--v3","statement":"USDA FSIS กำหนดให้ liquid egg white (LEW) ต้องผ่าน pasteurization ที่ 56.7 องศาเซลเซียส นาน 3.5 นาที","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22410216","locator":"75(3):443-8","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The U.S. Department of Agriculture, Food Safety and Inspection Service (FSIS) requires that liquid egg white (LEW) be pasteurized at 56.7 degrees C for 3.5 min."}},{"id":"milk-meat-hygiene--meat-egg-micro--egg-contamination-routes-salmonella-vertical-horizontal-processi--v4","statement":"Haugh unit (HU) เป็นค่าวัด internal egg quality ที่ได้จากการวัด albumen height ค่าจะลดลงเมื่อเก็บนานขึ้น (เฉลี่ย 72.44 ที่เวลาเริ่มต้น เหลือ 59.99 ที่ 7 สัปดาห์) และขึ้นกับอุณหภูมิขณะวัดด้วย โดยที่ 7 สัปดาห์ HU ลดลงประมาณ 6 หน่วยเมื่ออุณหภูมิทดสอบสูงขึ้น จึงควรรายงานอุณหภูมิที่ใช้วัดทุกครั้ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16553288","locator":"85(3):550-5","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The HU measurements averaged 72.44 at time zero and 59.99 at 7 wk. At 7 wk for all devices, HU values decreased 6 units with increased temperature (P < 0.05). ... Thus, it is recommended that egg testing temperature be reported when HU are"}}]}},"milk-meat-hygiene--milk-overview":{"milk-meat-hygiene--milk-overview--การสร้างน้ำนม-การหลั่งน้ำนม-และการรีด":{"claims":[{"id":"milk-meat-hygiene--milk-overview--การสร้างน้ำนม-การหลั่งน้ำนม-และการรีด--v1","statement":"น้ำนมที่เก็บอยู่ในเต้ามากกว่าร้อยละ 80 คือส่วน alveolar ซึ่งจะรีดออกได้ก็ต่อเมื่อเกิด milk ejection จากการหลั่ง oxytocin และการหดตัวของ myoepithelium โดยถูกกระตุ้นด้วยการสัมผัสหัวนม ยืนยันกลไกที่สไลด์อธิบาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15998500","locator":"Abstract; 29(2):268-273","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"More than 80% of the milk stored in the udder, i.e. the alveolar fraction, only available after milk ejection is induced by the release of oxytocin and myoepithelial contraction. Milk ejection is induced by tactile teat stimulation, either "}}]},"milk-meat-hygiene--milk-overview--นมในฐานะอาหาร-และทำไมนมมีสีขาว":{"claims":[{"id":"milk-meat-hygiene--milk-overview--นมในฐานะอาหาร-และทำไมนมมีสีขาว--v1","statement":"สีขาวของ skim milk เกิดจากการกระเจิงแสง (light scattering) ของ casein micelles ซึ่งมีขนาดระดับคอลลอยด์ และความขุ่นของน้ำนมโดยรวมเกิดจากอนุภาคแขวนลอยของไขมัน โปรตีน และแร่ธาตุบางชนิด ตรงกับคำอธิบายในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-tetra-pak-processing-s-1995","locator":"บท Chemistry of Milk หัวข้อ casein micelles และ appearance ของฉบับออนไลน์ dairyprocessinghandbook.tetrapak.com","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Since the micelles are of colloidal dimensions, they are capable of scattering light and the white colour of skim milk is largely due to light scattering by the casein micelles."}}]},"milk-meat-hygiene--milk-overview--กายวิภาคเต้านมโค-และ-suspensory-system":{"claims":[{"id":"milk-meat-hygiene--milk-overview--กายวิภาคเต้านมโค-และ-suspensory-system--v1","statement":"ในแม่โคที่ผ่านการให้ลูกหลายครั้ง ปริมาณน้ำนม (colostrum yield) ต่อ quarter ของเต้าคู่หลังสูงกว่าเต้าคู่หน้าอย่างมีนัยสำคัญ (p < 0.05) จึงสนับสนุนทิศทางของสไลด์ที่ว่าเต้าคู่หลังให้น้ำนมมากกว่า แม้เอกสารนี้จะไม่ได้ระบุสัดส่วน 50 ถึง 60 เปอร์เซ็นต์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27136032","locator":"Results; 94(4):1755-60","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"quarter colostrum yield in multiparous cows was higher in rear quarters than in front quarters ( < 0.05)"}},{"id":"milk-meat-hygiene--milk-overview--กายวิภาคเต้านมโค-และ-suspensory-system--v2","statement":"central suspensory ligament (เอ็นพยุงกลาง) ถูกจัดเป็นหนึ่งใน 5 ลักษณะโครงสร้างเต้านมหลักที่ประเมินและถ่ายทอดทางพันธุกรรมในโคนม ร่วมกับ anterior udder attachment, posterior udder attachment height, posterior udder attachment width และ udder depth ซึ่งยืนยันว่าเอ็นพยุงกลางเป็นโครงสร้างพยุงเต้านมที่สำคัญจริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36230283","locator":"Abstract, traits studied; 12(19):2542","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"we conducted a genome-wide association study for five udder traits, including anterior udder attachment (AUA), central suspensory ligament (CSL), posterior udder attachment height (PUAH), posterior udder attachment width (PUAW), and udder d"}}]},"milk-meat-hygiene--milk-overview--โครงสร้างภายใน-หลอดเลือด-น้ำเหลือง-ประสาท":{"claims":[{"id":"milk-meat-hygiene--milk-overview--โครงสร้างภายใน-หลอดเลือด-น้ำเหลือง-ประสาท--v1","statement":"การสร้างน้ำนมต้องใช้เลือดไหลผ่านเต้านมในปริมาณมหาศาล โดยวัดได้ 3.6 ถึง 4.9 ลิตรต่อนาทีสำหรับครึ่งเต้า และเต้านมทั้งเต้ารับเลือดคิดเป็นราว 19 เปอร์เซ็นต์ของ cardiac output อีกทั้งอัตราส่วนของ blood flow ต่อ milk yield ไม่เปลี่ยนแปลงแม้จะเร่งการสร้างน้ำนมด้วยฮอร์โมน แสดงว่าอัตราส่วนนี้เป็นค่าคงตัวทางสรีรวิทยา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3366719","locator":"Results; 66(1):70-9","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The proportion of cardiac output perfusing the (whole) udder increased to 19.1% (T4) and 18.7% (GH) ... Ratio of blood flow to milk yield was not changed by either treatment."}},{"id":"milk-meat-hygiene--milk-overview--โครงสร้างภายใน-หลอดเลือด-น้ำเหลือง-ประสาท--v2","statement":"rosette of Furstenberg เป็นโครงสร้างที่รอยต่อระหว่าง teat cistern กับ streak canal ซึ่งควบคุมทางออกของน้ำนม รอยโรคที่ตำแหน่งนี้หรือที่ streak canal ทำให้น้ำนมไหลออกผิดปกติและต้องรักษาด้วยการผ่าตัดแบบ theloscopy","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27719769","locator":"Abstract; 32(3):813-832","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Milk outflow impairment originating from the rosette of Fürstenberg or the streak canal is best treated using minimally invasive surgery (theloscopy)."}}]}}};
